insert into public.hadith_translations (hadith_id, locale, text, attribution)
select h.id, 'en', v.text, v.attribution
from (values
('nawawi:37', 'On the authority of Ibn Abbas (may Allah be pleased with him), from the Messenger of Allah (peace and blessings of Allah be upon him), from what he has related from his Lord: Verily Allah ta’ala has written down the good deeds and the evil deeds, and then explained it [by saying]: “Whosoever intended to perform a good deed, but did not do it, then Allah writes it down with Himself as a complete good deed. And if he intended to perform it and then did perform it, then Allah writes it down with Himself as from ten good deeds up to seven hundred times, up to many times multiplied. And if he intended to perform an evil deed, but did not do it, then Allah writes it down with Himself as a complete good deed. And if he intended it [i.e., the evil deed] and then performed it, then Allah writes it down as one evil deed.” [Al-Bukhari] [Muslim]', '40 Hadith Nawawi, Hadith 37'),
('bukhari:6592', 'Haritha said that he heard the Prophet saying that his Lake-Fount would be as large as the distance between Sana'' and Medina. Al- Mustaurid said to Haritha, "Didn''t you hear him talking about the vessels?" He said, "No." Al- Mustaurid said, "The vessels are seen in it as (numberless as) the stars', 'Sahih al-Bukhari 6592'),
('qudsi:7', 'On the authority of Uqbah ibn Amir (may Allah be pleased with him), who said: I heard the messenger of Allah (ﷺ) say: Your Lord delights at a shepherd who, on the peak of a mountain crag, gives the call to prayer and prays. Then Allah (glorified and exalted be He) say: Look at this servant of Mine, he gives the call to prayer and performs the prayers; he is in awe of Me. I have forgiven My servant [his sins] and have admitted him to Paradise. It was related by an-Nasa''i with a good chain of authorities', '40 Hadith Qudsi, Hadith 7'),
('bukhari:6525', 'Narrated Ibn `Abbas:I heard Allah''s Messenger (ﷺ) while he was delivering a sermon on a pulpit, saying, "You will meet Allah barefooted, naked, and uncircumcised', 'Sahih al-Bukhari 6525'),
('bukhari:80', 'Narrated Anas:Allah''s Messenger (ﷺ) said, "From among the portents of the Hour are (the following): -1. Religious knowledge will be taken away (by the death of Religious learned men). -2. (Religious) ignorance will prevail. -3. Drinking of Alcoholic drinks (will be very common). -4. There will be prevalence of open illegal sexual intercourse', 'Sahih al-Bukhari 80'),
('bukhari:105', 'Narrated Abu Bakra:The Prophet (ﷺ) said, "No doubt your blood, property, the sub-narrator Muhammad thought that Abu Bakra had also mentioned and your honor (chastity), are sacred to one another as is the sanctity of this day of yours in this month of yours. It is incumbent on those who are present to inform those who are absent." (Muhammad the Sub-narrator used to say, "Allah''s Messenger (ﷺ) told the truth.") The Prophet (ﷺ) repeated twice: "No doubt! Haven''t I conveyed Allah''s message to you', 'Sahih al-Bukhari 105'),
('qudsi:32', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: A man sinned greatly against himself, and when death came to him he charged his sons, saying: When I have died, burn me, then crush me and scatter [my ashes] into the sea, for, by Allah, if my Lord takes possession of me, He will punish me in a manner in which He has punished no one [else]. So they did that to him. Then He said to the earth: Produce what you have taken-and there he was! And He said to him: What induced you to do what you did? He said: Being afraid of You, O my Lord (or he said: Being frightened of You) and because of that He forgave him. It was related by Muslim (also by al-Bukhari, an-Nasa''i and Ibn Majah)', '40 Hadith Qudsi, Hadith 32'),
('nawawi:33', 'On the authority of Ibn Abbas (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: Were people to be given everything that they claimed, men would [unjustly] claim the wealth and lives of [other] people. But, the onus of proof is upon the claimant, and the taking of an oath is upon him who denies. A hasan hadeeth narrated by al-Baihaqee and others in this form, and part of it is in the two Saheehs', '40 Hadith Nawawi, Hadith 33'),
('bukhari:93', 'Narrated Anas bin Malik:One day Allah''s Messenger (ﷺ) came out (before the people) and `Abdullah bin Hudhafa stood up and asked (him) "Who is my father?" The Prophet (ﷺ) replied, "Your father is Hudhafa." The Prophet (ﷺ) told them repeatedly (in anger) to ask him anything they liked. `Umar knelt down before the Prophet (ﷺ) and said thrice, "We accept Allah as (our) Lord and Islam as (our) religion and Muhammad as (our) Prophet." After that the Prophet (ﷺ) became silent', 'Sahih al-Bukhari 93'),
('bukhari:6539', 'Narrated `Adi bin Hatim:The Prophet (ﷺ) said, "There will be none among you but will be talked to by Allah on the Day of Resurrection, without there being an interpreter between him and Him (Allah) . He will look and see nothing ahead of him, and then he will look (again for the second time) in front of him, and the (Hell) Fire will confront him. So, whoever among you can save himself from the Fire, should do so even with one half of a date (to give in charity)', 'Sahih al-Bukhari 6539'),
('bukhari:83', 'Narrated `Abdullah bin `Amr bin Al `Aas:Allah''s Messenger (ﷺ) stopped (for a while near the Jimar) at Mina during his last Hajj for the people and they were asking him questions. A man came and said, "I forgot and got my head shaved before slaughtering the Hadi (sacrificing animal)." The Prophet (ﷺ) said, "There is no harm, go and do the slaughtering now." Then another person came and said, "I forgot and slaughtered (the camel) before Rami (throwing of the pebbles) at the Jamra." The Prophet (ﷺ) said, "Do the Rami now and there is no harm." The narrator added: So on that day, when the Prophet (ﷺ) was asked about anything (as regards the ceremonies of Hajj) performed before or after its due time, his reply was: "Do it (now) and there is no harm', 'Sahih al-Bukhari 83'),
('bukhari:6436', 'Narrated Ibn `Abbas:I heard the Prophet (ﷺ) saying, "If the son of Adam (the human being) had two valleys of money, he would wish for a third, for nothing can fill the belly of Adam''s son except dust, and Allah forgives him who repents to Him', 'Sahih al-Bukhari 6436'),
('bukhari:6473', 'Narrated Warrad:(the clerk of Al-Mughira bin Shu`ba) Muawiya wrote to Al-Mughira: "Write to me a narration you have heard from Allah''s Messenger (ﷺ)." So Al-Mughira wrote to him, "I heard him saying the following after each prayer: ''La ilaha illal-lahu wahdahu la sharika lahu, lahu-l-mulk wa lahuI-hamd, wa huwa ''ala kulli Shai-in qadir.'' He also used to forbid idle talk, asking too many questions (in religion), wasting money, preventing what should be given, and asking others for something (except in great need), being undutiful to mothers, and burying one''s little daughters (alive)', 'Sahih al-Bukhari 6473'),
('bukhari:6530', 'Narrated Abu Sa`id:The Prophet (ﷺ) said, "Allah will say, ''O Adam!. Adam will reply, ''Labbaik and Sa`daik (I respond to Your Calls, I am obedient to Your orders), wal Khair fi Yadaik (and all the good is in Your Hands)!'' Then Allah will say (to Adam), Bring out the people of the Fire.'' Adam will say, ''What (how many) are the people of the Fire?'' Allah will say, ''Out of every thousand (take out) nine hundred and ninety-nine (persons).'' At that time children will become hoary-headed and every pregnant female will drop her load (have an abortion) and you will see the people as if they were drunk, yet not drunk; But Allah''s punishment will be very severe." That news distressed the companions of the Prophet (ﷺ) too much, and they said, "O Allah''s Messenger (ﷺ)! Who amongst us will be that man (the lucky one out of one-thousand who will be saved from the Fire)?" He said, "Have the good news that one-thousand will be from Gog and Magog, and the one (to be saved will be) from you." The Prophet (ﷺ) added, "By Him in Whose Hand my soul is, I Hope that you (Muslims) will be one third of the people of Paradise." On that, we glorified and praised Allah and said, "Allahu Akbar." The Prophet (ﷺ) then said, "By Him in Whose Hand my soul is, I hope that you will be one half of the people of Paradise, as your (Muslims) example in comparison to the other people (non-Muslims), is like that of a white hair on the skin of a black ox, or a round hairless spot on the foreleg of a donkey', 'Sahih al-Bukhari 6530'),
('bukhari:76', 'Narrated Ibn `Abbas:Once I came riding a she-ass and had (just) attained the age of puberty. Allah''s Messenger (ﷺ) was offering the prayer at Mina. There was no wall in front of him and I passed in front of some of the row while they were offering their prayers. There I let the she-ass loose to graze and entered the row, and nobody objected to it', 'Sahih al-Bukhari 76'),
('bukhari:42', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "If any one of you improves (follows strictly) his Islamic religion then his good deeds will be rewarded ten times to seven hundred times for each good deed and a bad deed will be recorded as it is', 'Sahih al-Bukhari 42'),
('bukhari:6506', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "The Hour will not be established till the sun rises from the west, and when it rises (from the west) and the people see it, then all of them will believe (in Allah). But that will be the time when ''No good it will do to a soul to believe then. If it believed not before.."'' (6.158) The Hour will be established (so suddenly) that two persons spreading a garment between them will not be able to finish their bargain, nor will they be able to fold it up. The Hour will be established while a man is carrying the milk of his she-camel, but cannot drink it; and the Hour will be established when someone is not able to prepare the tank to water his livestock from it; and the Hour will be established when some of you has raised his food to his mouth but cannot eat it', 'Sahih al-Bukhari 6506'),
('nawawi:21', 'On the authority of Abu `Amr — and he is also called Abu `Amrah — Sufyan bin Abdullah ath- Thaqafee (may Allah be pleased with him) who said: I said, "O Messenger of Allah, tell me something about al-Islam which I can ask of no one but you." He (peace and blessings of Allah be upon him) said, "Say I believe in Allah — and then be steadfast." [Muslim]', '40 Hadith Nawawi, Hadith 21'),
('bukhari:6572', 'Narrated `Abbas:that he said to the Prophet (ﷺ) "Did you benefit Abu Talib with anything?', 'Sahih al-Bukhari 6572'),
('bukhari:6523', 'Narrated Anas bin Malik:A man said, "O Allah''s Prophet! Will a Kafir (disbeliever) be gathered (driven prone) on his face?" The Prophet (ﷺ) said, "Is not He Who made him walk with his legs in this world, able to make him walk on his face on the Day of Resurrection?" (Qatada, a sub-narrator said: Yes, (He can), by the Power of Our Lord', 'Sahih al-Bukhari 6523'),
('bukhari:61', 'Narrated Ibn `Umar:Allah''s Messenger (ﷺ) said, "Amongst the trees, there is a tree, the leaves of which do not fall and is like a Muslim. Tell me the name of that tree." Everybody started thinking about the trees of the desert areas. And I thought of the date-palm tree but felt shy to answer the others then asked, "What is that tree, O Allah''s Messenger (ﷺ) ?" He replied, "It is the date-palm tree', 'Sahih al-Bukhari 61'),
('bukhari:128', 'Narrated Anas bin Malik:"Once Mu`adh was along with Allah''s Messenger (ﷺ) as a companion rider. Allah''s Messenger (ﷺ) said, "O Mu`adh bin Jabal." Mu`adh replied, "Labbaik and Sa`daik. O Allah''s Messenger (ﷺ)!" Again the Prophet (ﷺ) said, "O Mu`adh!" Mu`adh said thrice, "Labbaik and Sa`daik, O Allah''s Messenger (ﷺ)!" Allah''s Messenger (ﷺ) said, "There is none who testifies sincerely that none has the right to be worshipped but Allah and Muhammad is his Apostle, except that Allah, will save him from the Hell-fire." Mu`adh said, "O Allah''s Messenger (ﷺ) ! Should I not inform the people about it so that they may have glad tidings?" He replied, "When the people hear about it, they will solely depend on it." Then Mu`adh narrated the above-mentioned Hadith just before his death, being afraid of committing sin (by not telling the knowledge)', 'Sahih al-Bukhari 128'),
('bukhari:6502', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "Allah said, ''I will declare war against him who shows hostility to a pious worshipper of Mine. And the most beloved things with which My slave comes nearer to Me, is what I have enjoined upon him; and My slave keeps on coming closer to Me through performing Nawafil (praying or doing extra deeds besides what is obligatory) till I love him, so I become his sense of hearing with which he hears, and his sense of sight with which he sees, and his hand with which he grips, and his leg with which he walks; and if he asks Me, I will give him, and if he asks My protection (Refuge), I will protect him; (i.e. give him My Refuge) and I do not hesitate to do anything as I hesitate to take the soul of the believer, for he hates death, and I hate to disappoint him', 'Sahih al-Bukhari 6502'),
('nawawi:3', 'On the authority of Abdullah, the son of Umar ibn al-Khattab (ra), who said: I heard the Messenger of Allah (ﷺ) say, "Islam has been built on five [pillars]: testifying that there is no deity worthy of worship except Allah and that Muhammad is the Messenger of Allah, establishing the salah (prayer), paying the zakat (obligatory charity), making the hajj (pilgrimage) to the House, and fasting in Ramadhan." [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 3'),
('bukhari:63', 'Narrated Anas bin Malik:While we were sitting with the Prophet (ﷺ) in the mosque, a man came riding on a camel. He made his camel kneel down in the mosque, tied its foreleg and then said: "Who amongst you is Muhammad?" At that time the Prophet (ﷺ) was sitting amongst us (his companions) leaning on his arm. We replied, "This white man reclining on his arm." The man then addressed him, "O Son of `Abdul Muttalib." The Prophet (ﷺ) said, "I am here to answer your questions." The man said to the Prophet, "I want to ask you something and will be hard in questioning. So do not get angry." The Prophet (ﷺ) said, "Ask whatever you want." The man said, "I ask you by your Lord, and the Lord of those who were before you, has Allah sent you as an Apostle to all the mankind?" The Prophet (ﷺ) replied, "By Allah, yes." The man further said, "I ask you by Allah. Has Allah ordered you to offer five prayers in a day and night (24 hours)? He replied, "By Allah, Yes." The man further said, "I ask you by Allah! Has Allah ordered you to observe fasts during this month of the year (i.e. Ramadan)?" He replied, "By Allah, Yes." The man further said, "I ask you by Allah. Has Allah ordered you to take Zakat (obligatory charity) from our rich people and distribute it amongst our poor people?" The Prophet (ﷺ) replied, "By Allah, yes." Thereupon that man said, "I have believed in all that with which you have been sent, and I have been sent by my people as a messenger, and I am Dimam bin Tha`laba from the brothers of Bani Sa`d bin Bakr', 'Sahih al-Bukhari 63'),
('bukhari:6412', 'Narrated Ibn `Abbas:The Prophet (ﷺ) said: "There are two blessings that many people are deceived into losing: health and free time', 'Sahih al-Bukhari 6412'),
('bukhari:131', 'Narrated `Abdullah bin `Umar:Once Allah''s Messenger (ﷺ) said, "Amongst the trees there is a tree, the leaves of which do not fall and is like a Muslim, tell me the name of that tree." Everybody started thinking about the trees of the desert areas and I thought of the date-palm tree but felt shy (to answer). The others asked, "O Allah''s Apostle! inform us of it." He replied, "It is the date-palm tree." I told my father what had come to my mind and on that he said, "Had you said it I would have preferred it to such and such a thing that I might possess', 'Sahih al-Bukhari 131'),
('bukhari:99', 'Narrated Abu Huraira:I said: "O Allah''s Messenger (ﷺ)! Who will be the luckiest person, who will gain your intercession on the Day of Resurrection?" Allah''s Messenger (ﷺ) said: "O Abu Huraira! I have thought that none will ask me about it before you as I know your longing for the (learning of) Hadiths. The luckiest person who will have my intercession on the Day of Resurrection will be the one who said sincerely from the bottom of his heart "None has the right to be worshipped but Allah', 'Sahih al-Bukhari 99'),
('bukhari:6515', 'Narrated Ibn `Umar:Allah''s Messenger (ﷺ) said, "When anyone of you dies, his destination is displayed before him in the forenoon and in the afternoon, either in the (Hell) Fire or in Paradise, and it is said to him, "That is your place till you are resurrected and sent to it', 'Sahih al-Bukhari 6515'),
('bukhari:6574', 'Narrated ''Ata (while Abu Huraira was narrating (see previous hadith)):Abu Sa`id was sitting in the company of Abu Huraira and he did not deny anything of his narration till he reached his saying: "All this and as much again therewith are for you." Then Abu Sa`id said, "I heard Allah''s Messenger (ﷺ) saying, ''This is for you and ten times as much.'' " Abu Huraira said, "In my memory it is ''as much again therewith', 'Sahih al-Bukhari 6574'),
('bukhari:6522', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "The people will be gathered in three ways: (The first way will be of) those who will wish or have a hope (for Paradise) and will have a fear (of punishment), (The second batch will be those who will gather) riding two on a camel or three on a camel or ten on a camel. (The third batch) the rest of the people will be urged to gather by the Fire which will accompany them at the time of their afternoon nap and stay with them where they will spend the night, and will be with them in the morning wherever they may be then, and will be with them in the afternoon wherever they may be then', 'Sahih al-Bukhari 6522'),
('bukhari:6508', 'Narrated Abu Musa:The Prophet (ﷺ) said: "Whoever loves to meet Allah, Allah loves to meet him; and whoever hates to meet Allah, Allah hates to meet him', 'Sahih al-Bukhari 6508'),
('bukhari:6549', 'Narrated Abu Sa`id Al-Khudri:Allah''s Messenger (ﷺ) said, "Allah will say to the people of Paradise, ''O the people of Paradise!'' They will say, ''Labbaik, O our Lord, and Sa`daik!'' Allah will say, ''Are you pleased?" They will say, ''Why should we not be pleased since You have given us what You have not given to anyone of Your creation?'' Allah will say, ''I will give you something better than that.'' They will reply, ''O our Lord! And what is better than that?'' Allah will say, ''I will bestow My pleasure and contentment upon you so that I will never be angry with you after for-ever', 'Sahih al-Bukhari 6549'),
('qudsi:17', 'On the authority of Abu Dharr al-Ghifari (may Allah be pleased with him) from the Prophet (ﷺ) is that among the sayings he relates from his Lord (may He be glorified) is that He said: O My servants, I have forbidden oppression for Myself and have made it forbidden amongst you, so do not oppress one another. O My servants, all of you are astray except for those I have guided, so seek guidance of Me and I shall guide you, O My servants, all of you are hungry except for those I have fed, so seek food of Me and I shall feed you. O My servants, all of you are naked except for those I have clothed, so seek clothing of Me and I shall clothe you. O My servants, you sin by night and by day, and I forgive all sins, so seek forgiveness of Me and I shall forgive you. O My servants, you will not attain harming Me so as to harm Me, and will not attain benefitting Me so as to benefit Me. O My servants, were the first of you and the last of you, the human of you and the jinn of you to be as pious as the most pious heart of any one man of you, that would not increase My kingdom in anything. O My servants, were the first of you and the last of you, the human of you and the jinn of you to be as wicked as the most wicked heart of any one man of you, that would not decrease My kingdom in anything. O My servants, were the first of you and the last of you, the human of you and the jinn of you to rise up in one place and make a request of Me, and were I to give everyone what he requested, that would not decrease what I have, any more that a needle decreases the sea if put into it. O My servants, it is but your deeds that I reckon up for you and then recompense you for, so let him who finds good, praise Allah, and let him who finds other than that, blame no one but himself. It was related by Muslim (also by at-Tirmidhi and Ibn Majah)', '40 Hadith Qudsi, Hadith 17'),
('bukhari:6585', 'Abu Huraira narrated that the Prophet (ﷺ) said:"On the Day of Resurrection a group of companions will come to me, but will be driven away from the Lake-Fount, and I will say, ''O Lord (those are) my companions!'' It will be said, ''You have no knowledge as to what they innovated after you left; they turned apostate as renegades (reverted from Islam)', 'Sahih al-Bukhari 6585'),
('bukhari:6526', 'Narrated Ibn `Abbas:The Prophet (ﷺ) stood up among us and addressed (saying) "You will be gathered, barefooted, naked, and uncircumcised (as Allah says): ''As We began the first creation, We shall repeat it..'' (21.104) And the first human being to be dressed on the Day of Resurrection will be (the Prophet) Abraham Al-Khalil. Then will be brought some men of my followers who will be taken towards the left (i.e., to the Fire), and I will say: ''O Lord! My companions whereupon Allah will say: You do not know what they did after you left them. I will then say as the pious slave, Jesus said, And I was witness over them while I dwelt amongst them..........(up to) ...the All-Wise.'' (5.117-118). The narrator added: Then it will be said that those people (relegated from Islam, that is) kept on turning on their heels (deserted Islam)', 'Sahih al-Bukhari 6526'),
('bukhari:51', 'Narrated ''Abdullah bin ''Abbas: I was informed by Abu Sufyan that Heraclius said to him, "I asked you whether they (followers of Muhammad) were increasing or decreasing. You replied that they were increasing. And in fact, this is the way of true Faith till it is complete in all respects. I further asked you whether there was anybody, who, after embracing his (the Prophets) religion (Islam) became displeased and discarded it. You replied in the negative, and in fact, this is (a sign of) true faith. When its delight enters the heart and mixes with them completely, nobody can be displeased with it', 'Sahih al-Bukhari 51'),
('bukhari:37', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said: "Whoever establishes prayers during the nights of Ramadan faithfully out of sincere faith and hoping to attain Allah''s rewards (not for showing off), all his past sins will be forgiven', 'Sahih al-Bukhari 37'),
('bukhari:6566', 'Narrated `Imran bin Husain:The Prophet (ﷺ) said, "Some people will be taken out of the Fire through the intercession of Muhammad they will enter Paradise and will be called Al-Jahannamiyin (the Hell Fire people)', 'Sahih al-Bukhari 6566'),
('bukhari:6575', 'Narrated `Abdullah:The Prophet (ﷺ) said, "I am your predecessor at the Lake-Fount', 'Sahih al-Bukhari 6575'),
('nawawi:22', 'On the authority of Abu Abdullah Jabir bin Abdullah al-Ansaree (may Allah be pleased with him) that: A man questioned the Messenger of Allah (peace and blessings of Allah be upon him) and said, “Do you think that if I perform the obligatory prayers, fast in Ramadhan, treat as lawful that which is halal, and treat as forbidden that which is haram, and do not increase upon that [in voluntary good deeds], then I shall enter Paradise?” He (peace and blessings of Allah be upon him) replied, “Yes.” [Muslim]', '40 Hadith Nawawi, Hadith 22'),
('nawawi:35', 'On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Do not envy one another, and do not inflate prices for one another, and do not hate one another, and do not turn away from one another, and do not undercut one another in trade, but [rather] be slaves of Allah and brothers [amongst yourselves]. A Muslim is the brother of a Muslim: he does not oppress him, nor does he fail him, nor does he lie to him, nor does he hold him in contempt. Taqwa (piety) is right here [and he pointed to his chest three times]. It is evil enough for a man to hold his brother Muslim in contempt. The whole of a Muslim is inviolable for another Muslim: his blood, his property, and his honour.” [Muslim]', '40 Hadith Nawawi, Hadith 35'),
('bukhari:101', 'Narrated Abu Sa`id Al-Khudri:Some women requested the Prophet (ﷺ) to fix a day for them as the men were taking all his time. On that he promised them one day for religious lessons and commandments. Once during such a lesson the Prophet said, "A woman whose three children die will be shielded by them from the Hell fire." On that a woman asked, "If only two die?" He replied, "Even two (will shield her from the Hell-fire)', 'Sahih al-Bukhari 101'),
('nawawi:40', 'On the authority of Abdullah ibn Umar (may Allah be pleased with him), who said: The Messenger of Allah (peace and blessings of Allah be upon him) took me by the shoulder and said, “Be in this world as though you were a stranger or a wayfarer.” And Ibn Umar (may Allah be pleased with him) used to say, “In the evening do not expect [to live until] the morning, and in the morning do not expect [to live until] the evening. Take [advantage of] your health before times of sickness, and [take advantage of] your life before your death.” [Al-Bukhari]', '40 Hadith Nawawi, Hadith 40'),
('nawawi:7', 'On the authority of Tameem ibn Aus ad-Daree (ra): The Prophet (ﷺ) said, “The deen (religion) is naseehah (advice, sincerity).” We said, “To whom?” He (ﷺ) said, “To Allah, His Book, His Messenger, and to the leaders of the Muslims and their common folk.” [Muslim]', '40 Hadith Nawawi, Hadith 7'),
('bukhari:6439', 'Narrated Anas bin Malik:Allah''s Messenger (ﷺ) said, "If Adam''s son had a valley full of gold, he would like to have two valleys, for nothing fills his mouth except dust. And Allah forgives him who repents to Him', 'Sahih al-Bukhari 6439'),
('bukhari:6475', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "Whoever believes in Allah and the Last Day should talk what is good or keep quiet, and whoever believes in Allah and the Last Day should not hurt (or insult) his neighbor; and whoever believes in Allah and the Last Day, should entertain his guest generously', 'Sahih al-Bukhari 6475'),
('nawawi:12', 'On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Part of the perfection of one’s Islam is his leaving that which does not concern him.” A hasan (good) hadeeth which was related by at-Tirmidhi and others in this fashion', '40 Hadith Nawawi, Hadith 12'),
('bukhari:102', 'Narrated Abu Sa`id Al-Khudri:as above (the sub narrators are different). Abu Huraira qualified the three children referred to in the above mentioned Hadith as not having reached the age of committing sins (i.e. age of puberty)', 'Sahih al-Bukhari 102'),
('bukhari:6441', 'Narrated Hakim bin Hizam:I asked the Prophet (for some money) and he gave me, and then again I asked him and he gave me, and then again I asked him and he gave me and he then said, "This wealth is (like) green and sweet (fruit), and whoever takes it without greed, Allah will bless it for him, but whoever takes it with greed, Allah will not bless it for him, and he will be like the one who eats but is never satisfied. And the upper (giving) hand is better than the lower (taking) hand', 'Sahih al-Bukhari 6441'),
('bukhari:6462', 'Narrated `Aisha:The most beloved action to Allah''s Messenger (ﷺ) was that whose doer did it continuously and regularly', 'Sahih al-Bukhari 6462'),
('bukhari:6483', 'Narrated Abu Huraira:I heard Allah''s Messenger (ﷺ) saying, "My example and the example of the people is that of a man who made a fire, and when it lighted what was around it, Moths and other insects started falling into the fire. The man tried (his best) to prevent them, (from falling in the fire) but they overpowered him and rushed into the fire. The Prophet (ﷺ) added: Now, similarly, I take hold of the knots at your waist (belts) to prevent you from falling into the Fire, but you insist on falling into it', 'Sahih al-Bukhari 6483'),
('bukhari:34', 'Narrated ''Abdullah bin ''Amr: The Prophet (ﷺ) said, "Whoever has the following four (characteristics) will be a pure hypocrite and whoever has one of the following four characteristics will have one characteristic of hypocrisy unless and until he gives it up. 1. Whenever he is entrusted, he betrays. 2. Whenever he speaks, he tells a lie. 3. Whenever he makes a covenant, he proves treacherous. 4. Whenever he quarrels, he behaves in a very imprudent, evil and insulting manner', 'Sahih al-Bukhari 34'),
('bukhari:6544', 'Narrated Ibn `Umar:The Prophet; said, "The people of Paradise will enter Paradise, and the people of the (Hell) Fire will enter the (Hell) Fire: then a call-maker will get up (and make an announcement) among them, ''O the people of the (Hell) Fire! No death anymore ! And O people of Paradise! No death (anymore) but Eternity', 'Sahih al-Bukhari 6544'),
('bukhari:6528', 'Narrated `Abdullah:While we were in the company of the Prophet (ﷺ) in a tent he said, ''''Would it please you to be one fourth of the people of Paradise?" We said, "Yes." He said, "Would It please you to be one-third of the people of Paradise?" We said, "Yes." He said, "Would it please you to be half of the people of Paradise?" We said, "Yes." Thereupon he said, "I hope that you will be one half of the people of Paradise, for none will enter Paradise but a Muslim soul, and you people, in comparison to the people who associate others in worship with Allah, are like a white hair on the skin of a black ox, or a black hair on the skin of a red ox', 'Sahih al-Bukhari 6528'),
('bukhari:10', 'Narrated ''Abdullah bin ''Amr: The Prophet (ﷺ) said, "A Muslim is the one who avoids harming Muslims with his tongue and hands. And a Muhajir (emigrant) is the one who gives up (abandons) all what Allah has forbidden', 'Sahih al-Bukhari 10'),
('bukhari:46', 'Narrated Talha bin ''Ubaidullah: A man from Najd with unkempt hair came to Allah''s Messenger (ﷺ) and we heard his loud voice but could not understand what he was saying, till he came near and then we came to know that he was asking about Islam. Allah''s Messenger (ﷺ) said, "You have to offer prayers perfectly five times in a day and night (24 hours)." The man asked, "Is there any more (praying)?" Allah''s Messenger (ﷺ) replied, "No, but if you want to offer the Nawafil prayers (you can)." Allah''s Messenger (ﷺ) further said to him: "You have to observe fasts during the month of Ramadan." The man asked, "Is there any more fasting?" Allah''s Messenger (ﷺ) replied, "No, but if you want to observe the Nawafil fasts (you can.)" Then Allah''s Messenger (ﷺ) further said to him, "You have to pay the Zakat (obligatory charity)." The man asked, "Is there any thing other than the Zakat for me to pay?" Allah''s Messenger (ﷺ) replied, "No, unless you want to give alms of your own." And then that man retreated saying, "By Allah! I will neither do less nor more than this." Allah''s Messenger (ﷺ) said, "If what he said is true, then he will be successful (i.e. he will be granted Paradise)', 'Sahih al-Bukhari 46'),
('bukhari:96', 'Narrated `Abdullah bin `Amr:Once Allah''s Messenger (ﷺ) remained behind us in a journey. He joined us while we were performing ablution for the `Asr prayer which was over-due. We were just passing wet hands over our feet (not washing them properly) so the Prophet (ﷺ) addressed us in a loud voice and said twice or thrice, "Save your heels from the fire', 'Sahih al-Bukhari 96'),
('bukhari:6582', 'Narrated Anas:The Prophet (ﷺ) said, "Some of my companions will come to me at my Lake Fount, and after I recognize them, they will then be taken away from me, whereupon I will say, ''My companions!'' Then it will be said, ''You do not know what they innovated (new things) in the religion after you', 'Sahih al-Bukhari 6582'),
('bukhari:6505', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "I have been sent and the Hour (is at hand) as these two (fingers)', 'Sahih al-Bukhari 6505'),
('bukhari:6424', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "Allah says, ''I have nothing to give but Paradise as a reward to my believer slave, who, if I cause his dear friend (or relative) to die, remains patient (and hopes for Allah''s Reward)', 'Sahih al-Bukhari 6424'),
('bukhari:6443', 'Narrated Abu Dhar:Once I went out at night and found Allah''s Messenger (ﷺ) walking all alone accompanied by nobody, and I thought that perhaps he disliked that someone should accompany him. So I walked in the shade, away from the moonlight, but the Prophet (ﷺ) looked behind and saw me and said, "Who is that?" I replied, "Abu Dhar, let Allah get me sacrificed for you!" He said, "O Abu Dhar, come here!" So I accompanied him for a while and then he said, "The rich are in fact the poor (little rewarded) on the Day of Resurrection except him whom Allah gives wealth which he gives (in charity) to his right, left, front and back, and does good deeds with it. I walked with him a little longer. Then he said to me, "Sit down here." So he made me sit in an open space surrounded by rocks, and said to me, "Sit here till I come back to you." He went towards Al-Harra till I could not see him, and he stayed away for a long period, and then I heard him saying, while he was coming, "Even if he had committed theft, and even if he had committed illegal sexual intercourse?" When he came, I could not remain patient and asked him, "O Allah''s Prophet! Let Allah get me sacrificed for you! Whom were you speaking to by the side of Al-Harra? I did not hear anybody responding to your talk." He said, "It was Gabriel who appeared to me beside Al-Harra and said, ''Give the good news to your followers that whoever dies without having worshipped anything besides Allah, will enter Paradise.'' I said, ''O Gabriel! Even if he had committed theft or committed illegal sexual intercourse?'' He said, ''Yes.'' I said, ''Even if he has committed theft or committed illegal sexual intercourse?'' He said, ''Yes.'' I said, ''Even if he has committed theft or committed illegal sexual intercourse?'' He said, ''Yes', 'Sahih al-Bukhari 6443'),
('bukhari:6465', 'Narrated `Aisha:The Prophet (ﷺ) was asked, "What deeds are loved most by Allah?" He said, "The most regular constant deeds even though they may be few." He added, ''Don''t take upon yourselves, except the deeds which are within your ability', 'Sahih al-Bukhari 6465'),
('bukhari:108', 'Narrated Anas:The fact which stops me from narrating a great number of Hadiths to you is that the Prophet (ﷺ) said: "Whoever tells a lie against me intentionally, then (surely) let him occupy his seat in Hell-fire', 'Sahih al-Bukhari 108'),
('bukhari:114', 'Narrated ''Ubaidullah bin `Abdullah:Ibn `Abbas said, "When the ailment of the Prophet (ﷺ) became worse, he said, ''Bring for me (writing) paper and I will write for you a statement after which you will not go astray.'' But `Umar said, ''The Prophet is seriously ill, and we have got Allah''s Book with us and that is sufficient for us.'' But the companions of the Prophet (ﷺ) differed about this and there was a hue and cry. On that the Prophet (ﷺ) said to them, ''Go away (and leave me alone). It is not right that you should quarrel in front of me." Ibn `Abbas came out saying, "It was most unfortunate (a great disaster) that Allah''s Messenger (ﷺ) was prevented from writing that statement for them because of their disagreement and noise. (Note: It is apparent from this Hadith that Ibn `Abbas had witnessed the event and came out saying this statement. The truth is not so, for Ibn `Abbas used to say this statement on narrating the Hadith and he had not witnessed the event personally. See Fath Al-Bari Vol. 1, p.220 footnote.) (See Hadith No. 228, Vol)', 'Sahih al-Bukhari 114'),
('bukhari:74', 'Narrated Ibn `Abbas:That he differed with Hur bin Qais bin Hisn Al-Fazari regarding the companion of (the Prophet) Moses. Ibn `Abbas said that he was Al Khadir. Meanwhile, Ubai bin Ka`b passed by them and Ibn `Abbas called him, saying "My friend (Hur) and I have differed regarding Moses'' companion, whom Moses asked the way to meet. Have you heard the Prophet (ﷺ) mentioning something about him? He said, "Yes. I heard Allah''s Messenger (ﷺ) saying, "While Moses was sitting in the company of some Israelites, a man came and asked him. "Do you know anyone who is more learned than you? Moses replied: "No." So Allah sent the Divine Inspiration to Moses: ''Yes, Our slave Khadir (is more learned than you.)'' Moses asked (Allah) how to meet him (Khadir). So Allah made the fish as a sign for him and he was told that when the fish was lost, he should return (to the place where he had lost it) and there he would meet him (Al-Khadir). So Moses went on looking for the sign of the fish in the sea. The servant-boy of Moses said to him: Do you remember when we betook ourselves to the rock, I indeed forgot the fish, none but Satan made me forget to remember it. On that Moses said: ''That is what we have been seeking'' (18.64). So they went back retracing their footsteps, and found Khadir. (And) what happened further to them is narrated in the Holy Qur''an by Allah. (18.54 up to)', 'Sahih al-Bukhari 74'),
('bukhari:6447', 'Narrated Sahl bin Sa`d As-Sa`id:A man passed by Allah''s Messenger (ﷺ) and the Prophet (ﷺ) asked a man sitting beside him, "What is your opinion about this (passer-by)?" He replied, "This (passer-by) is from the noble class of people. By Allah, if he should ask for a lady''s hand in marriage, he ought to be given her in marriage, and if he intercedes for somebody, his intercession will be accepted. Allah''s Messenger (ﷺ) kept quiet, and then another man passed by and Allah''s Messenger (ﷺ) asked the same man (his companion) again, "What is your opinion about this (second) one?" He said, "O Allah''s Messenger (ﷺ)! This person is one of the poor Muslims. If he should ask a lady''s hand in marriage, no-one will accept him, and if he intercedes for somebody, no one will accept his intercession, and if he talks, no-one will listen to his talk." Then Allah''s Messenger (ﷺ) said, "This (poor man) is better than such a large number of the first type (i.e. rich men) as to fill the earth', 'Sahih al-Bukhari 6447'),
('bukhari:6569', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "None will enter Paradise but will be shown the place he would have occupied in the (Hell) Fire if he had rejected faith, so that he may be more thankful; and none will enter the (Hell) Fire but will be shown the place he would have occupied in Paradise if he had faith, so that may be a cause of sorrow for him', 'Sahih al-Bukhari 6569'),
('bukhari:18', 'Narrated ''Ubada bin As-Samit: who took part in the battle of Badr and was a Naqib (a person heading a group of six persons), on the night of Al-''Aqaba pledge: Allah''s Apostle said while a group of his companions were around him, "Swear allegiance to me for: 1. Not to join anything in worship along with Allah. 2. Not to steal. 3. Not to commit illegal sexual intercourse. 4. Not to kill your children. 5. Not to accuse an innocent person (to spread such an accusation among people). 6. Not to be disobedient (when ordered) to do good deed." The Prophet (ﷺ) added: "Whoever among you fulfills his pledge will be rewarded by Allah. And whoever indulges in any one of them (except the ascription of partners to Allah) and gets the punishment in this world, that punishment will be an expiation for that sin. And if one indulges in any of them, and Allah conceals his sin, it is up to Him to forgive or punish him (in the Hereafter)." ''Ubada bin As-Samit added: "So we swore allegiance for these." (points to Allah''s Apostle)', 'Sahih al-Bukhari 18'),
('bukhari:73', 'Narrated `Abdullah bin Mas`ud:The Prophet (ﷺ) said, "Do not wish to be like anyone except in two cases. (The first is) A person, whom Allah has given wealth and he spends it righteously; (the second is) the one whom Allah has given wisdom (the Holy Qur''an) and he acts according to it and teaches it to others." (Fath-al-Bari page 177 Vol)', 'Sahih al-Bukhari 73'),
('bukhari:85', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "(Religious) knowledge will be taken away (by the death of religious scholars) ignorance (in religion) and afflictions will appear; and Harj will increase." It was asked, "What is Harj, O Allah''s Messenger (ﷺ)?" He replied by beckoning with his hand indicating "killing." (Fath-al-Bari Page 192, Vol)', 'Sahih al-Bukhari 85'),
('bukhari:6565', 'Narrated Anas:Allah''s Messenger (ﷺ) said, "Allah will gather all the people on the Day of Resurrection and they will say, ''Let us request someone to intercede for us with our Lord so that He may relieve us from this place of ours.'' Then they will go to Adam and say, ''You are the one whom Allah created with His Own Hands, and breathed in you of His soul, and ordered the angels to prostrate to you; so please intercede for us with our Lord.'' Adam will reply, ''I am not fit for this undertaking, and will remember his sin, and will say, ''Go to Noah, the first Apostle sent by Allah'' They will go to him and he will say, ''I am not fit for this undertaking'', and will remember his sin and say, ''Go to Abraham whom Allah took as a Khalil. They will go to him (and request similarly). He will reply, ''I am not fit for this undertaking,'' and will remember his sin and say, ''Go to Moses to whom Allah spoke directly.'' They will go to Moses and he will say, ''I am not fit for this undertaking,'' and will remember his sin and say, ''Go to Jesus.'' They will go to him, and he will say, ''I am not fit for this undertaking, go to Muhammad as Allah has forgiven his past and future sins.'' They will come to me and I will ask my Lord''s permission, and when I see Him, I will fall down in prostration to Him, and He will leave me in that state as long as (He) Allah will, and then I will be addressed. ''Raise up your head (O Muhammad)! Ask, and your request will be granted, and say, and your saying will be listened to; intercede, and your intercession will be accepted.'' Then I will raise my head, and I will glorify and praise my Lord with a saying(i.e. invocation) He will teach me, and then I will intercede, Allah will fix a limit for me (i.e., certain type of people for whom I may intercede), and I will take them out of the (Hell) Fire and let them enter Paradise. Then I will come back (to Allah) and fall in prostration, and will do the same for the third and fourth times till no-one remains in the (Hell) Fire except those whom the Qur''an has imprisoned therein." (The sub-narrator, Qatada used to say at that point, "...those upon whom eternity (in Hell) has been imposed.") (See Hadith No. 3, Vol)', 'Sahih al-Bukhari 6565'),
('bukhari:6551', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "The width between the two shoulders of a Kafir (disbeliever) will be equal to the distance covered by a fast rider in three days', 'Sahih al-Bukhari 6551'),
('bukhari:72', 'Narrated Ibn `Umar:We were with the Prophet (ﷺ) and fresh dates of a palm tree were brought to him. On that he said, "Amongst the trees, there is a tree which resembles a Muslim." I wanted to say that it was the datepalm tree but as I was the youngest of all (of them) I kept quiet. And then the Prophet (ﷺ) said, "It is the date-palm tree', 'Sahih al-Bukhari 72'),
('bukhari:6476', 'Narrated Abu Shuraih Al-Khuza`i:My ears heard and my heart grasped (the statement which) the Prophet (ﷺ) said, "The period for keeping one''s guest is three days (and don''t forget) his reward." It was asked, "What is his reward?" He said, "In the first night and the day he should be given a high class quality of meals; and whoever believes in Allah and the Last Day, should entertain his guest generously; and whoever believes in Allah and the Last Day should talk what is good (sense) or keep quiet', 'Sahih al-Bukhari 6476'),
('bukhari:6554', 'Narrated Sahl bin Sa`d:Allah''s Messenger (ﷺ) said, "Seventy thousand or seven hundred thousand of my followers will enter Paradise. (Abu Hazim, the sub-narrator, is not sure as to which of the two numbers is correct.) They will be holding on to each other, the first will not entering the last one does, their faces like the moon on a full moon night', 'Sahih al-Bukhari 6554'),
('bukhari:121', 'Narrated Jarir:The Prophet (ﷺ) said to me during Hajjat-al-Wida`: Let the people keep quiet and listen. Then he said (addressing the people), "Do not (become infidels) revert to disbelief after me by striking the necks (cutting the throats) of one another (killing each other)', 'Sahih al-Bukhari 121'),
('bukhari:6495', 'Narrated Abu Sa`id:I heard from the Prophet (ﷺ) saying, "There will come a time upon the people when the best property of a Muslim will be sheep which he will take to the tops of mountains and to the places of rainfall, run away with his religion (in order to save it) from afflictions', 'Sahih al-Bukhari 6495'),
('nawawi:16', 'On the authority of Abu Hurayrah (may Allah be pleased with him): A man said to the Prophet (peace and blessings of Allah be upon him), “Counsel me,” so he (peace and blessings of Allah be upon him) said, “Do not become angry.” The man repeated [his request for counsel] several times, and [each time] he (peace and blessings of Allah be upon him) said, “Do not become angry.” [Al-Bukhari]', '40 Hadith Nawawi, Hadith 16'),
('bukhari:6535', 'Narrated Abu Sa`id Al-Khudri:Allah''s Messenger (ﷺ) said, "The believers, after being saved from the (Hell) Fire, will be stopped at a bridge between Paradise and Hell and mutual retaliation will be established among them regarding wrongs they have committed in the world against one another. After they are cleansed and purified (through the retaliation), they will be admitted into Paradise; and by Him in Whose Hand Muhammad''s soul is, everyone of them will know his dwelling in Paradise better than he knew his dwelling in this world', 'Sahih al-Bukhari 6535'),
('bukhari:130', 'Narrated Um Salama:Um-Sulaim came to Allah''s Messenger (ﷺ) and said, "Verily, Allah is not shy of (telling you) the truth. Is it necessary for a woman to take a bath after she has a wet dream (nocturnal sexual discharge?) The Prophet replied, "Yes, if she notices a discharge." Um Salama, then covered her face and asked, "O Allah''s Messenger (ﷺ)! Does a woman get a discharge?" He replied, "Yes, let your right hand be in dust (An Arabic expression you say to a person when you contradict his statement meaning "you will not achieve goodness"), and that is why the son resembles his mother', 'Sahih al-Bukhari 130'),
('bukhari:82', 'Narrated Ibn `Umar:Allah''s Messenger (ﷺ) said, "While I was sleeping, I saw that a cup full of milk was brought to me and I drank my fill till I noticed (the milk) its wetness coming out of my nails. Then I gave the remaining milk to `Umar Ibn Al-Khattab" The companions of the Prophet (ﷺ) asked, "What have you interpreted (about this dream), O Allah''s Messenger (ﷺ)?" He replied, "(It is religious) knowledge', 'Sahih al-Bukhari 82'),
('bukhari:107', 'Narrated `Abdullah bin Az-Zubair:I said to my father, ''I do not hear from you any narration (Hadith) of Allah''s Apostle as I hear (his narration) from so and so?" Az-Zubair replied, ''I was always with him (the Prophet) and I heard him saying, "Whoever tells a lie against me (intentionally) then (surely) let him occupy, his seat in Hellfire', 'Sahih al-Bukhari 107'),
('qudsi:16', 'On the authority of son of Abbas (may Allah be pleased with them both), from the Messenger of Allah (ﷺ), among the sayings he related from his Lord (glorified and exalted be He) is that He said: Allah has written down the good deeds and the bad ones. Then He explained it [by saying that] he who has intended a good deed and has not done it, Allah writes it down with Himself as a full good deed, but if he has intended it and has done it, Allah writes it down with Himself as from ten good deeds to seven hundred times, or many times over. But if he has intended a bad deed and has not done it, Allah writes it down with Himself as a full good deed, but if he has intended it and has done it, Allah writes it down as one bad deed. It was related by al-Bukhari and Muslim', '40 Hadith Qudsi, Hadith 16'),
('bukhari:45', 'Narrated ''Umar bin Al-Khattab: Once a Jew said to me, "O the chief of believers! There is a verse in your Holy Book Which is read by all of you (Muslims), and had it been revealed to us, we would have taken that day (on which it was revealed as a day of celebration." ''Umar bin Al-Khattab asked, "Which is that verse?" The Jew replied, "This day I have perfected your religion For you, completed My favor upon you, And have chosen for you Islam as your religion." (5:3) ''Umar replied,"No doubt, we know when and where this verse was revealed to the Prophet. It was Friday and the Prophet (ﷺ) was standing at ''Arafat (i.e. the Day of Hajj)', 'Sahih al-Bukhari 45'),
('bukhari:6429', 'Narrated `Abdullah:The Prophet (ﷺ) said, "The best people are those of my generation, and then those who will come after them (the next generation), and then those who will come after them (i.e. the next generation), and then after them, there will come people whose witness will precede their oaths, and whose oaths will precede their witness', 'Sahih al-Bukhari 6429'),
('bukhari:27', 'Narrated Sa''d: Allah''s Messenger (ﷺ) distributed (Zakat) amongst (a group of) people while I was sitting there but Allah''s Messenger (ﷺ) left a man whom I thought the best of the lot. I asked, "O Allah''s Messenger (ﷺ)! Why have you left that person? By Allah I regard him as a faithful believer." The Prophet (ﷺ) commented: "Or merely a Muslim." I remained quiet for a while, but could not help repeating my question because of what I knew about him. And then asked Allah''s Messenger (ﷺ), "Why have you left so and so? By Allah! He is a faithful believer." The Prophet (ﷺ) again said, "Or merely a Muslim." And I could not help repeating my question because of what I knew about him. Then the Prophet (ﷺ) said, "O Sa''d! I give to a person while another is dearer to me, for fear that he might be thrown on his face in the Fire by Allah', 'Sahih al-Bukhari 27'),
('nawawi:17', 'On the authority of Abu Ya’la Shaddad bin Aws (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: Verily Allah has prescribed ihsan (proficiency, perfection) in all things. So if you kill then kill well; and if you slaughter, then slaughter well. Let each one of you sharpen his blade and let him spare suffering to the animal he slaughters.” [Muslim]', '40 Hadith Nawawi, Hadith 17'),
('bukhari:6534', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "Whoever has wronged his brother, should ask for his pardon (before his death), as (in the Hereafter) there will be neither a Dinar nor a Dirham. (He should secure pardon in this life) before some of his good deeds are taken and paid to his brother, or, if he has done no good deeds, some of the bad deeds of his brother are taken to be loaded on him (in the Hereafter)', 'Sahih al-Bukhari 6534'),
('bukhari:6442', 'Narrated `Abdullah:The Prophet (ﷺ) said, "Who among you considers the wealth of his heirs dearer to him than his own wealth?" They replied, "O Allah''s Messenger (ﷺ)! There is none among us but loves his own wealth more." The Prophet (ﷺ) said, "So his wealth is whatever he spends (in Allah''s Cause) during his life (on good deeds) while the wealth of his heirs is whatever he leaves after his death', 'Sahih al-Bukhari 6442'),
('bukhari:97', 'Narrated Abu Burda''s father: Allah''s Messenger (ﷺ) said "Three persons will have a double reward: 1. A Person from the people of the scriptures who believed in his prophet (Jesus or Moses) and then believed in the Prophet Muhammad (ﷺ) (i.e. has embraced Islam). 2. A slave who discharges his duties to Allah and his master. 3. A master of a woman-slave who teaches her good manners and educates her in the best possible way (the religion) and manumits her and then marries her', 'Sahih al-Bukhari 97'),
('bukhari:6516', 'Narrated `Aisha:The Prophet (ﷺ) said, "Do not abuse the dead, for they have reached the result of what they have done', 'Sahih al-Bukhari 6516'),
('nawawi:4', 'On the authority of Abdullah ibn Masood (ra), who said: The Messenger of Allah (ﷺ), and he is the truthful, the believed, narrated to us, “Verily the creation of each one of you is brought together in his mother’s womb for forty days in the form of a nutfah (a drop), then he becomes an alaqah (clot of blood) for a like period, then a mudghah (morsel of flesh) for a like period, then there is sent to him the angel who blows his soul into him and who is commanded with four matters: to write down his rizq (sustenance), his life span, his actions, and whether he will be happy or unhappy (i.e., whether or not he will enter Paradise). By the One, other than Whom there is no deity, verily one of you performs the actions of the people of Paradise until there is but an arms length between him and it, and that which has been written overtakes him, and so he acts with the actions of the people of the Hellfire and thus enters it; and verily one of you performs the actions of the people of the Hellfire, until there is but an arms length between him and it, and that which has been written overtakes him and so he acts with the actions of the people of Paradise and thus he enters it.” [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 4'),
('bukhari:6449', 'Narrated `Imran bin Husain:The Prophet (ﷺ) said, "I looked into Paradise and found that the majority of its dwellers were the poor people, and I looked into the (Hell) Fire and found that the majority of its dwellers were women', 'Sahih al-Bukhari 6449'),
('bukhari:6510', 'Narrated `Aisha:There was a leather or wood container full of water in front of Allah''s Messenger (ﷺ) (at the time of his death). He would put his hand into the water and rub his face with it, saying, "None has the right to be worshipped but Allah! No doubt, death has its stupors." Then he raised his hand and started saying, "(O Allah!) with the highest companions." (See Qur''an 4:69) (and kept on saying it) till he expired and his hand dropped', 'Sahih al-Bukhari 6510'),
('bukhari:6444', 'Narrated Abu Dhar:While I was walking with the Prophet (ﷺ) in the Harra of Medina, Uhud came in sight. The Prophet (ﷺ) said, "O Abu Dhar!" I said, "Labbaik, O Allah''s Messenger (ﷺ)!" He said, "I would not like to have gold equal to this mountain of Uhud, unless nothing of it, not even a single Dinar of it remains with me for more than three days, except something which I will keep for repaying debts. I would have spent all of it (distributed it) amongst Allah''s Slaves like this, and like this, and like this." The Prophet (ﷺ) pointed out with his hand towards his right, his left and his back (while illustrating it). He proceeded with his walk and said, "The rich are in fact the poor (little rewarded) on the Day of Resurrection except those who spend their wealth like this, and like this, and like this, to their right, left and back, but such people are few in number." Then he said to me, "Stay at your place and do not leave it till I come back." Then he proceeded in the darkness of the night till he went out of sight, and then I heard a loud voice, and was afraid that something might have happened to the Prophet (ﷺ) .1 intended to go to him, but I remembered what he had said to me, i.e. ''Don''t leave your place till I come back to you,'' so I remained at my place till he came back to me. I said, "O Allah''s Messenger (ﷺ)! I heard a voice and I was afraid." So I mentioned the whole story to him. He said, "Did you hear it?" I replied, "Yes." He said, "It was Gabriel who came to me and said, ''Whoever died without joining others in worship with Allah, will enter Paradise.'' I asked (Gabriel), ''Even if he had committed theft or committed illegal sexual intercourse? Gabriel said, ''Yes, even if he had committed theft or committed illegal sexual intercourse', 'Sahih al-Bukhari 6444'),
('bukhari:6511', 'Narrated `Aisha:Some rough bedouins used to visit the Prophet (ﷺ) and ask him, "When will the Hour be?" He would look at the youngest of all of them and say, "If this should live till he is very old, your Hour (the death of the people addressed) will take place." Hisham said that he meant (by the Hour), their death', 'Sahih al-Bukhari 6511'),
('bukhari:6415', 'Narrated Sahl:I heard the Prophet (ﷺ) saying, "A (small) place equal to an area occupied by a whip in Paradise is better than the (whole) world and whatever is in it; and an undertaking (journey) in the forenoon or in the afternoon for Allah''s Cause, is better than the whole world and whatever is in it', 'Sahih al-Bukhari 6415'),
('bukhari:6513', 'Narrated Abu Qatada:The Prophet (ﷺ) said, "Relieved or relieving. And a believer is relieved (by death)', 'Sahih al-Bukhari 6513'),
('bukhari:15', 'Narrated Anas: The Prophet (ﷺ) said "None of you will have faith till he loves me more than his father, his children and all mankind', 'Sahih al-Bukhari 15'),
('nawawi:8', 'On the authority of Abdullah ibn Umar (ra): The Messenger of Allah (ﷺ) said, "I have been ordered to fight against the people until they testify that there is none worthy of worship except Allah and that Muhammad is the Messenger of Allah, and until they establish the salah and pay the zakat. And if they do that then they will have gained protection from me for their lives and property, unless [they commit acts that are punishable] in Islam, and their reckoning will be with Allah." [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 8'),
('bukhari:6418', 'Narrated Anas bin Malik:The Prophet (ﷺ) drew a few lines and said, "This is (man''s) hope, and this is the instant of his death, and while he is in this state (of hope), the nearer line (death) comes to Him', 'Sahih al-Bukhari 6418'),
('qudsi:12', 'On the authority of Abu Mas''ud al-Ansari (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: A man from among those who were before you was called to account. Nothing in the way of good was found for him except that he used to have dealings with people and, being well-to-do, he would order his servants to let off the man in straitened circumstances [from repaying his debt]. He (the Prophet (ﷺ) ﷺ) said that Allah said: We are worthier than you of that (of being so generous). Let him off. It was related by Muslim (also by al-Bukhari and an-Nasa''i)', '40 Hadith Qudsi, Hadith 12'),
('bukhari:6434', 'Narrated Mirdas Al-Aslami:The Prophet (ﷺ) said, "The righteous (pious people will depart (die) in succession one after the other, and there will remain (on the earth) useless people like the useless husk of barley seeds or bad dates', 'Sahih al-Bukhari 6434'),
('nawawi:41', 'On the authority of Abu Muhammad Abdullah bin ’Amr bin al-’Aas (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “None of you [truly] believes until his desires are subservient to that which I have brought.” [Imam an-Nawawi says:] We have related it in Kitab al-Hujjah with a saheeh chain of narrators', '40 Hadith Nawawi, Hadith 41'),
('bukhari:6496', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "When honesty is lost, then wait for the Hour." It was asked, "How will honesty be lost, O Allah''s Messenger (ﷺ)?" He said, "When authority is given to those who do not deserve it, then wait for the Hour', 'Sahih al-Bukhari 6496'),
('bukhari:6464', 'Narrated `Aisha:Allah''s Messenger (ﷺ) said, "Do good deeds properly, sincerely and moderately and know that your deeds will not make you enter Paradise, and that the most beloved deed to Allah is the most regular and constant even if it were little', 'Sahih al-Bukhari 6464'),
('bukhari:104', 'Narrated Sa`id:Abu Shuraih said, "When `Amr bin Sa`id was sending the troops to Mecca (to fight `Abdullah bin Az-Zubair) I said to him, ''O chief! Allow me to tell you what the Prophet (ﷺ) said on the day following the conquests of Mecca. My ears heard and my heart comprehended, and I saw him with my own eyes, when he said it. He glorified and praised Allah and then said, "Allah and not the people has made Mecca a sanctuary. So anybody who has belief in Allah and the Last Day (i.e. a Muslim) should neither shed blood in it nor cut down its trees. If anybody argues that fighting is allowed in Mecca as Allah''s Messenger (ﷺ) did fight (in Mecca), tell him that Allah gave permission to His Apostle, but He did not give it to you. The Prophet (ﷺ) added: Allah allowed me only for a few hours on that day (of the conquest) and today (now) its sanctity is the same (valid) as it was before. So it is incumbent upon those who are present to convey it (this information) to those who are absent." Abu- Shuraih was asked, "What did `Amr reply?" He said `Amr said, "O Abu Shuraih! I know better than you (in this respect). Mecca does not give protection to one who disobeys (Allah) or runs after committing murder, or theft (and takes refuge in Mecca)', 'Sahih al-Bukhari 104'),
('bukhari:19', 'Narrated Abu Said Al-Khudri: Allah''s Messenger (ﷺ) said, "A time will soon come when the best property of a Muslim will be sheep which he will take on the top of mountains and the places of rainfall (valleys) so as to flee with his religion from afflictions', 'Sahih al-Bukhari 19'),
('bukhari:6486', 'Narrated Anas:The Prophet (ﷺ) said, "If you knew that which I know, you would laugh little and weep much', 'Sahih al-Bukhari 6486'),
('nawawi:6', 'On the authority of an-Nu’man ibn Basheer (ra), who said: I heard the Messenger of Allah (ﷺ) say, “That which is lawful is clear and that which is unlawful is clear, and between the two of them are doubtful matters about which many people do not know. Thus he who avoids doubtful matters clears himself in regard to his religion and his honor, but he who falls into doubtful matters [eventually] falls into that which is unlawful, like the shepherd who pastures around a sanctuary, all but grazing therein. Truly every king has a sanctuary, and truly Allah’s sanctuary is His prohibitions. Truly in the body there is a morsel of flesh, which, if it be whole, all the body is whole, and which, if it is diseased, all of [the body] is diseased. Truly, it is the heart.” [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 6'),
('bukhari:77', 'Narrated Mahmud bin Rabi`a:When I was a boy of five, I remember, the Prophet (ﷺ) took water from a bucket (used for getting water out of a well) with his mouth and threw it on my face', 'Sahih al-Bukhari 77'),
('bukhari:6593', 'Narrated Asma ''bint Abu Bakr:The Prophet (ﷺ) said, "I will be standing at the Lake-Fount so that I will see whom among you will come to me; and some people will be taken away from me, and I will say, ''O Lord, (they are) from me and from my followers.'' Then it will be said, ''Did you notice what they did after you? By Allah, they kept on turning on their heels (turned as renegades).'' " The sub-narrator, Ibn Abi Mulaika said, "O Allah, we seek refuge with You from turning on our heels, or being put to trial in our religion', 'Sahih al-Bukhari 6593'),
('bukhari:14', 'Narrated Abu Huraira: "Allah''s Messenger (ﷺ) said, "By Him in Whose Hands my life is, none of you will have faith till he loves me more than his father and his children', 'Sahih al-Bukhari 14'),
('qudsi:38', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: When Allah created Paradise and Hell-fire, He sent Gabriel to Paradise, saying: Look at it and at what I have prepared therein for its inhabitants. The Prophet (ﷺ) said: So he came to it and looked at it and at what Allah had prepared therein for its inhabitants. The Prophet (ﷺ) said: So he returned to Him and said: By your glory, no one hears of it without entering it. So He ordered that it be encompassed by forms of hardship, and He said: Return to it and look at what I have prepared therein for its inhabitants. The Prophet (ﷺ) said: So he returned to it and found that it was encompassed by forms of hardship (1). Then he returned to Him and said: By Your glory, I fear that no one will enter it. He said: Go to Hell-fire and look at it and what I have prepared therein for its inhabitants, and he found that it was in layers, one above the other. Then he returned to Him and said: By Your glory, no one who hears of it will enter it. So He ordered that it be encompassed by lusts. Then He said: Return to it. And he returned to it and said: By Your glory, I am frightened that no one will escape from entering it. (1) The Arabic word used here is "makarih", the literal meaning of which is "things that are disliked". In this context it refers to forms of religious discipline that man usually finds onerous. It was related by Tirmidhi, who said that it was a good and sound Hadith (also by Abu Dawud and an-Nasa''i)', '40 Hadith Qudsi, Hadith 38'),
('bukhari:6561', 'Narrated An-Nu`man:I heard the Prophet (ﷺ) saying, "The person who will have the least punishment from amongst the Hell Fire people on the Day of Resurrection, will be a man under whose arch of the feet a smoldering ember will be placed so that his brain will boil because of it', 'Sahih al-Bukhari 6561'),
('bukhari:117', 'Narrated Ibn `Abbas:I stayed overnight in the house of my aunt Maimuna bint Al-Harith (the wife of the Prophet (ﷺ) ) while the Prophet (ﷺ) was there with her during her night turn. The Prophet (ﷺ) offered the `Isha'' prayer (in the mosque), returned home and after having prayed four rak`at, he slept. Later on he got up at night and then asked whether the boy (or he used a similar word) had slept? Then he got up for the prayer and I stood up by his left side but he made me stand to his right and offered five rak`at followed by two more rak`at. Then he slept and I heard him snoring and then (after a while) he left for the (Fajr) prayer', 'Sahih al-Bukhari 117'),
('bukhari:6428', 'Narrated Zahdam bin Mudarrib:`Imran bin Husain said: The Prophet (ﷺ) said, "The best people are my contemporaries (i.e., the present (my) generation) and then those who come after them (i.e., the next generation)." `Imran added: I am not sure whether the Prophet (ﷺ) repeated the statement twice after his first saying. The Prophet (ﷺ) added, "And after them there will come people who will bear witness, though they will not be asked to give their witness; and they will be treacherous and nobody will trust them, and they will make vows, but will not fulfill them, and fatness will appear among them', 'Sahih al-Bukhari 6428'),
('qudsi:13', 'On the authority of Adiyy ibn Hatim (may Allah be pleased with him), who said: I was with the Messenger of Allah (ﷺ) and there came to him two men: one of them was complaining of penury (being very poor), while the other was complaining of brigandry (robbery). The Messenger of Allah (ﷺ) said: As for brigandry, it will be but a short time before a caravan will [be able to] go out of Mecca without a guard. As for penury, the Hour (Day of Judgement) will not arrive before one of you takes his charity around without finding anyone to accept it from him. Then (1) one of you will surely stand before Allah, there being no screen between Him and him, nor an interpreter to translate for him. Then He will say to him: Did I not bring you wealth? And he will say: Yes. Then He will say: Did I not send to you a messenger? And he will say: Yes. And he will look to his right and will see nothing but Hell-fire, then he will look to his left and will see nothing but Hell-fire, so let each of you protect himself against Hell-fire, be it with even half a date - and if he finds it not, then with a kind word. (1) i.e. at the time of the Hour. It was related by al-Bukhari', '40 Hadith Qudsi, Hadith 13'),
('bukhari:6454', 'Narrated `Aisha:The family of Muhammad had never eaten their fill of wheat bread for three successive days since they had migrated to Medina till the death of the Prophet', 'Sahih al-Bukhari 6454'),
('bukhari:17', 'Narrated Anas: The Prophet (ﷺ) said, "Love for the Ansar is a sign of faith and hatred for the Ansar is a sign of hypocrisy', 'Sahih al-Bukhari 17'),
('bukhari:126', 'Narrated Aswad:Ibn Az-Zubair said to me, "Aisha used to tell you secretly a number of things. What did she tell you about the Ka`ba?" I replied, "She told me that once the Prophet (ﷺ) said, ''O `Aisha! Had not your people been still close to the pre-Islamic period of ignorance (infidelity)! I would have dismantled the Ka`ba and would have made two doors in it; one for entrance and the other for exit." Later on Ibn Az-Zubair did the same', 'Sahih al-Bukhari 126'),
('qudsi:22', 'On the authority of Abu Sa''id (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Let not any one of you belittle himself. They said: O Messenger of Allah, how can any one of us belittle himself? He said: He finds a matter concerning Allah about which he should say something, and he does not say [it], so Allah (mighty and sublime be He) says to him on the Day of Resurrection: What prevented you from saying something about such-and-such and such-and-such? He say: [It was] out of fear of people. Then He says: Rather it is I whom you should more properly fear. It was related by Ibn Majah with a sound chain of authorities', '40 Hadith Qudsi, Hadith 22'),
('bukhari:39', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "Religion is very easy and whoever overburdens himself in his religion will not be able to continue in that way. So you should not be extremists, but try to be near to perfection and receive the good tidings that you will be rewarded; and gain strength by worshipping in the mornings, the afternoons, and during the last hours of the nights." (See Fath-ul-Bari, Page 102, Vol)', 'Sahih al-Bukhari 39'),
('bukhari:67', 'Narrated `Abdur-Rahman bin Abi Bakra''s father:Once the Prophet (ﷺ) was riding his camel and a man was holding its rein. The Prophet (ﷺ) asked, "What is the day today?" We kept quiet, thinking that he might give that day another name. He said, "Isn''t it the day of Nahr (slaughtering of the animals of sacrifice)" We replied, "Yes." He further asked, "Which month is this?" We again kept quiet, thinking that he might give it another name. Then he said, "Isn''t it the month of Dhul-Hijja?" We replied, "Yes." He said, "Verily! Your blood, property and honor are sacred to one another (i.e. Muslims) like the sanctity of this day of yours, in this month of yours and in this city of yours. It is incumbent upon those who are present to inform those who are absent because those who are absent might comprehend (what I have said) better than the present audience', 'Sahih al-Bukhari 67'),
('bukhari:6532', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "The people will sweat so profusely on the Day of Resurrection that their sweat will sink seventy cubits deep into the earth, and it will rise up till it reaches the people''s mouths and ears', 'Sahih al-Bukhari 6532'),
('nawawi:19', 'On the authority of Abu Abbas Abdullah bin Abbas (may Allah be pleased with him) who said: One day I was behind the Prophet (peace and blessings of Allah be upon him) [riding on the same mount] and he said, “O young man, I shall teach you some words [of advice]: Be mindful of Allah and Allah will protect you. Be mindful of Allah and you will find Him in front of you. If you ask, then ask Allah [alone]; and if you seek help, then seek help from Allah [alone]. And know that if the nation were to gather together to benefit you with anything, they would not benefit you except with what Allah had already prescribed for you. And if they were to gather together to harm you with anything, they would not harm you except with what Allah had already prescribed against you. The pens have been lifted and the pages have dried.” It was related by at-Tirmidhi, who said it was a good and sound hadeeth. Another narration, other than that of Tirmidhi, reads: Be mindful of Allah, and you will find Him in front of you. Recognize and acknowledge Allah in times of ease and prosperity, and He will remember you in times of adversity. And know that what has passed you by [and you have failed to attain] was not going to befall you, and what has befallen you was not going to pass you by. And know that victory comes with patience, relief with affliction, and hardship with ease', '40 Hadith Nawawi, Hadith 19'),
('nawawi:42', 'On the authority of Anas (may Allah be pleased with him) who said: I heard the Messenger of Allah (peace and blessings of Allah be upon him) say, “Allah the Almighty has said: ‘O Son of Adam, as long as you invoke Me and ask of Me, I shall forgive you for what you have done, and I shall not mind. O Son of Adam, were your sins to reach the clouds of the sky and you then asked forgiveness from Me, I would forgive you. O Son of Adam, were you to come to Me with sins nearly as great as the Earth, and were you then to face Me, ascribing no partner to Me, I would bring you forgiveness nearly as great as it [too].’ ” It was related by at-Tirmidhi, who said that it was a hasan hadeeth', '40 Hadith Nawawi, Hadith 42'),
('qudsi:40', 'On the authority of Abu Sa''id al-Khudri (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah will say to the inhabitants of Paradise: O inhabitants of Paradise! They will say: O our Lord, we present ourselves and are at Your pleasure, and goodness rests in Your hands. Then He will say: Are you contented? And they will say: And how should we not be contented, O Lord, when You have given to us that which You have given to no one else of Your creation? Then He will say: Would you not like Me to give you something better than that? And they will say: O Lord and what thing is better than that? And He will say: I shall cause My favour to descend upon you and thereafter shall never be displeased with you. It was related by al-Bukhari (also by Muslim and at-Tirmidhi)', '40 Hadith Qudsi, Hadith 40'),
('qudsi:34', 'On the authority of Anas (may Allah be pleased with him), who said: I heard the Messenger of Allah (ﷺ) say: Allah the Almighty said: O son of Adam, so long as you call upon Me and ask of Me, I shall forgive you for what you have done, and I shall not mind. O son of Adam, were your sins to reach the clouds of the sky and were you then to ask forgiveness of Me, I would forgive you. O son of Adam, were you to come to Me with sins nearly as great as the earth and were you then to face Me, ascribing no partner to Me, I would bring you forgiveness nearly as great as it. It was related by at-Tirmidhi (also by Ahmad ibn Hanbal). Its chain of authorities is sound', '40 Hadith Qudsi, Hadith 34'),
('bukhari:6437', 'Narrated Ibn `Abbas:I heard Allah''s Messenger (ﷺ) saying, "If the son of Adam had money equal to a valley, then he will wish for another similar to it, for nothing can satisfy the eye of Adam''s son except dust. And Allah forgives him who repents to Him." Ibn `Abbas said: I do not know whether this saying was quoted from the Qur''an or not. `Ata'' said, "I heard Ibn Az-Zubair saying this narration while he was on the pulpit', 'Sahih al-Bukhari 6437'),
('nawawi:38', 'On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Verily Allah ta’ala has said: ‘Whosoever shows enmity to a wali (friend) of Mine, then I have declared war against him. And My servant does not draw near to Me with anything more loved to Me than the religious duties I have obligated upon him. And My servant continues to draw near to me with nafil (supererogatory) deeds until I Love him. When I Love him, I am his hearing with which he hears, and his sight with which he sees, and his hand with which he strikes, and his foot with which he walks. Were he to ask [something] of Me, I would surely give it to him; and were he to seek refuge with Me, I would surely grant him refuge.’ ” [Al-Bukhari]', '40 Hadith Nawawi, Hadith 38'),
('bukhari:6463', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "The deeds of anyone of you will not save you (from the (Hell) Fire)." They said, "Even you (will not be saved by your deeds), O Allah''s Messenger (ﷺ)?" He said, "No, even I (will not be saved) unless and until Allah bestows His Mercy on me. Therefore, do good deeds properly, sincerely and moderately, and worship Allah in the forenoon and in the afternoon and during a part of the night, and always adopt a middle, moderate, regular course whereby you will reach your target (Paradise)', 'Sahih al-Bukhari 6463'),
('bukhari:6527', 'Narrated `Aisha:Allah''s Messenger (ﷺ) said, "The people will be gathered barefooted, naked, and uncircumcised." I said, "O Allah''s Messenger (ﷺ)! Will the men and the women look at each other?" He said, "The situation will be too hard for them to pay attention to that', 'Sahih al-Bukhari 6527'),
('bukhari:6460', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "O Allah! Give food to the family of Muhammad', 'Sahih al-Bukhari 6460'),
('bukhari:111', 'Narrated Ash-Shu`bi:Abu Juhaifa said, "I asked `Ali, ''Have you got any book (which has been revealed to the Prophet (ﷺ) apart from the Qur''an)?'' `Ali replied, ''No, except Allah''s Book or the power of understanding which has been bestowed (by Allah) upon a Muslim or what is (written) in this sheet of paper (with me).'' Abu Juhaifa said, "I asked, ''What is (written) in this sheet of paper?'' `Ali replied, it deals with The Diyya (compensation (blood money) paid by the killer to the relatives of the victim), the ransom for the releasing of the captives from the hands of the enemies, and the law that no Muslim should be killed in Qisas (equality in punishment) for the killing of (a disbeliever)', 'Sahih al-Bukhari 111'),
('bukhari:6450', 'Narrated Anas:The Prophet (ﷺ) did not eat at a table till he died, and he did not eat a thin nicely baked wheat bread till he died', 'Sahih al-Bukhari 6450'),
('bukhari:33', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "The signs of a hypocrite are three: 1. Whenever he speaks, he tells a lie. 2. Whenever he promises, he always breaks it (his promise ). 3. If you trust him, he proves to be dishonest. (If you keep something as a trust with him, he will not return it)', 'Sahih al-Bukhari 33'),
('qudsi:18', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) will say on the Day of Resurrection: O son of Adam, I fell ill and you visited Me not. He will say: O Lord, and how should I visit You when You are the Lord of the worlds? He will say: Did you not know that My servant So-and-so had fallen ill and you visited him not? Did you not know that had you visited him you would have found Me with him? O son of Adam, I asked you for food and you fed Me not. He will say: O Lord, and how should I feed You when You are the Lord of the worlds? He will say: Did you not know that My servant So-and-so asked you for food and you fed him not? Did you not know that had you fed him you would surely have found that (the reward for doing so) with Me? O son of Adam, I asked you to give Me to drink and you gave Me not to drink. He will say: O Lord, how should I give You to drink when You are the Lord of the worlds? He will say: My servant So-and-so asked you to give him to drink and you gave him not to drink. Had you given him to drink you would have surely found that with Me. It was related by Muslim', '40 Hadith Qudsi, Hadith 18'),
('nawawi:15', 'On the authority of Abu Hurayrah (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: Let him who believes in Allah and the Last Day speak good, or keep silent; and let him who believes in Allah and the Last Day be generous to his neighbour; and let him who believes in Allah and the Last Day be generous to his guest. [Al-Bukhari] [Muslim]', '40 Hadith Nawawi, Hadith 15'),
('bukhari:113', 'Narrated Abu Huraira:There is none among the companions of the Prophet (ﷺ) who has narrated more Hadiths than I except `Abdullah bin `Amr (bin Al-`As) who used to write them and I never did the same', 'Sahih al-Bukhari 113'),
('bukhari:6503', 'Narrated Sahl:Allah''s Messenger (ﷺ) said, "I have been sent and the Hour (is at hand) as these two," showing his two fingers and sticking (separating) them out', 'Sahih al-Bukhari 6503'),
('bukhari:98', 'Narrated Ibn ''Abbas: Once Allah''s Messenger (ﷺ) came out while Bilal was accompanying him. He went towards the women thinking that they had not heard him (i.e. his sermon). So he preached them and ordered them to pay alms. (Hearing that) the women started giving alms; some donated their ear-rings, some gave their rings and Bilal was collecting them in the corner of his garment', 'Sahih al-Bukhari 98'),
('qudsi:1', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: When Allah decreed the Creation He pledged Himself by writing in His book which is laid down with Him: My mercy prevails over my wrath. It was related by Muslim (also by al-Bukhari, an-Nasa''i and Ibn Majah)', '40 Hadith Qudsi, Hadith 1'),
('bukhari:6498', 'Narrated `Abdullah bin `Umar:I heard Allah''s Messenger (ﷺ) saying, "People are just like camels, out of one hundred, one can hardly find a single camel suitable to ride', 'Sahih al-Bukhari 6498'),
('bukhari:6557', 'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Allah will say to the person who will have the minimum punishment in the Fire on the Day of Resurrection, ''If you had things equal to whatever is on the earth, would you ransom yourself (from the punishment) with it?'' He will reply, Yes. Allah will say, ''I asked you a much easier thing than this while you were in the backbone of Adam, that is, not to worship others besides Me, but you refused and insisted to worship others besides Me', 'Sahih al-Bukhari 6557'),
('bukhari:56', 'Narrated Sa''d bin Abi Waqqas: Allah''s Messenger (ﷺ) said, "You will be rewarded for whatever you spend for Allah''s sake even if it were a morsel which you put in your wife''s mouth', 'Sahih al-Bukhari 56'),
('bukhari:112', 'Narrated Abu Huraira:In the year of the Conquest of Mecca, the tribe of Khuza`a killed a man from the tribe of Bani Laith in revenge for a killed person, belonging to them. They informed the Prophet (ﷺ) about it. So he rode his Rahila (she-camel for riding) and addressed the people saying, "Allah held back the killing from Mecca. (The sub-narrator is in doubt whether the Prophet (ﷺ) said "elephant or killing," as the Arabic words standing for these words have great similarity in shape), but He (Allah) let His Apostle and the believers over power the infidels of Mecca. Beware! (Mecca is a sanctuary) Verily! Fighting in Mecca was not permitted for anyone before me nor will it be permitted for anyone after me. It (war) in it was made legal for me for few hours or so on that day. No doubt it is at this moment a sanctuary, it is not allowed to uproot its thorny shrubs or to uproot its trees or to pick up its Luqat (fallen things) except by a person who will look for its owner (announce it publicly). And if somebody is killed, then his closest relative has the right to choose one of the two-- the blood money (Diyya) or retaliation having the killer killed. In the meantime a man from Yemen came and said, "O Allah''s Messenger (ﷺ)! Get that written for me." The Prophet (ﷺ) ordered his companions to write that for him. Then a man from Quraish said, "Except Al-Idhkhir (a type of grass that has good smell) O Allah''s Messenger (ﷺ), as we use it in our houses and graves." The Prophet (ﷺ) said, "Except Al-Idhkhir i.e. Al-Idhkhir is allowed to be plucked', 'Sahih al-Bukhari 112'),
('bukhari:6455', 'Narrated `Aisha:The family of Muhammad did not eat two meals on one day, but one of the two was of dates', 'Sahih al-Bukhari 6455'),
('bukhari:70', 'Narrated Abu Wail:`Abdullah used to give a religious talk to the people on every Thursday. Once a man said, "O Aba `Abdur-Rahman! (By Allah) I wish if you could preach us daily." He replied, "The only thing which prevents me from doing so, is that I hate to bore you, and no doubt I take care of you in preaching by selecting a suitable time just as the Prophet (ﷺ) used to do with us, for fear of making us bored', 'Sahih al-Bukhari 70'),
('bukhari:6485', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "If you knew that which I know you would laugh little and weep much', 'Sahih al-Bukhari 6485'),
('bukhari:6432', 'Narrated Khabbab:We migrated with the Prophet..(This narration is related in the chapter of migration)', 'Sahih al-Bukhari 6432'),
('bukhari:6431', 'Narrated Qais:I came to Khabbab while he was building a wall, and he (Khabbab) said, "Our companions who have left this world, did not enjoy anything of their reward therein, while we have collected after them, much wealth that we cannot spend but on earth (i.e., on building)', 'Sahih al-Bukhari 6431'),
('bukhari:6580', 'Narrated Anas bin Malik:Allah''s Messenger (ﷺ) said, "The width of my Lake-Fount is equal to the distance between Aila (a town in Sham) and Sana'' (the capital of Yemen) and it has as many (numerous) jugs as the number of stars of the sky', 'Sahih al-Bukhari 6580'),
('bukhari:6477', 'Narrated Abu Huraira:That he heard Allah''s Messenger (ﷺ) saying, "A slave of Allah may utter a word without thinking whether it is right or wrong, he may slip down in the Fire as far away a distance equal to that between the east', 'Sahih al-Bukhari 6477'),
('nawawi:29', 'On the authority of Muadh bin Jabal (may Allah be pleased with him) who said: I said, “O Messenger of Allah, tell me of an act which will take me into Paradise and will keep me away from the Hellfire.” He (peace and blessings of Allah be upon him) said, “You have asked me about a great matter, yet it is easy for him for whom Allah makes it easy: worship Allah, without associating any partners with Him; establish the prayer; pay the zakat; fast in Ramadhan; and make the pilgrimage to the House.” Then he (peace and blessings of Allah be upon him) said, “Shall I not guide you towards the means of goodness? Fasting is a shield; charity wipes away sin as water extinguishes fire; and the praying of a man in the depths of the night.” Then he (peace and blessings of Allah be upon him) recited: “[Those] who forsake their beds, to invoke their Lord in fear and hope, and they spend (charity in Allah’s cause) out of what We have bestowed on them. No person knows what is kept hidden for them of joy as a reward for what they used to do.” [as-Sajdah, 16-17] Then he (peace and blessings of Allah be upon him) said, “Shall I not inform you of the head of the matter, its pillar and its peak?” I said, “Yes, O Messenger of Allah.” He (peace and blessings of Allah be upon him) said, “The head of the matter is Islam, its pillar is the prayer and its peak is jihad.” Then he (peace and blessings of Allah be upon him) said, “Shall I not tell you of the foundation of all of that?” I said, “Yes, O Messenger of Allah.” So he took hold of his tongue and said, “Restrain this.” I said, “O Prophet (ﷺ) of Allah, will we be taken to account for what we say with it?” He (peace and blessings of Allah be upon him) said, “May your mother be bereaved of you, O Muadh! Is there anything that throws people into the Hellfire upon their faces — or: on their noses — except the harvests of their tongues?” It was related by at-Tirmidhi, who said it was a good and sound hadeeth', '40 Hadith Nawawi, Hadith 29'),
('bukhari:6494', 'Narrated Abu Sa`id Al-Khudri:A bedouin came to the Prophet (ﷺ) and said, "O Allah''s Messenger (ﷺ)! Who is the best of mankind!" The Prophet said, "A man who strives for Allah''s Cause with his life and property, and also a man who lives (all alone) in a mountain path among the mountain paths to worship his Lord and save the people from his evil', 'Sahih al-Bukhari 6494'),
('bukhari:6570', 'Narrated Abu Huraira:I said, "O Allah''s Messenger (ﷺ)! Who will be the luckiest person who will gain your intercession on the Day of Resurrection?" The Prophet (ﷺ) said, "O Abu Huraira! I have thought that none will ask me about this Hadith before you, as I know your longing for the (learning of) Hadiths. The luckiest person who will have my intercession on the Day of Resurrection will be the one who said, ''None has the right to be worshipped but Allah,'' sincerely from the bottom of his heart', 'Sahih al-Bukhari 6570'),
('bukhari:68', 'Narrated Ibn Mas`ud:The Prophet (ﷺ) used to take care of us in preaching by selecting a suitable time, so that we might not get bored. (He abstained from pestering us with sermons and knowledge all the time)', 'Sahih al-Bukhari 68'),
('bukhari:6416', 'Narrated Mujahid:`Abdullah bin `Umar said, "Allah''s Messenger (ﷺ) took hold of my shoulder and said, ''Be in this world as if you were a stranger or a traveler." The sub-narrator added: Ibn `Umar used to say, "If you survive till the evening, do not expect to be alive in the morning, and if you survive till the morning, do not expect to be alive in the evening, and take from your health for your sickness, and (take) from your life for your death', 'Sahih al-Bukhari 6416'),
('bukhari:6452', 'Narrated Abu Huraira:By Allah except Whom none has the right to- be worshipped, (sometimes) I used to lay (sleep) on the ground on my liver (abdomen) because of hunger, and (sometimes) I used to bind a stone over my belly because of hunger. One day I sat by the way from where they (the Prophet (ﷺ) and his companions) used to come out. When Abu Bakr passed by, I asked him about a Verse from Allah''s Book and I asked him only that he might satisfy my hunger, but he passed by and did not do so. Then `Umar passed by me and I asked him about a Verse from Allah''s Book, and I asked him only that he might satisfy my hunger, but he passed by without doing so. Finally Abu-l-Qasim (the Prophet (ﷺ) ) passed by me and he smiled when he saw me, for he knew what was in my heart and on my face. He said, "O Aba Hirr (Abu Huraira)!" I replied, "Labbaik, O Allah''s Messenger (ﷺ)!" He said to me, "Follow me." He left and I followed him. Then he entered the house and I asked permission to enter and was admitted. He found milk in a bowl and said, "From where is this milk?" They said, "It has been presented to you by such-and-such man (or by such and such woman)." He said, "O Aba Hirr!" I said, "Labbaik, O Allah''s Messenger (ﷺ)!" He said, "Go and call the people of Suffa to me." These people of Suffa were the guests of Islam who had no families, nor money, nor anybody to depend upon, and whenever an object of charity was brought to the Prophet, he would send it to them and would not take anything from it, and whenever any present was given to him, he used to send some for them and take some of it for himself. The order of the Prophet upset me, and I said to myself, "How will this little milk be enough for the people of As- Suffa? though I was more entitled to drink from that milk in order to strengthen myself", but behold! The Prophet (ﷺ) came to order me to give that milk to them. I wondered what will remain of that milk for me, but anyway, I could not but obey Allah and His Apostle so I went to the people of As-Suffa and called them, and they came and asked the Prophet''s permission to enter. They were admitted and took their seats in the house. The Prophet (ﷺ) said, "O Aba-Hirr!" I said, "Labbaik, O Allah''s Messenger (ﷺ)!" He said, "Take it and give it to them." So I took the bowl (of milk) and started giving it to one man who would drink his fill and return it to me, whereupon I would give it to another man who, in his turn, would drink his fill and return it to me, and I would then offer it to another man who would drink his fill and return it to me. Finally, after the whole group had drunk their fill, I reached the Prophet (ﷺ) who took the bowl and put it on his hand, looked at me and smiled and said. "O Aba Hirr!" I replied, "Labbaik, O Allah''s Messenger (ﷺ)!" He said, "There remain you and I." I said, "You have said the truth, O Allah''s Messenger (ﷺ)!" He said, "Sit down and drink." I sat down and drank. He said, "Drink," and I drank. He kept on telling me repeatedly to drink, till I said, "No. by Allah Who sent you with the Truth, I have no space for it (in my stomach)." He said, "Hand it over to me." When I gave him the bowl, he praised Allah and pronounced Allah''s Name on it and drank the remaining milk', 'Sahih al-Bukhari 6452'),
('bukhari:92', 'Narrated Abu Musa:The Prophet (ﷺ) was asked about things which he did not like, but when the questioners insisted, the Prophet got angry. He then said to the people, "Ask me anything you like." A man asked, "Who is my father?" The Prophet (ﷺ) replied, "Your father is Hudhafa." Then another man got up and said, "Who is my father, O Allah''s Messenger (ﷺ) ?" He replied, "Your father is Salim, Maula (the freed slave) of Shaiba." So when `Umar saw that (the anger) on the face of the Prophet (ﷺ) he said, "O Allah''s Messenger (ﷺ)! We repent to Allah (Our offending you)', 'Sahih al-Bukhari 92'),
('bukhari:16', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever possesses the following three qualities will have the sweetness (delight) of faith: 1. The one to whom Allah and His Apostle become dearer than anything else. 2. Who loves a person and he loves him only for Allah''s sake. 3. Who hates to revert to Atheism (disbelief) as he hates to be thrown into the fire', 'Sahih al-Bukhari 16'),
('bukhari:6492', 'Narrated Ghailan:Anas said "You people do (bad) deeds (commit sins) which seem in your eyes as tiny (minute) than hair while we used to consider those (very deeds) during the life-time of the Prophet (ﷺ) as destructive sins', 'Sahih al-Bukhari 6492'),
('bukhari:6563', 'Narrated `Adi bin Hatim:The Prophet (ﷺ) mentioned the Fire and turned his face aside and asked for Allah''s protection from it, and then again he mentioned the Fire and turned his face aside and asked for Allah''s protection from it and said, "Protect yourselves from the Hell-Fire, even if with one half of a date, and he who cannot afford that, then (let him do so) by (saying) a good, pleasant word', 'Sahih al-Bukhari 6563'),
('qudsi:24', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: If Allah has loved a servant [of His] He calls Gabriel (on whom be peace) and says: I love So-and-so, therefore love him. He (the Prophet (ﷺ) ﷺ) said: So Gabriel loves him. Then he (Gabriel) calls out in heaven, saying: Allah loves So-and-so, therefore love him. And the inhabitants of heaven love him. He (the Prophet (ﷺ) ﷺ) said: Then acceptance is established for him on earth. And if Allah has abhorred a servant [of His], He calls Gabriel and says: I abhor So-and-so, therefore abhor him. So Gabriel abhors him. Then Gabriel calls out to the inhabitants of heaven: Allah abhors So-and-so, therefore abhor him. He (the Prophet (ﷺ) ﷺ) said: So they abhor him, and abhorrence is established for him on earth. It was related by Muslim (also by al-Bukhari, Malik, and at-Tirmidhi)', '40 Hadith Qudsi, Hadith 24'),
('bukhari:6577', 'Narrated Ibn `Umar:The Prophet (ﷺ) said, "There will be a tank (Lake-Fount) in front of you as large as the distance between Jarba and Adhruh (two towns in Sham)', 'Sahih al-Bukhari 6577'),
('bukhari:26', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) was asked, "What is the best deed?" He replied, "To believe in Allah and His Apostle (Muhammad). The questioner then asked, "What is the next (in goodness)? He replied, "To participate in Jihad (religious fighting) in Allah''s Cause." The questioner again asked, "What is the next (in goodness)?" He replied, "To perform Hajj (Pilgrim age to Mecca) ''Mubrur, (which is accepted by Allah and is performed with the intention of seeking Allah''s pleasure only and not to show off and without committing a sin and in accordance with the traditions of the Prophet)', 'Sahih al-Bukhari 26'),
('bukhari:9', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "Faith (Belief) consists of more than sixty branches (i.e. parts). And Haya (This term "Haya" covers a large number of concepts which are to be taken together; amongst them are self respect, modesty, bashfulness, and scruple, etc.) is a part of faith', 'Sahih al-Bukhari 9'),
('bukhari:6556', 'Abu Sa`id added:"As you see a glittering star remaining in the eastern horizon and the western horizon', 'Sahih al-Bukhari 6556'),
('bukhari:6458', 'Narrated `Aisha:A complete month would pass by during which we would not make a fire (for cooking), and our food used to be only dates and water unless we were given a present of some meat', 'Sahih al-Bukhari 6458'),
('bukhari:6546', 'Narrated `Imran:The Prophet (ﷺ) said, "I looked into paradise and saw that the majority of its people were the poor, and I looked into the Fire and found that the majority of its people were women', 'Sahih al-Bukhari 6546'),
('bukhari:6426', 'Narrated `Uqba bin ''Amir:The Prophet (ﷺ) went out and offered the funeral prayer for the martyrs of the (battle of) Uhud and then ascended the pulpit and said, "I am your predecessor and I am a witness against you. By Allah, I am now looking at my Tank-lake (Al-Kauthar) and I have been given the keys of the treasures of the earth (or the keys of the earth). By Allah! I am not afraid that after me you will worship others besides Allah, but I am afraid that you will start competing for (the pleasures of) this world', 'Sahih al-Bukhari 6426'),
('bukhari:6542', 'Narrated Abu Huraira:I heard Allah''s Messenger (ﷺ) saying, "From my followers there will enter Paradise a crowd, seventy thousand in number, whose faces will glitter as the moon does when it is full." On hearing that, ''Ukasha bin Mihsan Al-Asdi got up, lifting his covering sheet, and said, "O Allah''s Messenger (ﷺ)! Invoke Allah that He may make me one of them." The Prophet (ﷺ) said, "O Allah, make him one of them." Another man from the Ansar got up and said, "O Allah''s Messenger (ﷺ)! Invoke Allah to make me one of them. "The Prophet (ﷺ) said (to him), "''Ukasha has preceded you', 'Sahih al-Bukhari 6542'),
('bukhari:6547', 'Narrated Usama:The Prophet (ﷺ) said, "I stood at the gate of Paradise and saw that the majority of the people who had entered it were poor people, while the rich were forbidden (to enter along with the poor, because they were waiting the reckoning of their accounts), but the people of the Fire had been ordered to be driven to the Fire. And I stood at the gate of the Fire and found that the majority of the people entering it were women', 'Sahih al-Bukhari 6547'),
('bukhari:94', 'Narrated Anas:Whenever the Prophet (ﷺ) asked permission to enter, he knocked the door thrice with greeting and whenever he spoke a sentence (said a thing) he used to repeat it thrice. (See Hadith No. 261, Vol)', 'Sahih al-Bukhari 94'),
('bukhari:6584', 'Abu Hazim added:An-Nu`man bin Abi `Aiyash, on hearing me, said. "Did you hear this from Sahl?" I said, "Yes." He said, " I bear witness that I heard Abu Sa`id Al-Khudri saying the same, adding that the Prophet (ﷺ) said: ''I will say: They are of me (i.e. my followers). It will be said, ''You do not know what they innovated (new things) in the religion after you left''. I will say, ''Far removed, far removed (from mercy), those who changed (their religion) after me', 'Sahih al-Bukhari 6584'),
('qudsi:20', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: The gates of Paradise will be opened on Mondays and on Thursdays, and every servant [of Allah] who associates nothing with Allah will be forgiven, except for the man who has a grudge against his brother. [About them] it will be said: Delay these two until they are reconciled; delay these two until they are reconciled. It was related by Muslim (also by Malik and Abu Dawud)', '40 Hadith Qudsi, Hadith 20'),
('nawawi:30', 'On the authority of Abu Tha’labah al-Kushanee — Jurthoom bin Nashir (may Allah be pleased with him) — that the Messenger of Allah (peace and blessings of Allah be upon him) said: Verily Allah ta’ala has laid down religious obligations (fara’id), so do not neglect them; and He has set limits, so do not overstep them; and He has forbidden some things, so do not violate them; and He has remained silent about some things, out of compassion for you, not forgetfulness — so do not seek after them. A hasan hadeeth narrated by ad-Daraqutnee and others', '40 Hadith Nawawi, Hadith 30'),
('bukhari:38', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah''s rewards, then all his past sins will be forgiven', 'Sahih al-Bukhari 38'),
('bukhari:123', 'Narrated Abu Musa:A man came to the Prophet (ﷺ) and asked, "O Allah''s Messenger (ﷺ)! What kind of fighting is in Allah''s cause? (I ask this), for some of us fight because of being enraged and angry and some for the sake of his pride and haughtiness." The Prophet (ﷺ) raised his head (as the questioner was standing) and said, "He who fights so that Allah''s Word (Islam) should be superior, then he fights in Allah''s cause', 'Sahih al-Bukhari 123'),
('bukhari:6417', 'Narrated `Abdullah:The Prophet (ﷺ) drew a square and then drew a line in the middle of it and let it extend outside the square and then drew several small lines attached to that central line, and said, "This is the human being, and this, (the square) in his lease of life, encircles him from all sides (or has encircled him), and this (line), which is outside (the square), is his hope, and these small lines are the calamities and troubles (which may befall him), and if one misses him, an-other will snap (i.e. overtake) him, and if the other misses him, a third will snap (i.e. overtake) him', 'Sahih al-Bukhari 6417'),
('bukhari:6562', 'Narrated An-Nu`man bin Bashir:I heard the Prophet (ﷺ) saying, "The least punished person of the (Hell) Fire people on the Day of Resurrection will be a man under whose arch of the feet two smoldering embers will be placed, because of which his brain will boil just like Al-Mirjal (copper vessel) or a Qum-qum (narrow-necked vessel) is boiling with water', 'Sahih al-Bukhari 6562'),
('nawawi:11', 'On the authority of Abu Muhammad al-Hasan ibn Ali ibn Abee Talib (may Allah be pleased with him), the grandson of the Messenger of Allah (peace and blessings of Allah be upon him), and the one much loved by him, who said: I memorised from the Messenger of Allah (peace and blessings of Allah be upon him): “Leave that which makes you doubt for that which does not make you doubt.” [At-Tirmidhi] [An-Nasai] At-Tirmidhi said that it was a good and sound (hasan saheeh) hadeeth', '40 Hadith Nawawi, Hadith 11'),
('qudsi:9', 'On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (mighty and sublime be He) says: The first of his actions for which a servant of Allah will be held accountable on the Day of Resurrection will be his prayers. If they are in order, then he will have prospered and succeeded: and if they are wanting, then he will have failed and lost. If there is something defective in his obligatory prayers, the Lord (glorified and exalted be He) will say: See if My servant has any supererogatory prayers with which may be completed that which was defective in his obligatory prayers. Then the rest of his actions will be judged in like fashion. It was related by at-Tirmidhi (also by Abu Dawud, an-Nasa''i, Ibn Majah and Ahmad)', '40 Hadith Qudsi, Hadith 9'),
('bukhari:6456', 'Narrated `Aisha:The bed mattress of the Prophet (ﷺ) was made of a leather case stuffed with palm fibres', 'Sahih al-Bukhari 6456'),
('bukhari:110', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "Name yourselves with my name (use my name) but do not name yourselves with my Kunya name (i.e. Abul Qasim). And whoever sees me in a dream then surely he has seen me for Satan cannot impersonate me. And whoever tells a lie against me (intentionally), then (surely) let him occupy his seat in Hell-fire', 'Sahih al-Bukhari 110'),
('qudsi:2', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah Almighty has said: The son of Adam denied Me and he had no right to do so. And he reviled Me and he had no right to do so. As for his denying Me, it is his saying: He will not remake me as He made me at first (1) - and the initial creation [of him] is no easier for Me than remaking him. As for his reviling Me, it is his saying: Allah has taken to Himself a son, while I am the One, the Everlasting Refuge. I begot not nor was I begotten, and there is none comparable to Me.(1) i.e., bring me back to life after death. It was related by al-Bukhari (also by an-Nasa''i)', '40 Hadith Qudsi, Hadith 2'),
('bukhari:6467', 'Narrated `Aisha:The Prophet (ﷺ) said, "Do good deeds properly, sincerely and moderately, and receive good news because one''s good deeds will not make him enter Paradise." They asked, "Even you, O Allah''s Messenger (ﷺ)?" He said, "Even I, unless and until Allah bestows His pardon and Mercy on me', 'Sahih al-Bukhari 6467'),
('qudsi:15', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Prophet (ﷺ) said: Allah the Almighty said: I am as My servant thinks I am (1). I am with him when he makes mention of Me. If he makes mention of Me to himself, I make mention of him to Myself; and if he makes mention of Me in an assembly, I make mention of him in an assembly better than it. And if he draws near to Me an arm''s length, I draw near to him a cubit, and if he draws near to Me a cubit, I draw near to him a fathom. And if he comes to Me walking, I go to him at speed. (1) Another possible rendering of the Arabic is: "I am as My servant expects Me to be". The meaning is that forgiveness and acceptance of repentance by the Almighty is subject to His servant truly believing that He is forgiving and merciful. However, not to accompany such belief with right action would be to mock the Almighty. It was related by al-Buhkari (also by Muslim, at-Tirmidhi and Ibn-Majah)', '40 Hadith Qudsi, Hadith 15'),
('nawawi:36', 'On the authority of Abu Hurayrah (may Allah be pleased with him), that the Prophet (peace and blessings of Allah be upon him) said: Whoever removes a worldly grief from a believer, Allah will remove from him one of the griefs of the Day of Resurrection. And whoever alleviates the need of a needy person, Allah will alleviate his needs in this world and the Hereafter. Whoever shields [or hides the misdeeds of] a Muslim, Allah will shield him in this world and the Hereafter. And Allah will aid His slave so long as he aids his brother. And whoever follows a path to seek knowledge therein, Allah will make easy for him a path to Paradise. No people gather together in one of the Houses of Allah, reciting the Book of Allah and studying it among themselves, except that sakeenah (tranquility) descends upon them, and mercy envelops them, and the angels surround them, and Allah mentions them amongst those who are with Him. And whoever is slowed down by his actions, will not be hastened forward by his lineage. Related by [Muslim] in these words', '40 Hadith Nawawi, Hadith 36'),
('nawawi:10', 'On the authority of Abu Hurayrah (ra): The Messenger of Allah (ﷺ) said, “Allah the Almighty is Good and accepts only that which is good. And verily Allah has commanded the believers to do that which He has commanded the Messengers. So the Almighty has said: “O (you) Messengers! Eat of the tayyibat [all kinds of halal (legal) foods], and perform righteous deeds.” [23:51] and the Almighty has said: “O you who believe! Eat of the lawful things that We have provided you.” [2:172]” Then he (ﷺ) mentioned [the case] of a man who, having journeyed far, is disheveled and dusty, and who spreads out his hands to the sky saying “O Lord! O Lord!,” while his food is haram (unlawful), his drink is haram, his clothing is haram, and he has been nourished with haram, so how can [his supplication] be answered? [Muslim]', '40 Hadith Nawawi, Hadith 10'),
('qudsi:14', 'On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (glorified and exalted be He) has supernumerary angels who rove about seeking out gatherings in which Allah''s name is being invoked: they sit with them and fold their wings round each other, filling that which is between them and between the lowest heaven. When [the people in the gathering] depart, [the angels] ascend and rise up to heaven. He (the Prophet (ﷺ)) said: Then Allah (mighty and sublime be He) asks them - [though] He is most knowing about them: From where have you come? And they say: We have come from some servants of Yours on Earth: they were glorifying You (Subhana llah), exalting you (Allahu akbar), witnessing that there is no god but You (La ilaha illa llah), praising You (Al-Hamdu lillah), and asking [favours] of You. He says: And what do they ask of Me? They say: They ask of You Your Paradise. He says: And have they seen My Paradise? They say: No, O Lord. He says: And how would it be were they to have seen My Paradise! They say: And they ask protection of You. He says: From what do they ask protection of Me? They say: From Your Hell-fire, O Lord. He says: And have they seen My Hell-fire? They say: NO. He says: And how would it be were they to have seen My Hell-fire: They say: And they ask for Your forgiveness. He (the Prophet (ﷺ)) said: Then He says: I have forgiven them and I have bestowed upon them what they have asked for, and I have granted them sanctuary from that from which they asked protection. He (the Prophet (ﷺ) ﷺ) said: They say: O Lord, among them is So-and-so, a much sinning servant, who was merely passing by and sat down with them. He (the Prophet (ﷺ) ﷺ) said: And He says: And to him [too] I have given forgiveness: he who sits with such people shall not suffer. It was related by Muslim (also by al-Bukhari, at-Tirmidhi, and an-Nasa''i)', '40 Hadith Qudsi, Hadith 14'),
('bukhari:62', 'Narrated Ibn `Umar:The Prophet (ﷺ) said, "Amongst the trees, there is a tree, the leaves of which do not fall and is like a Muslim. Tell me the name of that tree." Everybody started thinking about the trees of the desert areas. And I thought of the date-palm tree. The others then asked, "Please inform us what is that tree, O Allah''s Messenger (ﷺ)?" He replied, "It is the date-palm tree', 'Sahih al-Bukhari 62'),
('bukhari:6578', 'Narrated Ibn `Abbas:The word ''Al-Kauthar'' means the abundant good which Allah gave to him (the Prophet Muhammad (ﷺ)). Abu Bishr said: I said to Sa`id, "Some people claim that it (Al-Kauthar) is a river in Paradise." Sa`id replied, "The river which is in Paradise is one item of that good which Allah has bestowed upon him (Muhammad)', 'Sahih al-Bukhari 6578'),
('nawawi:32', 'On the authority of Abu Sa’eed al-Khudree (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: There should be neither harming (darar) nor reciprocating harm (dirar). A hasan hadeeth related by Ibn Majah, ad-Daraqutnee and others as a musnad hadeeth. It was also related by Malik in al-Muwatta in mursal form from Amr bin Yahya, from his father from the Prophet (peace and blessings of Allah be upon him), but leaving Abu Sa’eed from the chain. And it has other chains of narrations that strengthen one another', '40 Hadith Nawawi, Hadith 32'),
('bukhari:6512', 'Narrated Abu Qatada bin Rib''i Al-Ansari:A funeral procession passed by Allah''s Messenger (ﷺ) who said, "Relieved or relieving?" The people asked, "O Allah''s Messenger (ﷺ)! What is relieved and relieving?" He said, "A believer is relieved (by death) from the troubles and hardships of the world and leaves for the Mercy of Allah, while (the death of) a wicked person relieves the people, the land, the trees, (and) the animals from him', 'Sahih al-Bukhari 6512'),
('bukhari:6533', 'Narrated `Abdullah:The Prophet (ﷺ) said, "The cases which will be decided first (on the Day of Resurrection) will be the cases of blood-shedding', 'Sahih al-Bukhari 6533'),
('bukhari:50', 'Narrated Abu Huraira: One day while the Prophet (ﷺ) was sitting in the company of some people, (The angel) Gabriel came and asked, "What is faith?" Allah''s Messenger (ﷺ) replied, ''Faith is to believe in Allah, His angels, (the) meeting with Him, His Apostles, and to believe in Resurrection." Then he further asked, "What is Islam?" Allah''s Messenger (ﷺ) replied, "To worship Allah Alone and none else, to offer prayers perfectly to pay the compulsory charity (Zakat) and to observe fasts during the month of Ramadan." Then he further asked, "What is Ihsan (perfection)?" Allah''s Messenger (ﷺ) replied, "To worship Allah as if you see Him, and if you cannot achieve this state of devotion then you must consider that He is looking at you." Then he further asked, "When will the Hour be established?" Allah''s Messenger (ﷺ) replied, "The answerer has no better knowledge than the questioner. But I will inform you about its portents. 1. When a slave (lady) gives birth to her master. 2. When the shepherds of black camels start boasting and competing with others in the construction of higher buildings. And the Hour is one of five things which nobody knows except Allah. The Prophet (ﷺ) then recited: "Verily, with Allah (Alone) is the knowledge of the Hour--." (31. 34) Then that man (Gabriel) left and the Prophet (ﷺ) asked his companions to call him back, but they could not see him. Then the Prophet (ﷺ) said, "That was Gabriel who came to teach the people their religion." Abu ''Abdullah said: He (the Prophet) considered all that as a part of faith', 'Sahih al-Bukhari 50'),
('qudsi:36', 'On the authority of Anas (may Allah be pleased with him) from the Prophet (ﷺ), who said: The believers will gather together on the Day of Resurrection and will say: Should we not ask [someone] to intercede for us with our Lord? So they will come to Adam and will say: You are the Father of mankind; Allah created you with His hand, He made His angels bow down to you and He taught you the names of everything, so intercede for us with your Lord so that He may give us relief form this place where we are. And he will say: I am not in a position [to do that] - and he will mention his wrongdoing and will feel ashamed and will say: Go to Noah, for he is the first messenger that Allah sent to the inhabitants of the earth. So they will come to him and he will say: I am not in a position [to do that] - and he will mention his having requested something of his Lord about which he had no [proper] knowledge (Quran 11:45-46), and he will feel ashamed and will say: Go to the Friend of the Merciful (Abraham). So they will come to him and he will say: I am not in a position [to do that]. Go to Moses, a servant to whom Allah talked and to whom He gave the Torah. So they will come to him and he will say: I am not in a position [to do that] - and he will mention the taking of a life other that for a life (Quran 28:15-16), and he will feel ashamed in the sight of his Lord and will say: Go to Jesus, Allah''s servant and messenger, Allah''s word and spirit. So they will come to him and he will say: I am not in a position [to do that]. Go to Muhammad (ﷺ), a servant to whom Allah has forgiven all his wrongdoing, past and future. So they will come to me and I shall set forth to ask permission to come to my Lord, and permission will be given, and when I shall see my Lord I shall prostrate myself. He will leave me thus for such time as it pleases Him, and then it will be said [to me]: Raise your head. Ask and it will be granted. Speak and it will be heard. Intercede and your intercession will be accepted. So I shall raise my head and praise Him with a form of praise that He will teach me. Then I shall intercede and He will set me a limit [as to the number of people], so I shall admit them into Paradise. Then I shall return to Him, and when I shall see my Lord [I shall bow down] as before. Then I shall intercede and He will set me a limit [as to the number of people]. So I shall admit them into Paradise. Then I shall return for a third time, then a fourth, and I shall say: There remains in Hell-fire only those whom the Qur''an has confined and who must be there for eternity. There shall come out of Hell-fire he who has said: There is no god but Allah and who has in his heart goodness weighing a barley-corn; then there shall come out of Hell-fire he who has said: There is no god but Allah and who has in his heart goodness weighing a grain of wheat; then there shall come out of Hell-fire he who has said: There is no god but Allah and who has in his heart goodness weighing an atom. It was related by al-Bukhari (also by Muslim, at-Tirmidhi, and Ibn Majah)', '40 Hadith Qudsi, Hadith 36'),
('bukhari:129', 'Narrated Anas:I was informed that the Prophet (ﷺ) had said to Mu`adh, "Whosoever will meet Allah without associating anything in worship with Him will go to Paradise." Mu`adh asked the Prophet, "Should I not inform the people of this good news?" The Prophet (ﷺ) replied, "No, I am afraid, lest they should depend upon it (absolutely)', 'Sahih al-Bukhari 129'),
('bukhari:6453', 'Narrated Sa`d:I was the first man among the Arabs to throw an arrow for Allah''s Cause. We used to fight in Allah''s Cause while we had nothing to eat except the leaves of the Hubla and the Sumur trees (desert trees) so that we discharged excrement like that of sheep (i.e. unmixed droppings). Today the (people of the) tribe of Bani Asad teach me the laws of Islam. If so, then I am lost, and all my efforts of that hard time had gone in vain', 'Sahih al-Bukhari 6453'),
('bukhari:6488', 'Narrated `Abdullah:The Prophet (ﷺ) said, "Paradise is nearer to any of you than the Shirak (leather strap) of his shoe, and so is the (Hell) Fire', 'Sahih al-Bukhari 6488'),
('bukhari:6552', 'Narrated Sahl bin Sa''d: Allah''s Messenger (ﷺ) said, "In Paradise there is a tree so big that in its shade a rider may travel for one hundred years without being able to cross it', 'Sahih al-Bukhari 6552'),
('bukhari:6481', 'Narrated Abu Sa`id:The Prophet (ﷺ) mentioned a man from the previous generation or from the people preceding your age whom Allah had given both wealth and children. The Prophet (ﷺ) said, "When the time of his death approached, he asked his children, ''What type of father have I been to you?'' They replied: You have been a good father. He said, ''But he (i.e. your father) has not stored any good deeds with Allah (for the Hereafter): if he should face Allah, Allah will punish him. So listen, (O my children), when I die, burn my body till I become mere coal and then grind it into powder, and when there is a stormy wind, throw me (my ashes) in it.'' So he took a firm promise from his children (to follow his instructions). And by Allah they (his sons) did accordingly(fulfilled their promise.) Then Allah said, "Be"'' and behold! That man was standing there! Allah then said. "O my slave! What made you do what you did?" That man said, "Fear of You." So Allah forgave him', 'Sahih al-Bukhari 6481'),
('nawawi:27', 'On the authority of an-Nawas bin Sam’an (may Allah be pleased with him), that the Prophet (peace and blessings of Allah be upon him) said: Righteousness is in good character, and wrongdoing is that which wavers in your soul, and which you dislike people finding out about. [Muslim] And on the authority of Wabisah bin Ma’bad (may Allah be pleased with him) who said: I came to the Messenger of Allah (peace and blessings of Allah be upon him) and he (peace and blessings of Allah be upon him) said, “You have come to ask about righteousness.” I said, “Yes.” He (peace and blessings of Allah be upon him) said, “Consult your heart. Righteousness is that about which the soul feels at ease and the heart feels tranquil. And wrongdoing is that which wavers in the soul and causes uneasiness in the breast, even though people have repeatedly given their legal opinion [in its favour].” A good hadeeth transmitted from the musnads of the two imams, Ahmed bin Hambal and Al- Darimi, with a good chain of authorities', '40 Hadith Nawawi, Hadith 27'),
('bukhari:6591', 'Narrated Haritha bin Wahb:I heard the Prophet (ﷺ) mentioning the Lake-Fount (Al-Kauthar), saying, "(The width of the Lake-Fount) is equal to the distance between Medina and Sana'' (capital of Yemen)', 'Sahih al-Bukhari 6591'),
('bukhari:25', 'Narrated Ibn ''Umar: Allah''s Messenger (ﷺ) said: "I have been ordered (by Allah) to fight against the people until they testify that none has the right to be worshipped but Allah and that Muhammad is Allah''s Messenger (ﷺ), and offer the prayers perfectly and give the obligatory charity, so if they perform that, then they save their lives and property from me except for Islamic laws and then their reckoning (accounts) will be done by Allah', 'Sahih al-Bukhari 25'),
('bukhari:6493', 'Narrated Sa`d bin Sahl As-Sa`idi:The Prophet (ﷺ) looked at a man fighting against the pagans and he was one of the most competent persons fighting on behalf of the Muslims. The Prophet (ﷺ) said, "Let him who wants to look at a man from the dwellers of the (Hell) Fire, look at this (man)." Another man followed him and kept on following him till he (the fighter) was injured and, seeking to die quickly, he placed the blade tip of his sword between his breasts and leaned over it till it passed through his shoulders (i.e., committed suicide)." The Prophet (ﷺ) added, "A person may do deeds that seem to the people as the deeds of the people of Paradise while in fact, he is from the dwellers of the (Hell) Fire: and similarly a person may do deeds that seem to the people as the deeds of the people of the (Hell) Fire while in fact, he is from the dwellers of Paradise. Verily, the (results of) deeds done, depend upon the last actions', 'Sahih al-Bukhari 6493'),
('bukhari:132', 'Narrated `Ali:I used to get the emotional urethral discharge frequently so I requested Al-Miqdad to ask the Prophet (ﷺ) about it. Al-Miqdad asked him and he replied, "One has to perform ablution (after it)." (See Hadith No)', 'Sahih al-Bukhari 132'),
('bukhari:6472', 'Narrated Ibn `Abbas:Allah''s Messenger (ﷺ) said, "Seventy thousand people of my followers will enter Paradise without accounts, and they are those who do not practice Ar-Ruqya and do not see an evil omen in things, and put their trust in their Lord', 'Sahih al-Bukhari 6472'),
('bukhari:29', 'Narrated Ibn ''Abbas: The Prophet (ﷺ) said: "I was shown the Hell-fire and that the majority of its dwellers were women who were ungrateful." It was asked, "Do they disbelieve in Allah?" (or are they ungrateful to Allah?) He replied, "They are ungrateful to their husbands and are ungrateful for the favors and the good (charitable deeds) done to them. If you have always been good (benevolent) to one of them and then she sees something in you (not of her liking), she will say, ''I have never received any good from you', 'Sahih al-Bukhari 29'),
('bukhari:28', 'Narrated ''Abdullah bin ''Amr: A person asked Allah''s Messenger (ﷺ), "What (sort of) deeds in or (what qualities of) Islam are good?" He replied, "To feed (the poor) and greet those whom you know and those whom you don''t know', 'Sahih al-Bukhari 28'),
('bukhari:6430', 'Narrated Qais:I heard Khabbab, who had branded his `Abdomen with seven brands, saying, "Had Allah''s Messenger (ﷺ) not forbidden us to invoke Allah for death, I would have invoked Allah for death. The companions of Muhammad have left this world without taking anything of their reward in it (i.e., they will have perfect reward in the Hereafter), but we have collected of the worldly wealth what we cannot spend but on earth (i.e. on building houses)', 'Sahih al-Bukhari 6430'),
('bukhari:6553', 'Narrated Abu Sa''id: The Prophet (ﷺ) said: There is a tree in Paradise (so huge) that a fast (or a trained) rider may travel: for one hundred years without being able to cross it', 'Sahih al-Bukhari 6553'),
('bukhari:22', 'Narrated Abu Said Al-Khudri: The Prophet (ﷺ) said, "When the people of Paradise will enter Paradise and the people of Hell will go to Hell, Allah will order those who have had faith equal to the weight of a grain of mustard seed to be taken out from Hell. So they will be taken out but (by then) they will be blackened (charred). Then they will be put in the river of Haya'' (rain) or Hayat (life) (the Narrator is in doubt as to which is the right term), and they will revive like a grain that grows near the bank of a flood channel. Don''t you see that it comes out yellow and twisted?', 'Sahih al-Bukhari 22'),
('bukhari:69', 'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Facilitate things to people (concerning religious matters), and do not make it hard for them and give them good tidings and do not make them run away (from Islam)', 'Sahih al-Bukhari 69'),
('bukhari:6555', 'Narrated Sahl:The Prophet (ﷺ) said, "The people of Paradise will see the Ghuraf (special abodes) in Paradise as you see a star in the sky', 'Sahih al-Bukhari 6555'),
('bukhari:6491', 'Narrated Ibn `Abbas:The Prophet (ﷺ) narrating about his Lord I''m and said, "Allah ordered (the appointed angels over you) that the good and the bad deeds be written, and He then showed (the way) how (to write). If somebody intends to do a good deed and he does not do it, then Allah will write for him a full good deed (in his account with Him); and if he intends to do a good deed and actually did it, then Allah will write for him (in his account) with Him (its reward equal) from ten to seven hundred times to many more times: and if somebody intended to do a bad deed and he does not do it, then Allah will write a full good deed (in his account) with Him, and if he intended to do it (a bad deed) and actually did it, then Allah will write one bad deed (in his account)', 'Sahih al-Bukhari 6491'),
('bukhari:6497', 'Narrated Hudhaifa:Allah''s Messenger (ﷺ) narrated to us two narrations, one of which I have seen (happening) and I am waiting for the other. He narrated that honesty was preserved in the roots of the hearts of men (in the beginning) and then they learnt it (honesty) from the Qur''an, and then they learnt it from the (Prophet''s) Sunna (tradition). He also told us about its disappearance, saying, "A man will go to sleep whereupon honesty will be taken away from his heart, and only its trace will remain, resembling the traces of fire. He then will sleep whereupon the remainder of the honesty will also be taken away (from his heart) and its trace will resemble a blister which is raised over the surface of skin, when an ember touches one''s foot; and in fact, this blister does not contain anything. So there will come a day when people will deal in business with each other but there will hardly be any trustworthy persons among them. Then it will be said that in such-and-such a tribe there is such-and-such person who is honest, and a man will be admired for his intelligence, good manners and strength, though indeed he will not have belief equal to a mustard seed in his heart." The narrator added: There came upon me a time when I did not mind dealing with anyone of you, for if he was a Muslim, his religion would prevent him from cheating; and if he was a Christian, his Muslim ruler would prevent him from cheating; but today I cannot deal except with so-and-so and so-and-so. (See Hadith No. 208, Vol)', 'Sahih al-Bukhari 6497'),
('bukhari:100', 'Narrated `Abdullah bin `Amr bin Al-`As:I heard Allah''s Messenger (ﷺ) saying, "Allah does not take away the knowledge, by taking it away from (the hearts of) the people, but takes it away by the death of the religious learned men till when none of the (religious learned men) remains, people will take as their leaders ignorant persons who when consulted will give their verdict without knowledge. So they will go astray and will lead the people astray', 'Sahih al-Bukhari 100'),
('bukhari:6586', 'Narrated Ibn Al-Musaiyab:The companions of the Prophet (ﷺ) said, "Some men from my companions will come to my Lake-Fount and they will be driven away from it, and I will say, ''O Lord, my companions!'' It will be said, ''You have no knowledge of what they innovated after you left: they turned apostate as renegades (reverted from Islam)', 'Sahih al-Bukhari 6586'),
('bukhari:12', 'Narrated ''Abdullah bin ''Amr: A man asked the Prophet (ﷺ) , "What sort of deeds or (what qualities of) Islam are good?" The Prophet (ﷺ) replied, ''To feed (the poor) and greet those whom you know and those whom you do not Know (See Hadith No)', 'Sahih al-Bukhari 12'),
('qudsi:19', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: Pride is my cloak and greatness My robe, and he who competes with Me in respect of either of them I shall cast into Hell-fire. It was related by Abu Dawud (also by Ibn Majah and Ahmad) with sound chains of authority. This Hadith also appears in Muslim in another version', '40 Hadith Qudsi, Hadith 19'),
('bukhari:90', 'Narrated Abu Mas`ud Al-Ansari:Once a man said to Allah''s Messenger (ﷺ) "O Allah''s Messenger (ﷺ)! I may not attend the (compulsory congregational) prayer because so and so (the Imam) prolongs the prayer when he leads us for it. The narrator added: "I never saw the Prophet (ﷺ) more furious in giving advice than he was on that day. The Prophet said, "O people! Some of you make others dislike good deeds (the prayers). So whoever leads the people in prayer should shorten it because among them there are the sick the weak and the needy (having some jobs to do)', 'Sahih al-Bukhari 90'),
('bukhari:6438', 'Narrated Sahl bin Sa`d:I heard Ibn Az-Zubair who was on the pulpit at Mecca, delivering a sermon, saying, "O men! The Prophet used to say, "If the son of Adam were given a valley full of gold, he would love to have a second one; and if he were given the second one, he would love to have a third, for nothing fills the belly of Adam''s son except dust. And Allah forgives he who repents to Him." Ubai said, "We considered this as a saying from the Qur''an till the Sura (beginning with) ''The mutual rivalry for piling up of worldly things diverts you..'' (102.1) was revealed', 'Sahih al-Bukhari 6438'),
('bukhari:6538', 'Narrated Anas bin Malik:Allah''s Prophet used to say, "A disbeliever will be brought on the Day of Resurrection and will be asked. "Suppose you had as much gold as to fill the earth, would you offer it to ransom yourself?" He will reply, "Yes." Then it will be said to him, "You were asked for something easier than that (to join none in worship with Allah (i.e. to accept Islam, but you refused)', 'Sahih al-Bukhari 6538'),
('bukhari:6589', 'Narrated Jundab:I heard the Prophet, saying, "I am your predecessor at the Lake-Fount. (Al-Kauthar)', 'Sahih al-Bukhari 6589'),
('bukhari:6484', 'Narrated `Abdullah bin `Amr:The Prophet (ﷺ) said, "A Muslim is the one who avoids harming Muslims with his tongue or his hands. And a Muhajir (an emigrant) is the one who gives up (abandons) all what Allah has forbidden', 'Sahih al-Bukhari 6484'),
('bukhari:6590', 'Narrated `Uqba bin ''Amir:Once the Prophet (ﷺ) went out and offered the funeral prayers for the martyrs of Uhud, and then went to the pulpit and said, "I am a predecessor for you and I am a witness for you: and by Allah, I am looking at my Fount just now, and the keys of the treasures of the earth (or the keys of the earth) have been given to me: and by Allah, I am not afraid that you will worship others besides Allah after me, but I am afraid that you will strive and struggle against each other over these treasures of the world', 'Sahih al-Bukhari 6590'),
('bukhari:49', 'Narrated ''Ubada bin As-Samit:"Allah''s Messenger (ﷺ) went out to inform the people about the (date of the) night of decree (Al-Qadr) but there happened a quarrel between two Muslim men. The Prophet (ﷺ) said, "I came out to inform you about (the date of) the night of Al-Qadr, but as so and so and so and so quarrelled, its knowledge was taken away (I forgot it) and maybe it was better for you. Now look for it in the 7th, the 9th and the 5th (of the last 10 nights of the month of Ramadan)', 'Sahih al-Bukhari 49'),
('bukhari:6531', 'Narrated Ibn `Umar:The Prophet (ﷺ) said (regarding the Verse), "A Day when all mankind will stand before the Lord of the Worlds,'' (that day) they will stand, drowned in their sweat up to the middle of their ears', 'Sahih al-Bukhari 6531'),
('bukhari:103', 'Narrated Ibn Abu Mulaika:Whenever `Aisha (the wife of the Prophet) heard anything which she did not understand, she used to ask again till she understood it completely. Aisha said: "Once the Prophet (ﷺ) said, "Whoever will be called to account (about his deeds on the Day of Resurrection) will surely be punished." I said, "Doesn''t Allah say: "He surely will receive an easy reckoning." (84.8) The Prophet (ﷺ) replied, "This means only the presentation of the accounts but whoever will be argued about his account, will certainly be ruined', 'Sahih al-Bukhari 103'),
('bukhari:47', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "(A believer) who accompanies the funeral procession of a Muslim out of sincere faith and hoping to attain Allah''s reward and remains with it till the funeral prayer is offered and the burial ceremonies are over, he will return with a reward of two Qirats. Each Qirat is like the size of the (Mount) Uhud. He who offers the funeral prayer only and returns before the burial, will return with the reward of one Qirat only', 'Sahih al-Bukhari 47'),
('bukhari:58', 'Narrated Ziyad bin''Ilaqa: I heard Jarir bin ''Abdullah (Praising Allah). On the day when Al-Mughira bin Shu''ba died, he (Jarir) got up (on the pulpit) and thanked and praised Allah and said, "Be afraid of Allah alone Who has none along with Him to be worshipped.(You should) be calm and quiet till the (new) chief comes to you and he will come to you soon. Ask Allah''s forgiveness for your (late) chief because he himself loved to forgive others." Jarir added, "Amma badu (now then), I went to the Prophet and said, ''I give my pledge of allegiance to you for Islam." The Prophet (ﷺ) conditioned (my pledge) for me to be sincere and true to every Muslim so I gave my pledge to him for this. By the Lord of this mosque! I am sincere and true to you (Muslims). Then Jarir asked for Allah''s forgiveness and came down (from the pulpit)', 'Sahih al-Bukhari 58'),
('bukhari:6440', 'Ubayy said (referring to the hadith above), "We considered this as a saying from the Qur''an till the Surah (beginning with):"The mutual rivalry (for piling up of worldly things) diverts you'' (102:1) was revealed', 'Sahih al-Bukhari 6440'),
('nawawi:31', 'On the authority of Abu al-’Abbas Sahl bin Sa’ad as-Sa’idee (may Allah be pleased with him) who said: A man came to the Prophet (peace and blessings of Allah be upon him) and said, “O Messenger of Allah, direct me to an act which, if I do it, [will cause] Allah to love me and the people to love me.” So he (peace and blessings of Allah be upon him) said, “Renounce the world and Allah will love you, and renounce what the people possess and the people will love you.” A hasan hadeeth related by Ibn Majah and others with good chains of authorities', '40 Hadith Nawawi, Hadith 31'),
('bukhari:6448', 'Narrated Abu Wail:We paid a visit to Khabbab who was sick, and he said, "We migrated with the Prophet (ﷺ) for Allah''s Sake and our wages became due on Allah. Some of us died without having received anything of the wages, and one of them was Mus`ab bin `Umair, who was martyred on the day of the battle of Uhud, leaving only one sheet (to shroud him in). If we covered his head with it, his feet became uncovered, and if we covered his feet with it, his head became uncovered. So the Prophet (ﷺ) ordered us to cover his head with it and put some Idhkhir (a kind of grass) over his feet. On the other hand, some of us have had the fruits (of our good deed) and are plucking them (in this world)', 'Sahih al-Bukhari 6448'),
('bukhari:6500', 'Narrated Mu`adh bin Jabal:While I was riding behind the Prophet (ﷺ) as a companion rider and there was nothing between me and him except the back of the saddle, he said, "O Mu`adh!" I replied, "Labbaik O Allah''s Messenger (ﷺ)! And Sa`daik!" He proceeded for a while and then said, "O Mu`adh!" I said, "Labbaik and Sa`daik, O Allah''s Messenger (ﷺ)!" He then proceeded for another while and said, "O Mu`adh bin Jabal!" I replied, "Labbaik, O Allah''s Messenger (ﷺ), and Sa`daik!" He said, "Do you know what is Allah''s right on His slaves?" I replied, "Allah and His Apostle know better." He said, "Allah''s right on his slaves is that they should worship Him and not worship anything besides Him." He then proceeded for a while, and again said, "O Mu`adh bin Jabal!" I replied. "Labbaik, O Allah''s Messenger (ﷺ), and Sa`daik." He said, "Do you know what is (Allah''s) slaves'' (people''s) right on Allah if they did that?" I replied, "Allah and His Apostle know better." He said, "The right of (Allah''s) slaves on Allah is that He should not punish them (if they did that)', 'Sahih al-Bukhari 6500'),
('bukhari:84', 'Narrated Ibn `Abbas:Somebody said to the Prophet (during his last Hajj), "I did the slaughtering before doing the Rami.'' The Prophet (ﷺ) beckoned with his hand and said, "There is no harm in that." Then another person said, "I got my head shaved before offering the sacrifice." The Prophet (ﷺ) beckoned with his hand saying, "There is no harm in that', 'Sahih al-Bukhari 84'),
('bukhari:6445', 'Narrated Abu Huraira:Allah''s Apostle said, "If I had gold equal to the mountain of Uhud, it would not please me that anything of it should remain with me after three nights (i.e., I would spend all of it in Allah''s Cause) except what I would keep for repaying debts', 'Sahih al-Bukhari 6445'),
('bukhari:6541', 'Narrated Ibn `Abbas:The Prophet (ﷺ) said, "The people were displayed in front of me and I saw one prophet passing by with a large group of his followers, and another prophet passing by with only a small group of people, and another prophet passing by with only ten (persons), and another prophet passing by with only five (persons), and another prophet passed by alone. And then I looked and saw a large multitude of people, so I asked Gabriel, "Are these people my followers?'' He said, ''No, but look towards the horizon.'' I looked and saw a very large multitude of people. Gabriel said. ''Those are your followers, and those are seventy thousand (persons) in front of them who will neither have any reckoning of their accounts nor will receive any punishment.'' I asked, ''Why?'' He said, ''For they used not to treat themselves with branding (cauterization) nor with Ruqya (get oneself treated by the recitation of some Verses of the Qur''an) and not to see evil omen in things, and they used to put their trust (only) in their Lord." On hearing that, ''Ukasha bin Mihsan got up and said (to the Prophet), "Invoke Allah to make me one of them." The Prophet (ﷺ) said, "O Allah, make him one of them." Then another man got up and said (to the Prophet), "Invoke Allah to make me one of them." The Prophet (ﷺ) said, ''Ukasha has preceded you', 'Sahih al-Bukhari 6541'),
('bukhari:35', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "Whoever establishes the prayers on the night of Qadr out of sincere faith and hoping to attain Allah''s rewards (not to show off) then all his past sins will be forgiven', 'Sahih al-Bukhari 35'),
('bukhari:6518', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "The people will fall down unconscious at the time when they should fall down (i.e., on the Day of Resurrection), and then I will be the first man to get up, and behold, Moses will be there holding (Allah''s) Throne. I will not know whether he has been amongst those who have fallen unconscious', 'Sahih al-Bukhari 6518'),
('bukhari:6414', 'Narrated Sahl bin Sa`d As-Sa`idi:We were in the company of Allah''s Messenger (ﷺ) in (the battle of) Al-Khandaq, and he was digging the trench while we were carrying the earth away. He looked at us and said, "O Allah! There is no life worth living except the life of the Hereafter, so (please) forgive the Ansar and the Emigrants', 'Sahih al-Bukhari 6414'),
('bukhari:53', 'Narrated Abu Jamra: I used to sit with Ibn ''Abbas and he made me sit on his sitting place. He requested me to stay with him in order that he might give me a share from his property. So I stayed with him for two months. Once he told (me) that when the delegation of the tribe of ''Abdul Qais came to the Prophet, the Prophet (ﷺ) asked them, "Who are the people (i.e. you)? (Or) who are the delegate?" They replied, "We are from the tribe of Rabi''a." Then the Prophet (ﷺ) said to them, "Welcome! O people (or O delegation of ''Abdul Qais)! Neither will you have disgrace nor will you regret." They said, "O Allah''s Messenger (ﷺ)! We cannot come to you except in the sacred month and there is the infidel tribe of Mudar intervening between you and us. So please order us to do something good (religious deeds) so that we may inform our people whom we have left behind (at home), and that we may enter Paradise (by acting on them)." Then they asked about drinks (what is legal and what is illegal). The Prophet (ﷺ) ordered them to do four things and forbade them from four things. He ordered them to believe in Allah Alone and asked them, "Do you know what is meant by believing in Allah Alone?" They replied, "Allah and His Apostle know better." Thereupon the Prophet (ﷺ) said, "It means: 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah''s Messenger (ﷺ). 2. To offer prayers perfectly 3. To pay the Zakat (obligatory charity) 4. To observe fast during the month of Ramadan. 5. And to pay Al-Khumus (one fifth of the booty to be given in Allah''s Cause). Then he forbade them four things, namely, Hantam, Dubba,'' Naqir Ann Muzaffat or Muqaiyar; (These were the names of pots in which Alcoholic drinks were prepared) (The Prophet (ﷺ) mentioned the container of wine and he meant the wine itself). The Prophet (ﷺ) further said (to them): "Memorize them (these instructions) and convey them to the people whom you have left behind', 'Sahih al-Bukhari 53'),
('bukhari:6550', 'Narrated Anas: Haritha was martyred on the day (of the battle) of Badr while he was young. His mother came to the Prophet (ﷺ) saying, "O Allah''s Messenger (ﷺ)! You know the relation of Haritha to me (how fond of him I was); so, if he is in Paradise, I will remain patient and wish for Allah''s reward, but if he is not there, then you will see what I will do." The Prophet (ﷺ) replied, "May Allah be merciful upon you! Have you gone mad? (Do you think) it is one Paradise? There are many Paradises and he is in the (most superior) Paradise of Al-Firdaus', 'Sahih al-Bukhari 6550'),
('bukhari:6548', 'Narrated Ibn `Umar:Allah''s Messenger (ﷺ) said, "When the people of Paradise have entered Paradise and the people of the Fire have entered the Fire, death will be brought and will be placed between the Fire and Paradise, and then it will be slaughtered, and a call will be made (that), ''O people of Paradise, no more death ! O people of the Fire, no more death ! '' So the people of Paradise will have happiness added to their previous happiness, and the people of the Fire will have sorrow added to their previous sorrow', 'Sahih al-Bukhari 6548'),
('bukhari:75', 'Narrated Ibn `Abbas:Once the Prophet (ﷺ) embraced me and said, "O Allah! Bestow on him the knowledge of the Book (Qur''an)', 'Sahih al-Bukhari 75'),
('bukhari:6536', 'Narrated Ibn Abi Mulaika:`Aisha said, "The Prophet (ﷺ) said, ''Anybody whose account (record) is questioned will surely be punished.'' I said, ''Doesn''t Allah say: ''He surely will receive an easy reckoning?'' (84.8) The Prophet (ﷺ) replied. ''This means only the presentation of the account."'' Narrated `Aisha: The Prophet (ﷺ) said (as above)', 'Sahih al-Bukhari 6536'),
('bukhari:6509', 'Narrated `Aisha:(the wife of the Prophet) When Allah''s Messenger (ﷺ) was in good health, he used to say, "No prophet''s soul is ever captured unless he is shown his place in Paradise and given the option (to die or survive)." So when the death of the Prophet (ﷺ) approached and his head was on my thigh, he became unconscious for a while and then he came to his senses and fixed his eyes on the ceiling and said, "O Allah (with) the highest companions." (See Qur''an 4:69). I said'' "Hence he is not going to choose us." And I came to know that it was the application of the narration which he (the Prophet) used to narrate to us. And that was the last statement of the Prophet (before his death) i.e., "O Allah! With the highest companions." (See Qur''an 4:)', 'Sahih al-Bukhari 6509'),
('bukhari:6469', 'Narrated Abu Huraira:I heard Allah''s Messenger (ﷺ) saying, Verily Allah created Mercy. The day He created it, He made it into one hundred parts. He withheld with Him ninety-nine parts, and sent its one part to all His creatures. Had the non-believer known of all the Mercy which is in the Hands of Allah, he would not lose hope of entering Paradise, and had the believer known of all the punishment which is present with Allah, he would not consider himself safe from the Hell-Fire', 'Sahih al-Bukhari 6469'),
('bukhari:6529', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "The first man to be called on the Day of Resurrection will be Adam who will be shown his offspring, and it will be said to them, ''This is your father, Adam.'' Adam will say (responding to the call), ''Labbaik and Sa`daik'' Then Allah will say (to Adam), ''Take out of your offspring, the people of Hell.'' Adam will say, ''O Lord, how many should I take out?'' Allah will say, ''Take out ninety-nine out of every hundred." They (the Prophet''s companions) said, "O Allah''s Apostle! If ninety-nine out of every one hundred of us are taken away, what will remain out of us?" He said, "My followers in comparison to the other nations are like a white hair on a black ox', 'Sahih al-Bukhari 6529'),
('bukhari:8', 'Narrated Ibn ''Umar: Allah''s Messenger (ﷺ) said: Islam is based on (the following) five (principles): 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah''s Messenger (ﷺ). 2. To offer the (compulsory congregational) prayers dutifully and perfectly. 3. To pay Zakat (i.e. obligatory charity) . 4. To perform Hajj. (i.e. Pilgrimage to Mecca) 5. To observe fast during the month of Ramadan', 'Sahih al-Bukhari 8'),
('nawawi:18', 'On the authority of Abu Dharr Jundub ibn Junadah, and Abu Abdur-Rahman Muadh bin Jabal (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: Have taqwa (fear) of Allah wherever you may be, and follow up a bad deed with a good deed which will wipe it out, and behave well towards the people. It was related by at-Tirmidhi, who said it was a hasan (good) hadeeth, and in some copies it is stated to be a hasan saheeh hadeeth', '40 Hadith Nawawi, Hadith 18'),
('bukhari:88', 'Narrated `Abdullah bin Abi Mulaika:`Uqba bin Al-Harith said that he had married the daughter of Abi Ihab bin `Aziz. Later on a woman came to him and said, "I have suckled (nursed) `Uqba and the woman whom he married (his wife) at my breast." `Uqba said to her, "Neither I knew that you have suckled (nursed) me nor did you tell me." Then he rode over to see Allah''s Messenger (ﷺ) at Medina, and asked him about it. Allah''s Messenger (ﷺ) said, "How can you keep her as a wife when it has been said (that she is your foster-sister)?" Then `Uqba divorced her, and she married another man', 'Sahih al-Bukhari 88'),
('bukhari:6507', 'Narrated ''Ubada bin As-Samit:The Prophet (ﷺ) said, "Who-ever loves to meet Allah, Allah (too) loves to meet him and who-ever hates to meet Allah, Allah (too) hates to meet him". `Aisha, or some of the wives of the Prophet (ﷺ) said, "But we dislike death." He said: It is not like this, but it is meant that when the time of the death of a believer approaches, he receives the good news of Allah''s pleasure with him and His blessings upon him, and so at that time nothing is dearer to him than what is in front of him. He therefore loves the meeting with Allah, and Allah (too) loves the meeting with him. But when the time of the death of a disbeliever approaches, he receives the evil news of Allah''s torment and His Requital, whereupon nothing is more hateful to him than what is before him. Therefore, he hates the meeting with Allah, and Allah too, hates the meeting with him', 'Sahih al-Bukhari 6507'),
('nawawi:26', 'On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Every joint of a person must perform a charity each day that the sun rises: to judge justly between two people is a charity. To help a man with his mount, lifting him onto it or hoisting up his belongings onto it, is a charity. And the good word is a charity. And every step that you take towards the prayer is a charity, and removing a harmful object from the road is a charity.” [Al-Bukhari] [Muslim]', '40 Hadith Nawawi, Hadith 26'),
('qudsi:39', 'On the authority of Abu Sa''id al-Khudri (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Paradise and Hell-fire disputed together, and Hell-fire said: In me are the mighty and the haughty. Paradise said: In me are the weak and the poor. So Allah judged between them, [saying]: You are Paradise, My mercy; through you I show mercy to those I wish. And you are Hell-fire, My punishment; through you I punish those I wish, and it is incumbent upon Me that each of you shall have its fill. It was related by Muslim (also by al-Bukhari and at-Tirmidhi)', '40 Hadith Qudsi, Hadith 39'),
('qudsi:4', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah said: Sons of Adam inveigh against [the vicissitudes of] Time, and I am Time, in My hand is the night and the day (1). (1) As the Almighty is the Ordainer of all things, to inveigh against misfortunes that are part of Time is tantamount to inveighing against Him. It was related by al-Bukhari (also by Muslim)', '40 Hadith Qudsi, Hadith 4'),
('nawawi:5', 'On the authority of the mother of the faithful, Aisha (ra), who said: The Messenger of Allah (ﷺ) said, “He who innovates something in this matter of ours (i.e., Islam) that is not of it will have it rejected (by Allah).” [Bukhari & Muslim] In another version in Muslim it reads: “He who does an act which we have not commanded, will have it rejected (by Allah).”', '40 Hadith Nawawi, Hadith 5'),
('bukhari:66', 'Narrated Abu Waqid Al-Laithi:While Allah''s Messenger (ﷺ) was sitting in the mosque with some people, three men came. Two of them came in front of Allah''s Messenger (ﷺ) and the third one went away. The two persons kept on standing before Allah''s Messenger (ﷺ) for a while and then one of them found a place in the circle and sat there while the other sat behind the gathering, and the third one went away. When Allah''s Messenger (ﷺ) finished his preaching, he said, "Shall I tell you about these three persons? One of them betook himself to Allah, so Allah took him into His grace and mercy and accommodated him, the second felt shy from Allah, so Allah sheltered Him in His mercy (and did not punish him), while the third turned his face from Allah and went away, so Allah turned His face from him likewise', 'Sahih al-Bukhari 66'),
('bukhari:13', 'Narrated Anas: The Prophet (ﷺ) said, "None of you will have faith till he wishes for his (Muslim) brother what he likes for himself', 'Sahih al-Bukhari 13'),
('bukhari:6413', 'Narrated Anas:The Prophet (ﷺ) said, "O Allah! There is no life worth living except the life of the Hereafter, so (please) make righteous the Ansar and the Emigrants', 'Sahih al-Bukhari 6413'),
('bukhari:6524', 'Narrated Ibn `Abbas:The Prophet (ﷺ) said, "You will meet Allah barefooted, naked, walking on feet, and uncircumcised', 'Sahih al-Bukhari 6524'),
('bukhari:6480', 'Narrated Hudhaifa:The Prophet (ﷺ) said, "There was a man amongst the people who had suspicion as to the righteousness of his deeds. Therefore he said to his family, ''If I die, take me and burn my corpse and throw my ashes into the sea on a hot (or windy) day.'' They did so, but Allah, collected his particles and asked (him), What made you do what you did?'' He replied, ''The only thing that made me do it, was that I was afraid of You.'' So Allah forgave him', 'Sahih al-Bukhari 6480'),
('bukhari:6482', 'Narrated Abu Musa:Allah''s Messenger (ﷺ) said. "My example and the example of the message with which Allah has sent me is like that of a man who came to some people and said, "I have seen with my own eyes the enemy forces, and I am a naked warner (to you) so save yourself, save yourself! A group of them obeyed him and went out at night, slowly and stealthily and were safe, while another group did not believe him and thus the army took them in the morning and destroyed them', 'Sahih al-Bukhari 6482'),
('bukhari:40', 'Narrated Al-Bara'' (bin ''Azib): When the Prophet (ﷺ) came to Medina, he stayed first with his grandfathers or maternal uncles from Ansar. He offered his prayers facing Baitul-Maqdis (Jerusalem) for sixteen or seventeen months, but he wished that he could pray facing the Ka''ba (at Mecca). The first prayer which he offered facing the Ka''ba was the ''Asr prayer in the company of some people. Then one of those who had offered that prayer with him came out and passed by some people in a mosque who were bowing during their prayers (facing Jerusalem). He said addressing them, "By Allah, I testify that I have prayed with Allah''s Messenger (ﷺ) facing Mecca (Ka''ba).'' Hearing that, those people changed their direction towards the Ka''ba immediately. Jews and the people of the scriptures used to be pleased to see the Prophet (ﷺ) facing Jerusalem in prayers but when he changed his direction towards the Ka''ba, during the prayers, they disapproved of it. Al-Bara'' added, "Before we changed our direction towards the Ka''ba (Mecca) in prayers, some Muslims had died or had been killed and we did not know what to say about them (regarding their prayers.) Allah then revealed: And Allah would never make your faith (prayers) to be lost (i.e. the prayers of those Muslims were valid).'' " (2:)', 'Sahih al-Bukhari 40'),
('qudsi:5', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (glorified and exalted be He) said: I am so self-sufficient that I am in no need of having an associate. Thus he who does an action for someone else''s sake as well as Mine will have that action renounced by Me to him whom he associated with Me. It was related by Muslim (also by Ibn Majah)', '40 Hadith Qudsi, Hadith 5'),
('qudsi:6', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said: I heard the Messenger of Allah (ﷺ) say: The first of people against whom judgment will be pronounced on the Day of Resurrection will be a man who died a martyr. He will be brought and Allah will make known to him His favours and he will recognize them. [ The Almighty] will say: And what did you do about them? He will say: I fought for you until I died a martyr. He will say: You have lied - you did but fight that it might be said [of you]: He is courageous. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. [Another] will be a man who has studied [religious] knowledge and has taught it and who used to recite the Quran. He will be brought and Allah will make known to him His favours and he will recognize them. [The Almighty] will say: And what did you do about them? He will say: I studied [religious] knowledge and I taught it and I recited the Quran for Your sake. He will say: You have lied - you did but study [religious] knowledge that it might be said [of you]: He is learned. And you recited the Quran that it might be said [of you]: He is a reciter. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. [Another] will be a man whom Allah had made rich and to whom He had given all kinds of wealth. He will be brought and Allah will make known to him His favours and he will recognize them. [The Almighty] will say: And what did you do about them? He will say: I left no path [untrodden] in which You like money to be spent without spending in it for Your sake. He will say: You have lied - you did but do so that it might be said [of you]: He is open-handed. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. It was related by Muslim (also by at-Tirmidhi and an-Nasa''i)', '40 Hadith Qudsi, Hadith 6'),
('bukhari:86', 'Narrated Asma'':I came to `Aisha while she was praying, and said to her, "What has happened to the people?" She pointed out towards the sky. (I looked towards the mosque), and saw the people offering the prayer. Aisha said, "Subhan Allah." I said to her, "Is there a sign?" She nodded with her head meaning, "Yes." I, too, then stood (for the prayer of eclipse) till I became (nearly) unconscious and later on I poured water on my head. After the prayer, the Prophet (ﷺ) praised and glorified Allah and then said, "Just now at this place I have seen what I have never seen before, including Paradise and Hell. No doubt it has been inspired to me that you will be put to trials in your graves and these trials will be like the trials of Masih-ad-Dajjal or nearly like it (the sub narrator is not sure which expression Asma'' used). You will be asked, ''What do you know about this man (the Prophet Muhammad (ﷺ))?'' Then the faithful believer (or Asma'' said a similar word) will reply, ''He is Muhammad Allah''s Messenger (ﷺ) who had come to us with clear evidences and guidance and so we accepted his teachings and followed him. And he is Muhammad.'' And he will repeat it thrice. Then the angels will say to him, ''Sleep in peace as we have come to know that you were a faithful believer.'' On the other hand, a hypocrite or a doubtful person will reply, ''I do not know, but I heard the people saying something and so I said it.'' (the same)', 'Sahih al-Bukhari 86'),
('bukhari:64', 'Narrated `Abdullah bin `Abbas:Once Allah''s Messenger (ﷺ) gave a letter to a person and ordered him to go and deliver it to the Governor of Bahrain. (He did so) and the Governor of Bahrain sent it to Chousroes, who read that letter and then tore it to pieces. (The sub-narrator (Ibn Shihab) thinks that Ibn Al-Musaiyab said that Allah''s Messenger (ﷺ) invoked Allah against them (saying), "May Allah tear them into pieces, and disperse them all totally', 'Sahih al-Bukhari 64'),
('bukhari:32', 'Narrated ''Abdullah: When the following Verse was revealed: "It is those who believe and confuse not their belief with wrong (worshipping others besides Allah.)" (6:83), the companions of Allah''s Messenger (ﷺ) asked, "Who is amongst us who had not done injustice (wrong)?" Allah revealed: "No doubt, joining others in worship with Allah is a great injustice (wrong) indeed', 'Sahih al-Bukhari 32'),
('bukhari:54', 'Narrated ''Umar bin Al-Khattab: Allah''s Messenger (ﷺ) said, "The reward of deeds depends upon the intention and every person will get the reward according to what he has intended. So whoever emigrated for Allah and His Apostle, then his emigration was for Allah and His Apostle. And whoever emigrated for worldly benefits or for a woman to marry, his emigration was for what he emigrated for', 'Sahih al-Bukhari 54'),
('bukhari:6537', 'Narrated `Aisha:Allah''s Messenger (ﷺ), said, "None will be called to account on the Day of Resurrection, but will be ruined." I said "O Allah''s Messenger (ﷺ)! Hasn''t Allah said: ''Then as for him who will be given his record in his right hand, he surely will receive an easy reckoning? (84.7-8) -- Allah''s Messenger (ﷺ) said, "That (Verse) means only the presentation of the accounts, but anybody whose account (record) is questioned on the Day of Resurrection, will surely be punished', 'Sahih al-Bukhari 6537'),
('bukhari:6545', 'Narrated Abu Huraira:The Prophet (ﷺ) said, " It will be said to the people of Paradise, ''O people of Paradise! Eternity (for you) and no death,'' and to the people of the Fire, ''O people of the Fire, eternity (for you) and no death', 'Sahih al-Bukhari 6545'),
('bukhari:78', 'Narrated Ibn `Abbas:that he differed with Hur bin Qais bin Hisn Al-Fazari regarding the companion of the Prophet Moses (ﷺ). Meanwhile, Ubai bin Ka`b passed by them and Ibn `Abbas called him saying, "My friend (Hur) and I have differed regarding Moses'' companion whom Moses asked the way to meet. Have you heard Allah''s Messenger (ﷺ) mentioning something about him?" Ubai bin Ka`b said: "Yes, I heard the Prophet (ﷺ) mentioning something about him (saying) while Moses was sitting in the company of some Israelites, a man came and asked him: "Do you know anyone who is more learned than you?" Moses replied: "No." So Allah sent the Divine Inspiration to Moses: ''--Yes, Our slave Khadir is more learned than you.'' Moses asked Allah how to meet him (Al-Khadir). So Allah made the fish a sign for him and he was told when the fish was lost, he should return (to the place where he had lost it) and there he would meet him (Al-Khadir). So Moses went on looking for the sign of the fish in the sea. The servant-boy of Moses said: ''Do you remember when we betook ourselves to the rock, I indeed forgot the fish, none but Satan made me forget to remember it. On that Moses said, ''That is what we have been seeking.'' So they went back retracing their footsteps, and found Khadir. (and) what happened further about them is narrated in the Holy Qur''an by Allah." (18.54 up to)', 'Sahih al-Bukhari 78'),
('qudsi:27', 'On the authority of Masruq, who said: We asked Abdullah (i.e. Ibn Masud) about this verse: And do not regard those who have been killed in the cause of Allah as dead, rather are they alive with their Lord, being provided for (Quran 3:169). He said: We asked about that and the Prophet (ﷺ) said: Their souls are in the insides of green birds having lanterns suspended from the Throne, roaming freely in Paradise where they please, then taking shelter in those lanterns. So their Lord cast a glance at them (1) and said: Do you wish for anything? They said: What shall we wish for when we roam freely in Paradise where we please? And thus did He do to them three times. When they say that they would not be spared from being asked [again], they said: O Lord, we would like for You to put back our souls into our bodies so that we might fight for Your sake once again. And when He saw that they were not in need of anything they were let be. (1) i.e. at those who had been killed in the cause of Allah. It was related by Muslim (also by at-Tirmidhi, an-Nasa''i and Ibn Majah)', '40 Hadith Qudsi, Hadith 27'),
('nawawi:23', 'On the authority of Abu Malik al-Harith bin Asim al-Asharee (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Purity is half of iman (faith). ‘Al-hamdu lillah (praise be to Allah)’ fills the scales, and ‘subhan-Allah (how far is Allah from every imperfection) and ‘Al-hamdulillah (praise be to Allah)’ fill that which is between heaven and earth. And the salah (prayer) is a light, and charity is a proof, and patience is illumination, and the Qur’an is a proof either for you or against you. Every person starts his day as a vendor of his soul, either freeing it or causing its ruin.” [Muslim]', '40 Hadith Nawawi, Hadith 23'),
('bukhari:6489', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "The truest poetic verse ever said by a poet, is: Indeed! Everything except Allah, is perishable', 'Sahih al-Bukhari 6489'),
('bukhari:6504', 'Narrated Anas:Allah''s Messenger (ﷺ) said, "I have been sent and the Hour (is at hand) as these two (fingers)', 'Sahih al-Bukhari 6504'),
('bukhari:6419', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "Allah will not accept the excuse of any person whose instant of death is delayed till he is sixty years of age', 'Sahih al-Bukhari 6419'),
('bukhari:6560', 'Narrated Abu Sa`id Al-Khudri:Allah''s Messenger (ﷺ) said, "When the people of Paradise have entered Paradise, and the people of the Fire have entered the Fire, Allah will say. ''Take out (of the Fire) whoever has got faith equal to a mustard seed in his heart.'' They will come out, and by that time they would have burnt and became like coal, and then they will be thrown into the river of Al-Hayyat (life) and they will spring up just as a seed grows on the bank of a rainwater stream." The Prophet (ﷺ) said, "Don''t you see that the germinating seed comes out yellow and twisted?', 'Sahih al-Bukhari 6560'),
('bukhari:134', 'Narrated Ibn `Umar:A man asked the Prophet (ﷺ) : "What (kinds of clothes) should a Muhrim (a Muslim intending to perform `Umra or Hajj) wear? He replied, "He should not wear a shirt, a turban, trousers, a head cloak or garment scented with saffron or Wars (kinds of perfumes). And if he has no slippers, then he can use Khuffs (socks made from thick fabric or leather) but the socks should be cut short so as to make the ankles bare." (See Hadith No. 615, Vol)', 'Sahih al-Bukhari 134'),
('qudsi:33', 'On the authority of Abu Hurayrah (may Allah be pleased with him) that the Prophet (ﷺ), from among the things he reports from his Lord (mighty and sublime be He), is that he said: A servant [of Allah''s] committed a sin and said: O Allah, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for them. Then he sinned again and said: O Lord, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for them. Then he sinned again and said: O Lord, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for sins. Do what you wish, for I have forgiven you. It was related by Muslim (also by al-Bukhari)', '40 Hadith Qudsi, Hadith 33'),
('nawawi:34', 'On the authority of Abu Sa`eed al-Khudree (may Allah be pleased with him) who said: I heard the Messenger of Allah (ﷺ) say, “Whosoever of you sees an evil, let him change it with his hand; and if he is not able to do so, then [let him change it] with his tongue; and if he is not able to do so, then with his heart — and that is the weakest of faith.” [Muslim]', '40 Hadith Nawawi, Hadith 34'),
('bukhari:81', 'Narrated Anas:I will narrate to you a Hadith and none other than I will tell you about after it. I heard Allah''s Messenger (ﷺ) saying: From among the portents of the Hour are (the following): -1. Religious knowledge will decrease (by the death of religious learned men). -2. Religious ignorance will prevail. -3. There will be prevalence of open illegal sexual intercourse. -4. Women will increase in number and men will decrease in number so much so that fifty women will be looked after by one man', 'Sahih al-Bukhari 81'),
('bukhari:6519', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "Allah will take the whole earth (in His Hand) and will roll up the Heaven in His right Hand, and then He will say, "I am King! Where are the kings of the earth ?', 'Sahih al-Bukhari 6519'),
('bukhari:6487', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "The (Hell) Fire is surrounded by all kinds of desires and passions, while Paradise is surrounded by all kinds of disliked undesirable things', 'Sahih al-Bukhari 6487'),
('bukhari:6540', 'Narrated `Adi bin Hatim:The Prophet (ﷺ) said, "Protect yourself from the Fire." He then turned his face aside (as if he were looking at it) and said again, "Protect yourself from the Fire," and then turned his face aside (as if he were looking at it), and he said so for the third time till we thought he was looking at it. He then said, "Protect yourselves from the Fire, even if with one half of a date and he who hasn''t got even this, (should do so) by (saying) a good, pleasant word', 'Sahih al-Bukhari 6540'),
('bukhari:6579', 'Narrated `Abdullah bin `Amr:The Prophet (ﷺ) said, "My Lake-Fount is (so large that it takes) a month''s journey to cross it. Its water is whiter than milk, and its smell is nicer than musk (a kind of Perfume), and its drinking cups are (as numerous) as the (number of) stars of the sky; and whoever drinks from it, will never be thirsty', 'Sahih al-Bukhari 6579'),
('bukhari:6583', 'Narrated Abu Hazim from Sahl bin Sa`d:The Prophet (ﷺ) said, "I am your predecessor (forerunner) at the Lake-Fount, and whoever will pass by there, he will drink from it and whoever will drink from it, he will never be thirsty. There will come to me some people whom I will recognize, and they will recognize me, but a barrier will be placed between me and them', 'Sahih al-Bukhari 6583'),
('bukhari:6576', 'Abdullah added:The Prophet (ﷺ) said, "I am your predecessor at the Lake-Fount, and some of you will be brought in front of me till I will see them and then they will be taken away from me and I will say, ''O Lord, my companions!'' It will be said, ''You do not know what they did after you had left', 'Sahih al-Bukhari 6576'),
('bukhari:116', 'Narrated `Abdullah bin `Umar:Once the Prophet (ﷺ) led us in the `Isha'' prayer during the last days of his life and after finishing it (the prayer) (with Taslim) he said: "Do you realize (the importance of) this night?" Nobody present on the surface of the earth tonight will be living after the completion of one hundred years from this night', 'Sahih al-Bukhari 116'),
('bukhari:41', 'Narrated Abu Sa''id Al Khudri:Allah''s Messenger (ﷺ) said, "If a person embraces Islam sincerely, then Allah shall forgive all his past sins, and after that starts the settlement of accounts, the reward of his good deeds will be ten times to seven hundred times for each good deed and one evil deed will be recorded as it is unless Allah forgives it', 'Sahih al-Bukhari 41'),
('bukhari:6422', 'Narrated Mahmud bin Ar-Rabi''a:I remember that the Allah''s Messenger (ﷺ) took water from a bucket (which was in our home used for getting water out of well) with his mouth (and threw it on my face)', 'Sahih al-Bukhari 6422'),
('bukhari:6490', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "If anyone of you looked at a person who was made superior to him in property and (in good) appearance, then he should also look at the one who is inferior to him', 'Sahih al-Bukhari 6490'),
('bukhari:6446', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "Wealth is not in having many possessions, but rather (true) wealth is feeling sufficiency in the soul', 'Sahih al-Bukhari 6446'),
('qudsi:25', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: Whosoever shows enmity to someone devoted to Me, I shall be at war with him. My servant draws not near to Me with anything more loved by Me than the religious duties I have enjoined upon him, and My servant continues to draw near to Me with supererogatory works so that I shall love him. When I love him I am his hearing with which he hears, his seeing with which he sees, his hand with which he strikes and his foot with which he walks. Were he to ask [something] of Me, I would surely give it to him, and were he to ask Me for refuge, I would surely grant him it. I do not hesitate about anything as much as I hesitate about [seizing] the soul of My faithful servant: he hates death and I hate hurting him. It was related by al-Bukhari', '40 Hadith Qudsi, Hadith 25'),
('bukhari:125', 'Narrated `Abdullah:While I was going with the Prophet (ﷺ) through the ruins of Medina and he was reclining on a date-palm leaf stalk, some Jews passed by. Some of them said to the others: Ask him (the Prophet) about the spirit. Some of them said that they should not ask him that question as he might give a reply which would displease them. But some of them insisted on asking, and so one of them stood up and asked, "O Abul-Qasim ! What is the spirit?" The Prophet (ﷺ) remained quiet. I thought he was being inspired Divinely. So I stayed till that state of the Prophet (while being inspired) was over. The Prophet (ﷺ) then said, "And they ask you (O Muhammad) concerning the spirit --Say: The spirit -- its knowledge is with my Lord. And of knowledge you (mankind) have been given only a little', 'Sahih al-Bukhari 125'),
('bukhari:36', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "The person who participates in (Holy battles) in Allah''s cause and nothing compels him to do so except belief in Allah and His Apostles, will be recompensed by Allah either with a reward, or booty (if he survives) or will be admitted to Paradise (if he is killed in the battle as a martyr). Had I not found it difficult for my followers, then I would not remain behind any sariya going for Jihad and I would have loved to be martyred in Allah''s cause and then made alive, and then martyred and then made alive, and then again martyred in His cause', 'Sahih al-Bukhari 36'),
('bukhari:6451', 'Narrated `Aisha:When the Prophet (ﷺ) died, nothing which can be eaten by a living creature was left on my shelf except some barley grain. I ate of it for a period and when I measured it, it finished', 'Sahih al-Bukhari 6451'),
('qudsi:11', 'On the authority of Abu Harayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (mighty and sublime be He) said: Spend (on charity), O son of Adam, and I shall spend on you. It was related by al-Bukhari (also by Muslim)', '40 Hadith Qudsi, Hadith 11'),
('bukhari:6571', 'Narrated `Abdullah:The Prophet (ﷺ) said, "I know the person who will be the last to come out of the (Hell) Fire, and the last to enter Paradise. He will be a man who will come out of the (Hell) Fire crawling, and Allah will say to him, ''Go and enter Paradise.'' He will go to it, but he will imagine that it had been filled, and then he will return and say, ''O Lord, I have found it full.'' Allah will say, ''Go and enter Paradise, and you will have what equals the world and ten times as much (or, you will have as much as ten times the like of the world).'' On that, the man will say, ''Do you mock at me (or laugh at me) though You are the King?" I saw Allah''s Messenger (ﷺ) (while saying that) smiling that his premolar teeth became visible. It is said that will be the lowest in degree amongst the people of Paradise', 'Sahih al-Bukhari 6571'),
('bukhari:6423', 'Narrated `Utban bin Malik Al-Ansari:who was one of the men of the tribe of Bani Salim: Allah''s Messenger (ﷺ) came to me and said, "If anybody comes on the Day of Resurrection who has said: La ilaha illal-lah, sincerely, with the intention to win Allah''s Pleasure, Allah will make the Hell-Fire forbidden for him', 'Sahih al-Bukhari 6423'),
('nawawi:13', 'On the authority of Abu Hamzah Anas bin Malik (may Allah be pleased with him) — the servant of the Messenger of Allah (peace and blessings of Allah be upon him) — that the Prophet (peace and blessings of Allah be upon him) said: None of you [truly] believes until he loves for his brother that which he loves for himself. [Al-Bukhari] [Muslim]', '40 Hadith Nawawi, Hadith 13'),
('bukhari:6521', 'Narrated Sahl bin Sa`d:I heard the Prophet (ﷺ) saying, "The people will be gathered on the Day of Resurrection on reddish white land like a pure loaf of bread (made of pure fine flour)." Sahl added: That land will have no landmarks for anybody (to make use of)', 'Sahih al-Bukhari 6521'),
('nawawi:24', 'On the authority of Abu Dharr al-Ghifaree (may Allah be pleased with him) from the Prophet (peace and blessings of Allah be upon him) from his Lord, that He said: O My servants! I have forbidden dhulm (oppression) for Myself, and I have made it forbidden amongst you, so do not oppress one another. O My servants, all of you are astray except those whom I have guided, so seek guidance from Me and I shall guide you. O My servants, all of you are hungry except those whom I have fed, so seek food from Me and I shall feed you. O My servants, all of you are naked except those whom I have clothed, so seek clothing from Me and I shall clothe you. O My servants, you commit sins by day and by night, and I forgive all sins, so seek forgiveness from Me and I shall forgive you. O My servants, you will not attain harming Me so as to harm Me, and you will not attain benefiting Me so as to benefit Me. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all as pious as the most pious heart of any individual amongst you, then this would not increase My Kingdom an iota. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all as wicked as the most wicked heart of any individual amongst you, then this would not decrease My Kingdom an iota. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all to stand together in one place and ask of Me, and I were to give everyone what he requested, then that would not decrease what I Possess, except what is decreased of the ocean when a needle is dipped into it. O My servants, it is but your deeds that I account for you, and then recompense you for. So he who finds good, let him praise Allah, and he who finds other than that, let him blame no one but himself. [Muslim]', '40 Hadith Nawawi, Hadith 24'),
('qudsi:35', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Our Lord (glorified and exalted be He) descends each night to the earth''s sky when there remains the final third of the night, and He says: Who is saying a prayer to Me that I may answer it? Who is asking something of Me that I may give it him? Who is asking forgiveness of Me that I may forgive him? It was related by al-Bukhari (also by Muslim, Malik, at-Tirmidhi and Abu Dawud). In a version by Muslim the Hadith ends with the words: And thus He continues till [the light of] dawn shines', '40 Hadith Qudsi, Hadith 35'),
('bukhari:6558', 'Narrated Hammad from `Amr from Jabir:The Prophet (ﷺ) said, "Some people will come out of the Fire through intercession looking like The Thaarir." I asked `Amr, "What is the Thaarir?" He said, Ad Dagh`Abis, and at that time he was toothless. Hammad added: I said to `Amr bin Dinar, "O Abu Muhammad! Did you hear Jabir bin `Abdullah saying, ''I heard the Prophet (ﷺ) saying: ''Some people will come out of the Fire through intercession?" He said, "Yes', 'Sahih al-Bukhari 6558'),
('bukhari:95', 'Narrated Anas:Whenever the Prophet (ﷺ) spoke a sentence (said a thing), he used to repeat it thrice so that the people could understand it properly from him and whenever he asked permission to enter, (he knocked the door) thrice with greeting', 'Sahih al-Bukhari 95'),
('bukhari:44', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever said "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of a barley grain will be taken out of Hell. And whoever said: "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of a wheat grain will be taken out of Hell. And whoever said, "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of an atom will be taken out of Hell', 'Sahih al-Bukhari 44'),
('bukhari:6421', 'Narrated Anas bin Malik:Allah''s Messenger (ﷺ) said, "The son of Adam (i.e. man) grows old and so also two (desires) grow old with him, i.e., love for wealth and (a wish for) a long life', 'Sahih al-Bukhari 6421'),
('bukhari:115', 'Narrated Um Salama:One night Allah''s Messenger (ﷺ) got up and said, "Subhan Allah! How many afflictions have been descended tonight and how many treasures have been disclosed! Go and wake the sleeping lady occupants of these dwellings (his wives) up (for prayers). A well-dressed (soul) in this world may be naked in the Hereafter', 'Sahih al-Bukhari 115'),
('bukhari:6466', 'Narrated ''Alqama:I asked `Aisha, mother of the believers, "O mother of the believers! How were the deeds of the Prophet? Did he use to do extra deeds of worship on special days?" She said, "No, but his deeds were regular and constant, and who among you is able to do what the Prophet (ﷺ) was able to do (i.e. in worshipping Allah)?', 'Sahih al-Bukhari 6466'),
('bukhari:6474', 'Narrated Sahl bin Sa`d:Allah''s Messenger (ﷺ) said, "Whoever can guarantee (the chastity of) what is between his two jaw-bones and what is between his two legs (i.e. his tongue and his private parts), I guarantee Paradise for him', 'Sahih al-Bukhari 6474'),
('bukhari:91', 'Narrated Zaid bin Khalid Al-Juhani:A man asked the Prophet (ﷺ) about the picking up of a "Luqata" (fallen lost thing). The Prophet (ﷺ) replied, "Recognize and remember its tying material and its container, and make public announcement (about it) for one year, then utilize it but give it to its owner if he comes." Then the person asked about the lost camel. On that, the Prophet (ﷺ) got angry and his cheeks or his Face became red and he said, "You have no concern with it as it has its water container, and its feet and it will reach water, and eat (the leaves) of trees till its owner finds it." The man then asked about the lost sheep. The Prophet (ﷺ) replied, "It is either for you, for your brother (another person) or for the wolf', 'Sahih al-Bukhari 91'),
('bukhari:6471', 'Narrated Al-Mughira bin Shu`ba:The Prophet (ﷺ) used to pray so much that his feet used to become edematous or swollen, and when he was asked as to why he prays so much, he would say, "Shall I not be a thankful slave (to Allah)?', 'Sahih al-Bukhari 6471'),
('bukhari:6517', 'Narrated Abu Huraira:Two men, a Muslim and a Jew, abused each other. The Muslim said, "By Him Who gave superiority to Muhammad over all the people." On that, the Jew said, "By Him Who gave superiority to Moses over all the people." The Muslim became furious at that and slapped the Jew in the face. The Jew went to Allah''s Messenger (ﷺ) and informed him of what had happened between him and the Muslim. Allah''s Apostle said, "Don''t give me superiority over Moses, for the people will fall unconscious on the Day of Resurrection and I will be the first to gain consciousness, and behold ! Moses will be there holding the side of Allah''s Throne. I will not know whether Moses has been among those people who have become unconscious and then has regained consciousness before me, or has been among those exempted by Allah from falling unconscious', 'Sahih al-Bukhari 6517'),
('qudsi:3', 'On the authority of Zayd ibn Khalid al-Juhaniyy (may Allah be pleased with him), who said: The Messenger of Allah (ﷺ) led the morning prayer for us at al-Hudaybiyah following rainfall during the night. When the Prophet (ﷺ) finished, he faced the people and said to them: Do you know what your Lord has said? They said: Allah and his Messenger know best. He said: This morning one of my servants became a believer in Me and one a disbeliever. As for him who said: We have been given rain by virtue of Allah and His mercy, that one is a believer in Me, a disbeliever in the stars (2); and as for him who said: We have been given rain by such-and-such a star, that one is a disbeliever in Me, a believer in the stars. (2) The pre-Islamic Arabs believed that rain was brought about by the movement of stars. This Hadith draws attention to the fact that whatever be the direct cause of such natural phenomena as rain, it is Allah the Almighty who is the Disposer of all things. It was related by al-Bukhari (also by Malik and an-Nasa''i)', '40 Hadith Qudsi, Hadith 3'),
('qudsi:37', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah said: I have prepared for My righteous servants what no eye has seen and no ear has heard, not has it occurred to human heart. Thus recite if you wish (1): And no soul knows what joy for them (the inhabitants of Paradise) has been kept hidden (Quran 32:17). (1) The words "Thus recite if you wish" are those of Abu Harayrah. It was related by al-Bukhari, Muslim, at-Tirmidhi and Ibn Majah', '40 Hadith Qudsi, Hadith 37'),
('bukhari:59', 'Narrated Abu Huraira:While the Prophet (ﷺ) was saying something in a gathering, a Bedouin came and asked him, "When would the Hour (Doomsday) take place?" Allah''s Messenger (ﷺ) continued his talk, so some people said that Allah''s Messenger (ﷺ) had heard the question, but did not like what that Bedouin had asked. Some of them said that Allah''s Messenger (ﷺ) had not heard it. When the Prophet (ﷺ) finished his speech, he said, "Where is the questioner, who inquired about the Hour (Doomsday)?" The Bedouin said, "I am here, O Allah''s Apostle ." Then the Prophet (ﷺ) said, "When honesty is lost, then wait for the Hour (Doomsday)." The Bedouin said, "How will that be lost?" The Prophet (ﷺ) said, "When the power or authority comes in the hands of unfit persons, then wait for the Hour (Doomsday)', 'Sahih al-Bukhari 59'),
('qudsi:21', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said that Allah the Almighty said: There are three (1) whose adversary I shall be on the Day of Resurrection: a man who has given his word by Me and has broken it; a man who has sold a free man (2) and has consumed the price; and a man who has hired a workman, has exacted his due in full from him and has not given him his wage. (1) i.e. types of men. (2) i.e. a man who has made a slave of another and has sold him. It was related by al-Bukhari (also by Ibn Majah and Ahmad ibn Hanbal)', '40 Hadith Qudsi, Hadith 21'),
('nawawi:28', 'On the authority of Abu Najeeh al-’Irbaad ibn Saariyah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) gave us a sermon by which our hearts were filled with fear and tears came to our eyes. So we said, “O Messenger of Allah! It is as though this is a farewell sermon, so counsel us.” He (peace and blessings of Allah be upon him) said, “I counsel you to have taqwa (fear) of Allah, and to listen and obey [your leader], even if a slave were to become your ameer. Verily he among you who lives long will see great controversy, so you must keep to my Sunnah and to the Sunnah of the Khulafa ar-Rashideen (the rightly guided caliphs), those who guide to the right way. Cling to it stubbornly [literally: with your molar teeth]. Beware of newly invented matters [in the religion], for verily every bidah (innovation) is misguidance.” [Abu Dawud] It was related by at-Tirmidhi, who said that it was a good and sound hadeeth', '40 Hadith Nawawi, Hadith 28'),
('bukhari:6433', 'Narrated Ibn `Abbas:I brought water to `Uthman bin `Affan to perform the ablution while he was sitting on his seat. He performed the ablution in a perfect way and said, "I saw the Prophet (ﷺ) performing the ablution in this place and he performed it in a perfect way and said, "Whoever performs the ablution as I have done this time and then proceeds to the mosque and offers a two-rak`at prayer and then sits there (waiting for the compulsory congregational prayers), then all his past sins will be forgiven." The Prophet (ﷺ) further added, "Do not be conceited (thinking that your sins will be forgiven because of your prayer)', 'Sahih al-Bukhari 6433'),
('bukhari:124', 'Narrated `Abdullah bin `Ammar:I saw the Prophet (ﷺ) near the Jamra and the people were asking him questions (about religious problems). A man asked, "O Allah''s Messenger (ﷺ)! I have slaughtered the Hadi (animal) before doing the Rami." The Prophet (ﷺ) replied, "Do the Rami (now) and there is no harm." Another person asked, "O Allah''s Messenger (ﷺ)! I got my head shaved before slaughtering the animal." The Prophet (ﷺ) replied, "Do the slaughtering (now) and there is no harm." So on that day, when the Prophet (ﷺ) was asked about anything as regards the ceremonies of Hajj performed before or after its due time his reply was, "Do it (now) and there is no harm', 'Sahih al-Bukhari 124'),
('bukhari:31', 'Narrated Al-Ahnaf bin Qais: While I was going to help this man (''Ali Ibn Abi Talib), Abu Bakra met me and asked, "Where are you going?" I replied, "I am going to help that person." He said, "Go back for I have heard Allah''s Messenger (ﷺ) saying, ''When two Muslims fight (meet) each other with their swords, both the murderer as well as the murdered will go to the Hell-fire.'' I said, ''O Allah''s Messenger (ﷺ)! It is all right for the murderer but what about the murdered one?'' Allah''s Messenger (ﷺ) replied, "He surely had the intention to kill his companion', 'Sahih al-Bukhari 31'),
('bukhari:43', 'Narrated ''Aisha: Once the Prophet (ﷺ) came while a woman was sitting with me. He said, "Who is she?" I replied, "She is so and so," and told him about her (excessive) praying. He said disapprovingly, "Do (good) deeds which is within your capacity (without being overtaxed) as Allah does not get tired (of giving rewards) but (surely) you will get tired and the best deed (act of Worship) in the sight of Allah is that which is done regularly', 'Sahih al-Bukhari 43'),
('bukhari:106', 'Narrated `Ali:The Prophet (ﷺ) said, "Do not tell a lie against me for whoever tells a lie against me (intentionally) then he will surely enter the Hell-fire', 'Sahih al-Bukhari 106'),
('bukhari:6581', 'Narrated Anas bin Malik:The Prophet (ﷺ) said: "While I was walking in Paradise (on the night of Mi''raj), I saw a river, on the two banks of which there were tents made of hollow pearls. I asked, "What is this, O Gabriel?'' He said, ''That is the Kauthar which Your Lord has given to you.'' Behold! Its scent or its mud was sharp smelling musk!" (The sub-narrator, Hudba is in doubt as to the correct expression)', 'Sahih al-Bukhari 6581'),
('bukhari:6470', 'Narrated Abu Sa`id:Some people from the Ansar asked Allah''s Messenger (ﷺ) (to give them something) and he gave to everyone of them, who asked him, until all that he had was finished. When everything was finished and he had spent all that was in his hand, he said to them, ''"(Know) that if I have any wealth, I will not withhold it from you (to keep for somebody else); And (know) that he who refrains from begging others (or doing prohibited deeds), Allah will make him contented and not in need of others; and he who remains patient, Allah will bestow patience upon him, and he who is satisfied with what he has, Allah will make him self-sufficient. And there is no gift better and vast (you may be given) than patience', 'Sahih al-Bukhari 6470'),
('nawawi:9', 'On the authority of Abu Hurayrah (ra): I heard the Messenger of Allah (ﷺ) say, “What I have forbidden for you, avoid. What I have ordered you [to do], do as much of it as you can. For verily, it was only the excessive questioning and their disagreeing with their Prophets that destroyed [the nations] who were before you.” [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 9'),
('nawawi:14', 'On the authority of Ibn Masood (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “It is not permissible to spill the blood of a Muslim except in three [instances]: the married person who commits adultery, a life for a life, and the one who forsakes his religion and separates from the community.” [Al-Bukhari] [Muslim]', '40 Hadith Nawawi, Hadith 14'),
('bukhari:6435', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "Perish the slave of Dinar, Dirham, Qatifa (thick soft cloth), and Khamisa (a garment), for if he is given, he is pleased; otherwise he is dissatisfied', 'Sahih al-Bukhari 6435'),
('bukhari:6568', 'Narrated Anas:Um (the mother of) Haritha came to Allah''s Messenger (ﷺ) after Haritha had been martyred on the Day (of the battle) of Badr by an arrow thrown by an unknown person. She said, "O Allah''s Messenger (ﷺ)! You know the position of Haritha in my heart (i.e. how dear to me he was), so if he is in Paradise, I will not weep for him, or otherwise, you will see what I will do." The Prophet (ﷺ) said, "Are you mad? Is there only one Paradise? There are many Paradises, and he is in the highest Paradise of Firdaus." The Prophet added, "A forenoon journey or an after noon journey in Allah''s Cause is better than the whole world and whatever is in it; and a place equal to an arrow bow of anyone of you, or a place equal to a foot in Paradise is better than the whole world and whatever is in it; and if one of the women of Paradise looked at the earth, she would fill the whole space between them (the earth and the heaven) with light, and would fill whatever is in between them, with perfume, and the veil of her face is better than the whole world and whatever is in it', 'Sahih al-Bukhari 6568'),
('bukhari:48', 'Narrated ''Abdullah: The Prophet (ﷺ) said, "Abusing a Muslim is Fusuq (an evil doing) and killing him is Kufr (disbelief)', 'Sahih al-Bukhari 48'),
('bukhari:6478', 'Narrated Abu Huraira:The Prophet; said, "A slave (of Allah) may utter a word which pleases Allah without giving it much importance, and because of that Allah will raise him to degrees (of reward): a slave (of Allah) may utter a word (carelessly) which displeases Allah without thinking of its gravity and because of that he will be thrown into the Hell-Fire', 'Sahih al-Bukhari 6478'),
('bukhari:71', 'Narrated Muawiya:I heard Allah''s Messenger (ﷺ) saying, "If Allah wants to do good to a person, He makes him comprehend the religion. I am just a distributor, but the grant is from Allah. (And remember) that this nation (true Muslims) will keep on following Allah''s teachings strictly and they will not be harmed by any one going on a different path till Allah''s order (Day of Judgment) is established', 'Sahih al-Bukhari 71'),
('bukhari:6559', 'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Some people will come out of the Fire after they have received a touch of the Fire, changing their color, and they will enter Paradise, and the people of Paradise will name them ''Al- Jahannamiyin'' the (Hell) Fire people', 'Sahih al-Bukhari 6559'),
('bukhari:6520', 'Narrated Abu Sa`id Al-Khudri:The Prophet (ﷺ) said, "The (planet of) earth will be a bread on the Day of Resurrection, and The resistible (Allah) will topple turn it with His Hand like anyone of you topple turns a bread with his hands while (preparing the bread) for a journey, and that bread will be the entertainment for the people of Paradise." A man from the Jews came (to the Prophet) and said, "May The Beneficent (Allah) bless you, O Abul Qasim! Shall I tell you of the entertainment of the people of Paradise on the Day of Resurrection?" The Prophet (ﷺ) said, "Yes." The Jew said, "The earth will be a bread," as the Prophet (ﷺ) had said. Thereupon the Prophet (ﷺ) looked at us and smiled till his premolar tooth became visible. Then the Jew further said, "Shall I tell you of the udm (additional food taken with bread) they will have with the bread?" He added, "That will be Balam and Nun." The people asked, "What is that?" He said, "It is an ox and a fish, and seventy thousand people will eat of the caudate lobe (i.e. extra lobe) of their livers', 'Sahih al-Bukhari 6520'),
('bukhari:30', 'Narrated Al-Ma''rur: At Ar-Rabadha I met Abu Dhar who was wearing a cloak, and his slave, too, was wearing a similar one. I asked about the reason for it. He replied, "I abused a person by calling his mother with bad names." The Prophet said to me, ''O Abu Dhar! Did you abuse him by calling his mother with bad names You still have some characteristics of ignorance. Your slaves are your brothers and Allah has put them under your command. So whoever has a brother under his command should feed him of what he eats and dress him of what he wears. Do not ask them (slaves) to do things beyond their capacity (power) and if you do so, then help them', 'Sahih al-Bukhari 30'),
('bukhari:6420', 'Narrated Abu Huraira:I heard Allah''s Messenger (ﷺ) saying, "The heart of an old man remains young in two respects, i.e., his love for the world (its wealth, amusements and luxuries) and his incessant hope', 'Sahih al-Bukhari 6420'),
('nawawi:2', 'Also on the authority of `Umar (ra) who said: While we were one day sitting with the Messenger of Allah (ﷺ) there appeared before us a man dressed in extremely white clothes and with very black hair. No traces of journeying were visible on him, and none of us knew him. He sat down close by the Prophet (ﷺ) rested his knees against the knees of the Prophet (ﷺ) and placed his palms over his thighs, and said: "O Muhammad! Inform me about Islam." The Messenger of Allah (ﷺ) replied: "Islam is that you should testify that there is no deity worthy of worship except Allah and that Muhammad is His Messenger (ﷺ), that you should perform salah (ritual prayer), pay the zakah, fast during Ramadan, and perform Hajj (pilgrimage) to the House (the Ka`bah at Makkah), if you can find a way to it (or find the means for making the journey to it)." He said: "You have spoken the truth." We were astonished at his thus questioning him (ﷺ) and then telling him that he was right, but he went on to say, "Inform me about Iman (faith)." He (the Prophet) answered, "It is that you believe in Allah and His angels and His Books and His Messengers and in the Last Day, and in fate (qadar), both in its good and in its evil aspects." He said, "You have spoken the truth." Then he (the man) said, "Inform me about Ihsan." He (the Prophet) answered, "It is that you should serve Allah as though you could see Him, for though you cannot see Him yet He sees you." He said, "Inform me about the Hour." He (the Prophet) said, "About that the one questioned knows no more than the questioner." So he said, "Well, inform me about its signs." He said, "They are that the slave-girl will give birth to her mistress and that you will see the barefooted ones, the naked, the destitute, the herdsmen of the sheep (competing with each other) in raising lofty buildings." Thereupon the man went off. I waited a while, and then he (the Prophet) said, "O `Umar, do you know who that questioner was?" I replied, "Allah and His Messenger know better." He said, "That was Jibril. He came to teach you your religion." [Muslim]', '40 Hadith Nawawi, Hadith 2'),
('bukhari:6461', 'Narrated Masruq:I asked `Aisha "What deed was the most beloved to the Prophet?" She said, "The regular constant one." I said, "At what time did he use to get up at night (for the Tahajjud night prayer)?'' She said, "He used to get up on hearing (the crowing of) the cock (the last third of the night)', 'Sahih al-Bukhari 6461'),
('bukhari:6468', 'Narrated Anas bin Malik:Once Allah''s Messenger (ﷺ) led us in prayer and then (after finishing it) ascended the pulpit and pointed with his hand towards the Qibla of the mosque and said, "While I was leading you in prayer, both Paradise and Hell were displayed in front of me in the direction of this wall. I had never seen a better thing (than Paradise) and a worse thing (than Hell) as I have seen today, I had never seen a better thing and a worse thing as I have seen today', 'Sahih al-Bukhari 6468'),
('bukhari:57', 'Narrated Jarir bin Abdullah: I gave the pledge of allegiance to Allah''s Messenger (ﷺ) for the following: 1. offer prayers perfectly 2. pay the Zakat (obligatory charity) 3. and be sincere and true to every Muslim', 'Sahih al-Bukhari 57'),
('bukhari:6479', 'Narrated Abu Huraira:The Prophet (ﷺ) said Allah will give shade to seven (types of people) under His Shade (on the Day of Resurrection). (one of them will be) a person who remembers Allah and his eyes are then flooded with tears', 'Sahih al-Bukhari 6479'),
('qudsi:23', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah will say on the Day of Resurrection: Where are those who love one another through My glory? Today I shall give them shade in My shade, it being a day when there is no shade but My shade. It was related by al-Bukhari (also by Malik)', '40 Hadith Qudsi, Hadith 23'),
('qudsi:31', 'On the authority of Jundub (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) related: A man said: By Allah, Allah will not forgive So-and-so. At this Allah the Almighty said: Who is he who swears by Me that I will not forgive So-and-so? Verily I have forgiven So-and-so and have nullified your [own good] deeds (1) (or as he said [it]). (1) A similar Hadith, which is given by Abu Dawud, indicates that the person referred to was a goldly man whose previous good deeds were brought to nought through presuming to declare that Allah would not forgive someone''s bad deeds. It was related by Muslim', '40 Hadith Qudsi, Hadith 31'),
('bukhari:6457', 'Narrated Qatada:We used to go to Anas bin Malik and see his baker standing (preparing the bread). Anas said, "Eat. I have not known that the Prophet (ﷺ) ever saw a thin well-baked loaf of bread till he died, and he never saw a roasted sheep with his eyes', 'Sahih al-Bukhari 6457'),
('bukhari:118', 'Narrated Abu Huraira:People say that I have narrated many Hadiths (The Prophet''s narration). Had it not been for two verses in the Qur''an, I would not have narrated a single Hadith, and the verses are: "Verily those who conceal the clear sign and the guidance which We have sent down . . . (up to) Most Merciful." (2:159-160). And no doubt our Muhajir (emigrant) brothers used to be busy in the market with their business (bargains) and our Ansari brothers used to be busy with their property (agriculture). But I (Abu Huraira) used to stick to Allah''s Messenger (ﷺ) contented with what will fill my stomach and I used to attend that which they used not to attend and I used to memorize that which they used not to memorize', 'Sahih al-Bukhari 118'),
('bukhari:87', 'Narrated Abu Jamra:I was an interpreter between the people and Ibn `Abbas. Once Ibn `Abbas said that a delegation of the tribe of `Abdul Qais came to the Prophet (ﷺ) who asked them, "Who are the people (i.e. you)? (Or) who are the delegates?" They replied, "We are from the tribe of Rabi`a." Then the Prophet (ﷺ) said to them, "Welcome, O people (or said, "O delegation (of `Abdul Qais).") Neither will you have disgrace nor will you regret." They said, "We have come to you from a distant place and there is the tribe of the infidels of Mudar intervening between you and us and we cannot come to you except in the sacred month. So please order us to do something good (religious deeds) and that we may also inform our people whom we have left behind (at home) and that we may enter Paradise (by acting on them.)" The Prophet ordered them to do four things, and forbade them from four things. He ordered them to believe in Allah Alone, the Honorable the Majestic and said to them, "Do you know what is meant by believing in Allah Alone?" They replied, "Allah and His Apostle know better." Thereupon the Prophet (ﷺ) said, "(That means to testify that none has the right to be worshipped but Allah and that Muhammad is His Apostle, to offer prayers perfectly, to pay Zakat, to observe fasts during the month of Ramadan, (and) to pay Al-Khumus (one fifth of the booty to be given in Allah''s cause)." Then he forbade them four things, namely Ad-Dubba.'' Hantam, Muzaffat (and) An-Naqir or Muqaiyar (These were the names of pots in which alcoholic drinks used to be prepared). The Prophet (ﷺ) further said, "Memorize them (these instructions) and tell them to the people whom you have left behind', 'Sahih al-Bukhari 87'),
('qudsi:8', 'On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: A prayer performed by someone who has not recited the Essence of the Quran (1) during it is deficient (and he repeated the word three times), incomplete. Someone said to Abu Hurayrah: [Even though] we are behind the imam? (2) He said: Recite it to yourself, for I have heard the Prophet (may the blessings and peace of Allah be up on him) say: Allah (mighty and sublime be He), had said: I have divided prayer between Myself and My servant into two halves, and My servant shall have what he has asked for. When the servant says: Al-hamdu lillahi rabbi l-alamin (3), Allah (mighty and sublime be He) says: My servant has praised Me. And when he says: Ar-rahmani r-rahim (4), Allah (mighty and sublime be He) says: My servant has extolled Me, and when he says: Maliki yawmi d-din (5), Allah says: My servant has glorified Me - and on one occasion He said: My servant has submitted to My power. And when he says: Iyyaka na budu wa iyyaka nasta in (6), He says: This is between Me and My servant, and My servant shall have what he has asked for. And when he says: Ihdina s-sirata l- mustaqim, siratal ladhina an amta alayhim ghayril-maghdubi alayhim wa la d-dallin (7), He says: This is for My servant, and My servant shall have what he has asked for. (1) Surat al-Fatihah, the first surah (chapter) of the Qur''an. (2) i.e. standing behind the imam (leader) listening to him reciting al-Fatihah. (3) "Praise be to Allah, Lord of the Worlds." (4) "The Merciful, the Compassionate". (5) "Master of the Day of Judgement". (6) "It is You we worship and it is You we ask for help". (7) "Guide us to the straight path, the path of those upon whom You have bestowed favors, not of those against whom You are angry, nor of those who are astray". It was related by Muslim (also by Malik, at-Tirmidhi, Abu-Dawud, an-Nasa''i and Ibn Majah)', '40 Hadith Qudsi, Hadith 8'),
('bukhari:6459', 'Narrated `Aisha:that she said to `Urwa, "O, the son of my sister! We used to see three crescents in two months, and no fire used to be made in the houses of Allah''s Messenger (ﷺ) (i.e. nothing used to be cooked)." `Urwa said, "What used to sustain you?" `Aisha said, "The two black things i.e. dates and water, except that Allah''s Messenger (ﷺ) had neighbors from the Ansar who had some milch she-camels, and they used to give the Prophet (ﷺ) some milk from their house, and he used to make us drink it', 'Sahih al-Bukhari 6459'),
('qudsi:26', 'On the authority of Abu Umamah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: Truly of those devoted to Me the one I most favor is a believer who is of meager means and much given to prayer, who has been particular in the worship of his Lord and has obeyed Him inwardly[1], who was obscure among people and not pointed out, and whose sustenance was just sufficient to provide for him yet he bore this patiently. Then the Prophet (ﷺ) shook his hand and said: Death will have come early to him, his mourners will have been few, his estate scant. [1] i.e. he has not been ostentatious in his obedience. It was related by at-Tirmidhi (also by Ahmad ibn Hanbal and Ibn Majah). Its chain of authorities is sound', '40 Hadith Qudsi, Hadith 26'),
('bukhari:89', 'Narrated `Umar:My Ansari neighbor from Bani Umaiya bin Zaid who used to live at `Awali Al-Medina and I used to visit the Prophet (ﷺ) by turns. He used to go one day and I another day. When I went I used to bring the news of that day regarding the Divine Inspiration and other things, and when he went, he used to do the same for me. Once my Ansari friend, in his turn (on returning from the Prophet), knocked violently at my door and asked if I was there." I became horrified and came out to him. He said, "Today a great thing has happened." I then went to Hafsa and saw her weeping. I asked her, "Did Allah''s Messenger (ﷺ) divorce you all?" She replied, "I do not know." Then, I entered upon the Prophet (ﷺ) and said while standing, "Have you divorced your wives?" The Prophet (ﷺ) replied in the negative. On that I said, "Allahu-Akbar (Allah is Greater)." (See Hadith No. 119, Vol. 3 for details)', 'Sahih al-Bukhari 89'),
('bukhari:11', 'Narrated Abu Musa: Some people asked Allah''s Messenger (ﷺ), "Whose Islam is the best? i.e. (Who is a very good Muslim)?" He replied, "One who avoids harming the Muslims with his tongue and hands', 'Sahih al-Bukhari 11'),
('bukhari:6427', 'Narrated Abu Sa`id Al-Khudri:Allah''s Messenger (ﷺ) said, "The thing I am afraid of most for your sake, is the worldly blessings which Allah will bring forth to you." It was said, "What are the blessings of this world?" The Prophet (ﷺ) said, "The pleasures of the world." A man said, "Can the good bring forth evil?" The Prophet (ﷺ) kept quiet for a while till we thought that he was being inspired divinely. Then he started removing the sweat from his forehead and said," Where is the questioner?" That man said, "I (am present)." Abu Sa`id added: We thanked the man when the result (of his question) was such. The Prophet (ﷺ) said, "Good never brings forth but good. This wealth (of the world) is (like) green and sweet (fruit), and all the vegetation which grows on the bank of a stream either kills or nearly kills the animal that eats too much of it, except the animal that eats the Khadira (a kind of vegetation). Such an animal eats till its stomach is full and then it faces the sun and starts ruminating and then it passes out dung and urine and goes to eat again. This worldly wealth is (like) sweet (fruit), and if a person earns it (the wealth) in a legal way and spends it properly, then it is an excellent helper, and whoever earns it in an illegal way, he will be like the one who eats but is never satisfied', 'Sahih al-Bukhari 6427'),
('bukhari:6587', 'Narrated Abu Huraira:The Prophet (ﷺ) said, "While I was sleeping, a group (of my followers were brought close to me), and when I recognized them, a man (an angel) came out from amongst (us) me and them, he said (to them), ''Come along.'' I asked, ''Where?'' He said, ''To the (Hell) Fire, by Allah'' I asked, ''what is wrong with them'' He said, ''They turned apostate as renegades after you left.'' Then behold! (Another) group (of my followers) were brought close to me, and when I recognized them, a man (an angel) came out from (me and them) he said (to them); Come along.'' I asked, "Where?'' He said, ''To the (Hell) Fire, by Allah.'' I asked, What is wrong with them?'' He said, ''They turned apostate as renegades after you left. So I did not see anyone of them escaping except a few who were like camels without a shepherd', 'Sahih al-Bukhari 6587'),
('bukhari:6514', 'Narrated Anas bin Malik:Allah''s Messenger (ﷺ) said, "When carried to his grave, a dead person is followed by three, two of which return (after his burial) and one remains with him: his relative, his property, and his deeds follow him; relatives and his property go back while his deeds remain with him', 'Sahih al-Bukhari 6514'),
('bukhari:120', 'Narrated Abu Huraira:I have memorized two kinds of knowledge from Allah''s Messenger (ﷺ) . I have propagated one of them to you and if I propagated the second, then my pharynx (throat) would be cut (i.e. killed)', 'Sahih al-Bukhari 120'),
('bukhari:6499', 'Narrated Jundub:The Prophet (ﷺ) said, "He who lets the people hear of his good deeds intentionally, to win their praise, Allah will let the people know his real intention (on the Day of Resurrection), and he who does good things in public to show off and win the praise of the people, Allah will disclose his real intention (and humiliate him)', 'Sahih al-Bukhari 6499'),
('qudsi:29', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) says: My faithful servant''s reward from Me, if I have taken to Me his best friend from amongst the inhabitants of the world and he has then borne it patiently for My sake, shall be nothing less than Paradise. It was related by al-Bukhari', '40 Hadith Qudsi, Hadith 29'),
('qudsi:10', 'On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (mighty and sublime be He) says: Fasting is Mine and it is I who give reward for it. [A man] gives up his sexual passion, his food and his drink for my sake. Fasting is like a shield, and he who fasts has two joys: a joy when he breaks his fast and a joy when he meets his Lord. The change in the breath of the mouth of him who fasts is better in Allah''s estimation than the smell of musk. It was related by al-Bukhari (also by Muslim, Malik, at-Tirmidhi, an-Nasa''i and Ibn Majah)', '40 Hadith Qudsi, Hadith 10'),
('nawawi:25', 'Also on the authority of Abu Dharr (may Allah be pleased with him): Some people from amongst the Companions of the Messenger of Allah (peace and blessings of Allah be upon him) said to the Prophet (peace and blessings of Allah be upon him), "O Messenger of Allah, the affluent have made off with the rewards; they pray as we pray, they fast as we fast, and they give [much] in charity by virtue of their wealth." He (peace and blessings of Allah be upon him) said, "Has not Allah made things for you to give in charity? Truly every tasbeehah [saying: ''subhan-Allah''] is a charity, and every takbeerah [saying: ''Allahu akbar''] is a charity, and every tahmeedah [saying: ''al-hamdu lillah''] is a charity, and every tahleelah [saying: ''laa ilaha illAllah''] is a charity. And commanding the good is a charity, and forbidding an evil is a charity, and in the bud`i [sexual act] of each one of you there is a charity." They said, "O Messenger of Allah, when one of us fulfils his carnal desire will he have some reward for that?" He (peace and blessings of Allah be upon him) said, "Do you not see that if he were to act upon it [his desire] in an unlawful manner then he would be deserving of punishment? Likewise, if he were to act upon it in a lawful manner then he will be deserving of a reward." [Muslim]', '40 Hadith Nawawi, Hadith 25'),
('bukhari:109', 'Narrated Salama:I heard the Prophet (ﷺ) saying, "Whoever (intentionally) ascribes to me what I have not said then (surely) let him occupy his seat in Hell-fire', 'Sahih al-Bukhari 109'),
('bukhari:6573', 'Narrated Abu Huraira:Some people said, "O Allah''s Messenger (ﷺ)! Shall we see our Lord on the Day of Resurrection?" He said, "Do you crowd and squeeze each other on looking at the sun when it is not hidden by clouds?" They replied, "No, Allah''s Messenger (ﷺ)." He said, "Do you crowd and squeeze each other on looking at the moon when it is full and not hidden by clouds?" They replied, No, O Allah''s Messenger (ﷺ)!" He said, "So you will see Him (your Lord) on the Day of Resurrection similarly Allah will gather all the people and say, ''Whoever used to worship anything should follow that thing. ''So, he who used to worship the sun, will follow it, and he who used to worship the moon will follow it, and he who used to worship false deities will follow them; and then only this nation (i.e., Muslims) will remain, including their hypocrites. Allah will come to them in a shape other than they know and will say, ''I am your Lord.'' They will say, ''We seek refuge with Allah from you. This is our place; (we will not follow you) till our Lord comes to us, and when our Lord comes to us, we will recognize Him. Then Allah will come to then in a shape they know and will say, "I am your Lord.'' They will say, ''(No doubt) You are our Lord,'' and they will follow Him. Then a bridge will be laid over the (Hell) Fire." Allah''s Messenger (ﷺ) added, "I will be the first to cross it. And the invocation of the Apostles on that Day, will be ''Allahumma Sallim, Sallim (O Allah, save us, save us!),'' and over that bridge there will be hooks Similar to the thorns of As Sa''dan (a thorny tree). Didn''t you see the thorns of As-Sa''dan?" The companions said, "Yes, O Allah''s Messenger (ﷺ)." He added, "So the hooks over that bridge will be like the thorns of As-Sa-dan except that their greatness in size is only known to Allah. These hooks will snatch the people according to their deeds. Some people will be ruined because of their evil deeds, and some will be cut into pieces and fall down in Hell, but will be saved afterwards, when Allah has finished the judgments among His slaves, and intends to take out of the Fire whoever He wishes to take out from among those who used to testify that none had the right to be worshipped but Allah. We will order the angels to take them out and the angels will know them by the mark of the traces of prostration (on their foreheads) for Allah banned the f ire to consume the traces of prostration on the body of Adam''s son. So they will take them out, and by then they would have burnt (as coal), and then water, called Ma''ul Hayat (water of life) will be poured on them, and they will spring out like a seed springs out on the bank of a rainwater stream, and there will remain one man who will be facing the (Hell) Fire and will say, ''O Lord! It''s (Hell''s) vapor has Poisoned and smoked me and its flame has burnt me; please turn my face away from the Fire.'' He will keep on invoking Allah till Allah says, ''Perhaps, if I give you what you want), you will ask for another thing?'' The man will say, ''No, by Your Power, I will not ask You for anything else.'' Then Allah will turn his face away from the Fire. The man will say after that, ''O Lord, bring me near the gate of Paradise.'' Allah will say (to him), ''Didn''t you promise not to ask for anything else? Woe to you, O son of Adam ! How treacherous you are!'' The man will keep on invoking Allah till Allah will say, ''But if I give you that, you may ask me for something else.'' The man will say, ''No, by Your Power. I will not ask for anything else.'' He will give Allah his covenant and promise not to ask for anything else after that. So Allah will bring him near to the gate of Paradise, and when he sees what is in it, he will remain silent as long as Allah will, and then he will say, ''O Lord! Let me enter Paradise.'' Allah will say, ''Didn''t you promise that you would not ask Me for anything other than that? Woe to you, O son of Adam ! How treacherous you are!'' On that, the man will say, ''O Lord! Do not make me the most wretched of Your creation,'' and will keep on invoking Allah till Allah will smile and when Allah will smile because of him, then He will allow him to enter Paradise, and when he will enter Paradise, he will be addressed, ''Wish from so-and-so.'' He will wish till all his wishes will be fulfilled, then Allah will say, All this (i.e. what you have wished for) and as much again therewith are for you.'' " Abu Huraira added: That man will be the last of the people of Paradise to enter (Paradise)', 'Sahih al-Bukhari 6573'),
('bukhari:21', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever possesses the following three qualities will taste the sweetness of faith: 1. The one to whom Allah and His Apostle become dearer than anything else. 2. Who loves a person and he loves him only for Allah''s sake. 3. Who hates to revert to disbelief (Atheism) after Allah has brought (saved) him out from it, as he hates to be thrown in fire', 'Sahih al-Bukhari 21'),
('nawawi:1', 'It is narrated on the authority of Amirul Mu''minin, Abu Hafs ''Umar bin al-Khattab (ra) who said: I heard the Messenger of Allah (ﷺ) say: "Actions are (judged) by motives (niyyah), so each man will have what he intended. Thus, he whose migration (hijrah) was to Allah and His Messenger, his migration is to Allah and His Messenger; but he whose migration was for some worldly thing he might gain, or for a wife he might marry, his migration is to that for which he migrated." [Bukhari & Muslim]', '40 Hadith Nawawi, Hadith 1'),
('bukhari:6543', 'Narrated Sahl bin Sa`d:The Prophet (ﷺ) said, "Seventy-thousand or seven-hundred thousand of my followers (the narrator is in doubt as to the correct number) will enter Paradise holding each other till the first and the last of them enter Paradise at the same time, and their faces will have a glitter like that of the moon at night when it is full', 'Sahih al-Bukhari 6543'),
('bukhari:127', 'Narrated Abu at-Tufail:The above mentioned Statement of `Ali', 'Sahih al-Bukhari 127'),
('bukhari:119', 'Narrated Abu Huraira:I said to Allah''s Messenger (ﷺ) "I hear many narrations (Hadiths) from you but I forget them." Allah''s Apostle said, "Spread your Rida'' (garment)." I did accordingly and then he moved his hands as if filling them with something (and emptied them in my Rida'') and then said, "Take and wrap this sheet over your body." I did it and after that I never forgot any thing. Narrated Ibrahim bin Al-Mundhir: Ibn Abi Fudaik narrated the same as above (Hadith...119) but added that the Prophet (ﷺ) had moved his hands as if filling them with something and then he emptied them in the Rida'' of Abu Huraira', 'Sahih al-Bukhari 119'),
('bukhari:55', 'Narrated Abu Mas''ud: The Prophet (ﷺ) said, "If a man spends on his family (with the intention of having a reward from Allah) sincerely for Allah''s sake then it is a (kind of) alms-giving in reward for him', 'Sahih al-Bukhari 55'),
('bukhari:23', 'Narrated Abu Said Al-Khudri: Allah''s Messenger (ﷺ) said, "While I was sleeping I saw (in a dream) some people wearing shirts of which some were reaching up to the breasts only while others were even shorter than that. Umar bin Al-Khattab was shown wearing a shirt that he was dragging." The people asked, "How did you interpret it? (What is its interpretation) O Allah''s Messenger (ﷺ)?" He (the Prophet (ﷺ) ) replied, "It is the Religion', 'Sahih al-Bukhari 23'),
('bukhari:24', 'Narrated ''Abdullah (bin ''Umar): Once Allah''s Messenger (ﷺ) passed by an Ansari (man) who was admonishing his brother regarding Haya''. On that Allah''s Messenger (ﷺ) said, "Leave him as Haya'' is a part of faith." (See Hadith)', 'Sahih al-Bukhari 24'),
('bukhari:6501', 'Narrated Anas:The Prophet (ﷺ) had a she-camel called Al-`Adba'' and it was too fast to surpass in speed. There came a bedouin riding a camel of his, and that camel outstripped it (i.e. Al-Aqba''). That result was hard on the Muslims who said sorrowfully, "Al- Adba has been outstripped." Allah''s Messenger (ﷺ) said, "It is due from Allah that nothing would be raised high in this world except that He lowers or puts it down', 'Sahih al-Bukhari 6501'),
('bukhari:6588', 'Narrated Abu Huraira:Allah''s Messenger (ﷺ) said, "Between my house and my pulpit there is a garden from amongst the gardens of Paradise, and my pulpit is over my Lake-Fount', 'Sahih al-Bukhari 6588'),
('bukhari:52', 'Narrated An-Nu''man bin Bashir: I heard Allah''s Messenger (ﷺ) saying, ''Both legal and illegal things are evident but in between them there are doubtful (suspicious) things and most of the people have no knowledge about them. So whoever saves himself from these suspicious things saves his religion and his honor. And whoever indulges in these suspicious things is like a shepherd who grazes (his animals) near the Hima (private pasture) of someone else and at any moment he is liable to get in it. (O people!) Beware! Every king has a Hima and the Hima of Allah on the earth is His illegal (forbidden) things. Beware! There is a piece of flesh in the body if it becomes good (reformed) the whole body becomes good but if it gets spoilt the whole body gets spoilt and that is the heart', 'Sahih al-Bukhari 52'),
('bukhari:6564', 'Narrated Abu Sa`id Al-Khudri:I heard Allah''s Messenger (ﷺ) when his uncle, Abu Talib had been mentioned in his presence, saying, "May be my intercession will help him (Abu Talib) on the Day of Resurrection so that he may be put in a shallow place in the Fire, with fire reaching his ankles and causing his brain to boil', 'Sahih al-Bukhari 6564'),
('nawawi:39', 'On the authority of Ibn Abbas (may Allah be pleased with him), that the Messenger of Allah (peace and blessings of Allah be upon him) said: Verily Allah has pardoned [or been lenient with] for me my ummah: their mistakes, their forgetfulness, and that which they have been forced to do under duress. A hasan hadeeth related by Ibn Majah, and al-Bayhaqee and others', '40 Hadith Nawawi, Hadith 39'),
('bukhari:60', 'Narrated `Abdullah bin `Amr:Once the Prophet (ﷺ) remained behind us in a journey. He joined us while we were performing ablution for the prayer which was over-due. We were just passing wet hands over our feet (and not washing them properly) so the Prophet (ﷺ) addressed us in a loud voice and said twice or thrice: "Save your heels from the fire', 'Sahih al-Bukhari 60'),
('qudsi:28', 'On the authority of Jundub ibn Abdullah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: There was amongst those before you a man who had a wound. He was in [such] anguish that he took a knife and made with it a cut in his hand, and the blood did not cease to flow till he died. Allah the Almighty said: My servant has himself forestalled Me; I have forbidden him Paradise. It was related by al-Bukhari', '40 Hadith Qudsi, Hadith 28'),
('bukhari:79', 'Narrated Abu Musa:The Prophet (ﷺ) said, "The example of guidance and knowledge with which Allah has sent me is like abundant rain falling on the earth, some of which was fertile soil that absorbed rain water and brought forth vegetation and grass in abundance. (And) another portion of it was hard and held the rain water and Allah benefited the people with it and they utilized it for drinking, making their animals drink from it and for irrigation of the land for cultivation. (And) a portion of it was barren which could neither hold the water nor bring forth vegetation (then that land gave no benefits). The first is the example of the person who comprehends Allah''s religion and gets benefit (from the knowledge) which Allah has revealed through me (the Prophet) and learns and then teaches others. The last example is that of a person who does not care for it and does not take Allah''s guidance revealed through me (He is like that barren land)', 'Sahih al-Bukhari 79'),
('bukhari:122', 'Narrated Sa`id bin Jubair:I said to Ibn `Abbas, "Nauf-Al-Bakali claims that Moses (the companion of Khadir) was not the Moses of Bani Israel but he was another Moses." Ibn `Abbas remarked that the enemy of Allah (Nauf) was a liar. Narrated Ubai bin Ka`b: The Prophet (ﷺ) said, "Once the Prophet Moses (ﷺ) stood up and addressed Bani Israel. He was asked, "Who is the most learned man amongst the people. He said, "I am the most learned." Allah admonished Moses as he did not attribute absolute knowledge to Him (Allah). So Allah inspired to him "At the junction of the two seas there is a slave amongst my slaves who is more learned than you." Moses said, "O my Lord! How can I meet him?" Allah said: Take a fish in a large basket (and proceed) and you will find him at the place where you will lose the fish. So Moses set out along with his (servant) boy, Yusha` bin Noon and carried a fish in a large basket till they reached a rock, where they laid their heads (i.e. lay down) and slept. The fish came out of the basket and it took its way into the sea as in a tunnel. So it was an amazing thing for both Moses and his (servant) boy. They proceeded for the rest of that night and the following day. When the day broke, Moses said to his (servant) boy: "Bring us our early meal. No doubt, we have suffered much fatigue in this journey." Moses did not get tired till he passed the place about which he was told. There the (servant) boy told Moses, "Do you remember when we betook ourselves to the rock, I indeed forgot the fish." Moses remarked, "That is what we have been seeking. So they went back retracing their footsteps, till they reached the rock. There they saw a man covered with a garment (or covering himself with his own garment). Moses greeted him. Al-Khadir replied saying, "How do people greet each other in your land?" Moses said, "I am Moses." He asked, "The Moses of Bani Israel?" Moses replied in the affirmative and added, "May I follow you so that you teach me of that knowledge which you have been taught." Al-Khadir replied, "Verily! You will not be able to remain patient with me, O Moses! I have some of the knowledge of Allah which He has taught me and which you do not know, while you have some knowledge which Allah has taught you which I do not know." Moses said, "Allah willing, you will find me patient and I will disobey no order of yours. So both of them set out walking along the seashore, as they did not have a boat. In the meantime a boat passed by them and they requested the crew of the boat to take them on board. The crew recognized Al-Khadir and took them on board without fare. Then a sparrow came and stood on the edge of the boat and dipped its beak once or twice in the sea. Al-Khadir said: "O Moses! My knowledge and your knowledge have not decreased Allah''s knowledge except as much as this sparrow has decreased the water of the sea with its beak." Al- Khadir went to one of the planks of the boat and plucked it out. Moses said, "These people gave us a free lift but you have broken their boat and scuttled it so as to drown its people." Al-Khadir replied, "Didn''t I tell you that you will not be able to remain patient with me." Moses said, "Call me not to account for what I forgot." The first (excuse) of Moses was that he had forgotten. Then they proceeded further and found a boy playing with other boys. Al-Khadir took hold of the boy''s head from the top and plucked it out with his hands (i.e. killed him). Moses said, "Have you killed an innocent soul who has killed none." Al-Khadir replied, "Did I not tell you that you cannot remain patient with me?" Then they both proceeded till when they came to the people of a town, they asked them for food, but they refused to entertain them. Then they found there a wall on the point of collapsing. Al-Khadir repaired it with his own hands. Moses said, "If you had wished, surely you could have taken wages for it." Al-Khadir replied, "This is the parting between you and me." The Prophet added, "May Allah be Merciful to Moses! Would that he could have been more patient to learn more about his story with Al-Khadir', 'Sahih al-Bukhari 122'),
('bukhari:133', 'Narrated Nafi`:`Abdullah bin `Umar said: "A man got up in the mosque and said: ''O Allah''s Messenger (ﷺ) At which place you order us that we should assume the Ihram?'' Allah''s Messenger (ﷺ) replied, ''The residents of Medina should assure the Ihram from Dhil-Hulaifa, the people of Syria from Al-Juhfa and the people of Najd from Qarn." Ibn `Umar further said, "The people consider that Allah''s Messenger (ﷺ) had also said, ''The residents of Yemen should assume Ihram from Yalamlam.'' " Ibn `Umar used to say, "I do not remember whether Allah''s Messenger (ﷺ) had said the last statement or not', 'Sahih al-Bukhari 133'),
('bukhari:6425', 'Narrated `Amr bin `Auf:(An ally of the tribe of Bani ''Amir bin Lu''ai and one of those who had witnessed the battle of Badr with Allah''s Messenger (ﷺ)) Allah''s Messenger (ﷺ) sent Abu ''Ubaida bin AlJarrah to Bahrain to collect the Jizya tax. Allah''s Messenger (ﷺ) had concluded a peace treaty with the people of Bahrain and appointed Al ''Ala bin Al-Hadrami as their chief; Abu Ubaida arrived from Bahrain with the money. The Ansar heard of Abu ''Ubaida''s arrival which coincided with the Fajr (morning) prayer led by Allah''s Messenger (ﷺ). When the Prophet (ﷺ) finished the prayer, they came to him. Allah''s Messenger (ﷺ) smiled when he saw them and said, "I think you have heard of the arrival of Abu ''Ubaida and that he has brought something." They replied, "Yes, O Allah''s Messenger (ﷺ)! " He said, "Have the good news, and hope for what will please you. By Allah, I am not afraid that you will become poor, but I am afraid that worldly wealth will be given to you in abundance as it was given to those (nations) before you, and you will start competing each other for it as the previous nations competed for it, and then it will divert you (from good) as it diverted them', 'Sahih al-Bukhari 6425'),
('qudsi:30', 'On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: If My servant likes to meet Me, I like to meet him; and if he dislikes to meet Me, I dislike to meet him. Prophetic explanation of this Sacred Hadith: He who likes to meet Allah, Allah likes to meet him; and he who dislikes to meet Allah, Allah dislikes to meet him. Aishah (may Allah be pleased with her) said: O Prophet (ﷺ) of Allah, is it because of the dislike of death, for all of us dislike death? The Prophet (ﷺ) said: It is not so, but rather it is that when the believer is given news of Allah''s mercy, His approval and His Paradise, he likes to meet Allah and Allah likes to meet him; but when the unbeliever is given news of Allah''s punishment and His displeasure, he dislikes to meet Allah and Allah dislikes to meet him. It was related by al-Bukhari and Malik. The Prophetic version is related by Muslim', '40 Hadith Qudsi, Hadith 30'),
('bukhari:20', 'Narrated ''Aisha: Whenever Allah''s Messenger (ﷺ) ordered the Muslims to do something, he used to order them deeds which were easy for them to do, (according to their strength and endurance). They said, "O Allah''s Messenger (ﷺ)! We are not like you. Allah has forgiven your past and future sins." So Allah''s Apostle became angry and it was apparent on his face. He said, "I am the most Allah fearing, and know Allah better than all of you do', 'Sahih al-Bukhari 20'),
('bukhari:65', 'Narrated Anas bin Malik:Once the Prophet (ﷺ) wrote a letter or had an idea of writing a letter. The Prophet (ﷺ) was told that they (rulers) would not read letters unless they were sealed. So the Prophet (ﷺ) got a silver ring made with "Muhammad Allah''s Messenger (ﷺ)" engraved on it. As if I were just observing its white glitter in the hand of the Prophet', 'Sahih al-Bukhari 65'),
('nawawi:20', 'On the authority of Abu Masood Uqbah bin ’Amr al-Ansaree al-Badree (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Verily, from what was learnt by the people from the speech of the earliest prophecy is: If you feel no shame, then do as you wish.” [Al-Bukhari]', '40 Hadith Nawawi, Hadith 20')
) as v(reference, text, attribution)
join public.hadiths h on h.reference = v.reference
on conflict (hadith_id, locale) do nothing;